window.__LEX={"G3900":"<h1>paraptoma</h1>\n<p>Strong n° 3900 <i>Prononciation [par-ap'-to-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tomber à côté de ou près de quelque chose</li>\n<li>une faute ou déviation par rapport à la vérité et la droiture\n<ol type=\"a\">\n<li>un péché, une faute, une erreur, un méfait</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παράπτωμα, ατος (τὸ) :<br>      1</b> échec, revers, DS. <i>19, 100 ;</i><br><b>      2</b> faute, erreur, SPT. <i>Ps. 18, 13, etc. ;</i> POL. <i>9, 10, 6 ;</i> LGN <i>36, 2 ;</i><br><b>      3</b> dérogation à, violation de, SPT. <i>Ezech. 14, 13 ;</i> NT. <i>Matth. 6, 14 ;</i> GAL. <i>6, 1, etc</i>.<br><span><b>Étym</b>. παραπίπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραπτωμα - παράπτωμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 19 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Romains (9)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (3)</li>\n<li>Colossiens (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G3901":"<h1>pararrhueo</h1>\n<p>Strong n° 3901 <i>Prononciation [par-ar-hroo-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>glisser, être emporté par : de peur que ... nous ne soyons emportés\n<ol type=\"a\">\n<li>emporté loin de nous</li>\n<li>une chose qui m'échappe</li>\n<li>effleure mon esprit</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·ρρέω</b> <span>(<i>f</i>. -ρρεύσομαι, <i>ao.2</i> παρερρύην, <i>pf</i>. παρερρύηκα)</span><br><b>   I</b> couler devant <i>ou</i> le long de :<br><b>      1</b> <i>au propre,</i> XÉN. <i>Cyr. 4, 5, 2 ;</i> παρὰ τὸν νεών, XÉN. <i>An. 5, 3, 8,</i> devant le temple ; τινι, XÉN. <i>An. 4, 4, 11,</i> tomber auprès de qqn, <i>en parl. de neige ;</i> couler <i>ou</i> glisser le long de, s’échapper des mains, <i>d’où</i> s’égarer, être oublié, SOPH. <i>Ph. 652 ;</i><br><b>      2</b> <i>fig. avec un suj. de pers</i>. passer le long de, <i>càd</i>. passer sans faire attention, SPT. <i>Prov. 3, 11 ;</i> NT. <i>Hebr. 2, 1 ;</i> π. φρενῶν, EUP. (STOB. <i>Fl. 4, 33</i>) perdre ses esprits ; <i>avec un suj. de. chose :</i> π. τινι, PLAT. <i>Leg. 781</i> a, <i>ou</i> τινα, CLÉM. <i>324,</i> échapper à qqn ;<br><b>   II</b> arriver en coulant, <i>d’où</i> couler à travers, s’infiltrer, se glisser, pénétrer ; <i>au propre avec</i> παρά <i>et l’acc</i>. ARSTT. <i>P.A. 3, 3, 6, en parl. de pers. ; avec</i> εἰς <i>et l’acc</i>. PLUT. <i>M. 969</i> e ; <i>en parl. de choses (fausse monnaie, bruits, etc</i>.) PLUT. <i>M. 94</i> c ; πρός τινα, DÉM. <i>170, 25,</i> pénétrer jusqu’à qqn.<br><span><b>Étym</b>. π. ῥέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραρρυεω - παραρρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3902":"<h1>parasemos</h1>\n<p>Strong n° 3902 <i>Prononciation [par-as'-ay-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>marqué faussement, faux, contrefait : comme de la monnaie</li>\n<li>marqué à côté ou dans la marge\n<ol type=\"a\">\n<li>les mots remarquables, que le lecteur d'un livre marque dans la marge</li>\n</ol>\n</li>\n<li>noté, marqué, en évidence, remarquable\n<ol type=\"a\">\n<li>de personnes dans un mauvais sens, notoire</li>\n</ol>\n</li>\n<li>marqué d'un signe : un navire marqué par l'image ou l'enseigne des Dioscures (Castor et Pollux)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρά·σημος, ος, ον :<br>      1</b> marqué faussement, marqué d’un signe de mauvais aloi : π. νόμισμα, PLUT. <i>M. 65</i> a, fausse monnaie ; <i>p. anal. en parl. de pers</i>. AR. <i>Ach. 518 ;</i> PLUT. <i>M. 4</i> c ; <i>en parl. d’un mauvais orateur,</i> DÉM. <i>307, 26 ; de même en parl. de choses :</i> π. δόξα, EUR. <i>Hipp. 1116,</i> opinion fausse, <i>p. opp. à</i> ἀτρεκής ; <i>cf</i>. ESCHL. <i>Ag. 780, etc. ;</i><br><b>      2</b> annoté, <i>d’où</i> étrange, extraordinaire, <i>en parl. de mots, de constructions, etc</i>. ANTH. <i>11, 144 ;</i> PLUT. <i>M. 1010</i> d ; <i>joint à</i> σολοικόν, PLUT. <i>Alex. 46 ; p. suite,</i> qui se fait remarquer, <i>d’ord. en mauv. part ;</i> τινι, PLUT. <i>M. 823</i> b, par qqe ch. ; π. ἐστιν <i>avec un part</i>. PLUT. <i>Brut. 2,</i> qui se fait remarquer par.<br><span><b>Étym</b>. l’affectation de, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρασημος - παράσημος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3903":"<h1>paraskeuazo</h1>\n<p>Strong n° 3903 <i>Prononciation [par-ask-yoo-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se rendre prêt, se préparer</li>\n<li>s'être préparé, être préparé ou prêt</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·σκευάζω</b> <span>(<i>f</i>. άσω, <i>ao</i>. παρεσκεύασα, <i>pf</i>. παρεσκεύακα, <i>etc</i>.)</span><br><b>      1</b> préparer, apprêter, disposer : τι, HDT. <i>9, 82, etc. ;</i> LYS. <i>Agor. § 26 ;</i> AR. <i>Ach. 1176, etc</i>. qqe ch. (un repas, des navires, <i>etc</i>.) ; <i>au pass</i>. être préparé, XÉN. <i>An. 5, 2, 13 ; impers</i>. οἱ Κορίνθιοι, ἐπειδὴ αὐτοῖς παρεσκεύαστο, ἔπλεον, THC. <i>1, 46,</i> lorsque tout fut prêt, les Corinthiens prirent la mer ; <i>avec double rég. :</i> τῇ νηῒ ἄλφιτα καὶ οἶνον π. THC. <i>3, 49,</i> garnir un navire de provisions de farine et de vin ; τινὶ π. τι, PLAT. <i>Rsp. 369</i> e, <i>etc</i>. procurer qqe ch. à qqn<br><i><b>Moy</b>. :</i><br><b>   I <i>tr.</i></b> préparer <i>ou</i> disposer pour soi : σῖτα καὶ ποτά, HDT. <i>5, 34,</i> à manger et à boire ; κλίμακας, XÉN. <i>Cyr. 7, 2, 1,</i> des échelles ; τὰ πολέμια, THC. <i>1, 18,</i> se préparer à la guerre ; στρατιάν, THC. <i>4, 70,</i> préparer une expédition ; ἑκατὸν νεῶν ἐπίπλουν, THC. <i>2, 56,</i> préparer une expédition de cent vaisseaux ; ὅπερ πάλαι παρεσκευαζόμην, AR. <i>Pl. 410,</i> ce que je poursuivais depuis longtemps, ce à quoi je songeais depuis longtemps ;<br><b>   II <i>intr</i>.<br>      1</b> se préparer, s’apprêter, se disposer, se tenir tout prêt : παρ. οἴκαδε, XÉN. <i>An. 7, 7, 57,</i> se préparer pour le retour dans la patrie ; π. ἐς μάχην, HDT. <i>9, 99 ;</i> ἐς πολιορκίην, HDT. <i>3, 105,</i> se préparer pour un combat, pour un siège ; <i>avec</i> πρός <i>et l’acc</i>. THC. <i>3, 69, etc. ; avec</i> ἐν <i>et le dat</i>. ARR. <i>Epict. 2, 6, 3 ;</i> ὡς εἰς μάχην, XÉN. <i>An. 1, 8, 1,</i> comme pour la bataille, comme si. l’on en devait venir à une bataille ; <i>avec un inf</i>. se disposer à faire, être prêt à faire, ESCHL. <i>Sept. 440, etc. ;</i> AR. <i>Av. 227, etc. ;</i> THC. <i>3, 110, etc. ; avec</i> ὥστε <i>et l’inf</i>. EUR. <i>H.f. 1241 ; avec</i> ὅπως <i>et l’ind. fut</i>. THC. <i>3, 99 ; avec</i> ὡς <i>et le part. fut</i>. HDT. <i>2, 162, etc. ;</i> XÉN. <i>Cyr. 5, 4, 42, etc. ; rar. sans</i> ὡς : παρεσκευάζετο προπηλακιῶν αὐτόν, THC. <i>6, 54, litt</i>. il se préparait à le couvrir de boue, <i>càd</i>. à lui faire un affront ; <i>cf</i>. XÉN. <i>Hell. 4, 1, 41 ; avec</i> ὡς <i>et le gén. ou l’acc. abs. :</i> παρασκευάζεσθαι ὡς μάχης ἐσομένης, XÉN. <i>Hell. 4, 2, 18,</i> se préparer comme si un combat devait avoir lieu ; <i>cf</i>. XÉN. <i>Cyr. 3, 2, 8 ;</i><br><b>      2</b> <i>en mauv. part :</i> intriguer, IS. <i>79, 7 ;</i><br><b>      3</b> préparer en vue de, disposer pour, rendre apte à : παρεσκεύασεν ὁ θεὸς τὴν τῆς γυναικὸς φύσιν ἐπὶ τὰ ἔνδον ἔργα καὶ ἐπιμελήματα, XÉN. <i>Œc. 7, 22,</i> la divinité a approprié la nature de la femme aux travaux et aux soins de l’intérieur ; εὖ παρεσκευασμένοι καὶ τὰς ψυχὰς καὶ τὰ σώματα. XÉN. <i>Œc. 5, 13,</i> dispos de corps et d’âme ; <i>avec</i> ὅπως <i>et le fut</i>. XÉN. <i>An. 5, 4, 21 ;</i> PLAT. <i>Ap. 39</i> d ; <i>avec</i> ὡς <i>et le part. :</i> οὕτω τὰ σώματα καὶ τὴν γνώμην παρασκευάζοιντο ὡς ἀγωνιούμενοι, XÉN. <i>Hell. 3, 4, 20,</i> qu’ils se préparent de corps et d’âme comme pour combattre ; <i>cf</i>. XÉN. <i>Cyr. 2, 1, 11 ; avec</i> ὡς <i>et l’inf. :</i> οὕτω δοκοῦμεν παρεσκευάσθαι, ὡς ἱκανοὶ εἶναι ὑμᾶς εὖ ποιεῖν, XÉN. <i>Cyr. 4, 2, 13,</i> il nous semble que nous sommes en mesure de pouvoir vous rendre service ; <i>avec</i> ὡς <i>et l’ind</i>. XÉN. <i>An. 6, 3, 17, etc. ; avec l’inf. seul :</i> π. τὸν βίον μηδὲν δεῖσθαι δικαστοῦ, PLAT. <i>Rsp. 405</i> c, arranger sa vie de façon à n’avoir pas besoin de juge ; <i>impers. :</i> τούτῳ ἄριστα παρεσκεύασται ζῆν, PLAT. <i>Menex. 248</i> a, il s’est arrangé pour vivre le mieux possible ; <i>avec un acc. accompagné d’un attrib. :</i> τοὺς θεοὺς ἵλεως αὑτῷ, PLAT. <i>Leg. 803</i> e, se rendre les dieux favorables ; εὐσεϐέστερόν τινα, XÉN. <i>Mem. 4, 3, 17,</i> rendre qqn plus pieux ;<br><b>      4</b> <i>en mauv. part,</i> pousser à qqe mauvaise action, IS. <i>69, 1 ;</i> ANT. <i>114, 25 ; particul</i>. suborner des témoins, DÉM. <i>1141, 23</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pl.q.pf. pass. 3 pl. ion</i>. παρεσκευάδατο, HDT. <i>3, 150, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρασκευαζω - παρασκευάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G3904":"<h1>paraskeue</h1>\n<p>Strong n° 3904 <i>Prononciation [par-ask-yoo-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui rend prêt, préparation, action d'équiper</li>\n<li>ce qui est préparé, équipement</li>\n<li>dans le N.T. dans un sens Juif, le jour de préparation\n<ol type=\"a\">\n<li>le jour où les Juifs faisaient la préparation nécessaire pour célébrer un sabbat ou une fête</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρασκευή, ῆς (ἡ) :<br>A</b> <i>act. :</i><br><b>   I</b> action de préparer, préparation :<br><b>      1</b> <i>en gén</i>. π. δείπνου, HDT. <i>9, 82 ;</i> σίτου, HDT. <i>3, 25 ;</i> τῆς τροφῆς, PLAT. <i>Rsp. 369</i> e, préparation d’un repas, du blé, de la nourriture ; ὅλη ἡ τοῦ ζῆν π. PLAT. <i>Pol. 207</i> e, toute la conduite de la vie, toute l’économie de la vie ; παρασκευὴν παρασκευάζεσθαι, ARR. <i>Epict. 2, 2, 10, etc</i>. prendre ses dispositions, se préparer ;<br><b>      2</b> préparatifs de guerre, armement, équipement : νεῶν, AR. <i>Ach. 190,</i> d’une flotte ; τὸ ναυτικὸν ἐν παρασκευῇ ἦν, THC. <i>2, 80,</i> on préparait la flotte, on appareillait ; μάχη ἐκ παρασκευῆς, THC. <i>5, 56,</i> bataille préparée, <i>p. opp. à</i> ἐνέδραι καὶ καταδρομαί ;<br><b>      3</b> préparation à un discours, PLUT. <i>Dem. 8, 9 ; particul</i>. préparation faite habilement, <i>p. opp. à</i> αὐτοσχεδιασμός, ALEX. <i>π. σχημ. p. 576 ;</i> action de préparer les auditeurs dans un récit, de rendre attentif, DH. <i>Is. 15 ; Rhet. 10, 13 ;</i> ce qu’on met dans le discours pour chercher à se concilier par avance l’auditeur, RUFIN. <i>Fig. 32 ;</i><br><b>      4</b> <i>chez les Juifs,</i> le jour qui précède le sabbat, NT. <i>Marc. 15, 42 ; Joh. 19, 14, etc. ; Luc. 23, 54 ;</i> ἡ μεγάλη <i>ou</i> ἁγία π. ECCL. le vendredi saint ;<br><b>B</b> <i>pass. :</i><br><b>   I</b> ce qui a été préparé, ce qui est à la disposition de, <i>d’où :</i><br><b>      1</b> <i>en gén</i>. appareil, équipage, XÉN. <i>Cyr. 8, 3, 4 ;</i> PLAT. <i>Rsp. 495</i> a,<br><b>      2</b> ce qui a été préparé, équipement, armement, THC. <i>2, 100 ;</i> ISOCR. <i>217</i> d ; <i>particul</i>. équipement d’un général, HDT. <i>9, 82 ;</i><br><b>      3</b> <i>dans un procès,</i> préparatifs, efforts des parties pour gagner le procès ; <i>particul</i>. dispositions prises par l’accusé pour échapper à la peine, LYCURG. <i>150, 20 ;</i> LYS. <i>152, 10, etc. ;</i><br><b>      4</b> cabale, intrigue, menées, ANT. <i>138, 36 ;</i> DÉM. <i>444, 22, etc. ;</i> ἐκ παρασκευῆς, LYS. <i>189, 34 ;</i> ἀπὸ παρασκευῆς, LYS. <i>162, 23,</i> avec calcul <i>ou</i> préméditation (<i>ttef</i>. ἐκ παρασκευῆς, <i>etc</i>. selon les conventions) ESCHN. <i>64, 13 ;</i> ἀπὸ παρασκευῆς οὐδεμιᾶς, ANT. <i>132, 5,</i> sans aucune préméditation ;<br><b>   II</b> le fait d’être préparé à qqe ch., <i>d’où</i> disposition naturelle, qualités, ressources, THC. <i>1, 1 ;</i> PLAT. <i>Gorg. 510</i> e, <i>513</i> d, <i>etc. ;</i><br><b>   III</b> approche, arrivée de la fièvre, DIOSC. <i>5, 29</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρασκευη - παρασκευή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G3905":"<h1>parateino</h1>\n<p>Strong n° 3905 <i>Prononciation [par-at-i'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étendre à côté de, s'étendre en longueur, continuer</li>\n<li>prolonger (son discours)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·τείνω</b> <span>(<i>f</i>. -τενῶ, <i>ao</i>. παρέτεινα, <i>pf</i>. παρατέτακα <span>[τᾰ]</span>)</span><br><b>A <i>tr</i>.<br>   I</b> étendre à côté, développer, <i>acc</i>. HDT. <i>1, 185 ;</i> PLUT. <i>Cam. 33 ; d’où</i> tirer en longueur, amplifier, <i>acc</i>. ARSTT. <i>Poet. 17, 5 ;</i> π. ὀνόματα ; LUC. <i>Luct. 13,</i> prononcer lentement les mots ; π. τὰ τελευταῖα τῆς φωνῆς, LUC. <i>Demon. 3,</i> prolonger les derniers sons de la voix, <i>en parl. d’une chambre construite d’une certaine façon ;</i><br><b>   II</b> tendre le long de, <i>particul. :</i><br><b>      1</b> étendre sur le chevalet, <i>d’où</i> torturer, PLUT. <i>M. 135</i> d, <i>etc. ; p. suite au pass</i>. périr, mourir : λιμῷ, PLAT. <i>Conv. 207</i> b ; πόθῳ, PLUT. <i>Sol. 7,</i> de faim, de désir ; <i>avec un part. :</i> γελῶντε παρετάθησαν, PLAT. <i>Euthyd. 303</i> b, tous deux faillirent mourir de rire ;<br><b>      2</b> <i>t. de méd</i>. détendre, <i>d’où</i> rendre (le ventre) libre, PHILIST. (ATH. <i>115</i> e) ;<br><b>      3</b> <i>t. de math</i>. construire une figure de géométrie sur une ligne donnée, PLAT. <i>Men. 87</i> a, <i>Rsp. 527</i> a ;<br><b>   III</b> traîner en longueur, <i>d’où :</i><br><b>      1</b> amuser, retenir, faire attendre : τινά, XÉN. <i>Cyr. 1, 3, 11,</i> qqn ; <i>au pass</i>. PLUT. <i>M. 195</i> d ;<br><b>      2</b> prolonger : βίον ἕως, <i>gén</i>. PLUT. <i>M. 832</i> e ; LUC. <i>Macr. 3,</i> prolonger sa vie jusqu’à, <i>etc. ;</i><br><b>      3</b> ajourner, différer, <i>acc</i>. LUC. <i>Ic. 29 ; au pass</i>. LUC. <i>D. mort. 4, 2 ;</i><br><b>B <i>intr</i>.<br>      1</b> s’étendre, <i>en parl. d’un lieu, avec l’acc. du lieu jusqu’où s’étend une région,</i> HDT. <i>1, 203 ;</i> THC. <i>4, 8 ;</i> παρά τι, POL. <i>6, 31, 5,</i> le long de qqe ch. (d’une côte, d’une île, <i>etc</i>.) ; <i>avec le dat</i>. STR. <i>335 ;</i><br><b>      2</b> se prolonger, durer, demeurer longtemps : ἐς ἔτη τινά, APP. <i>Syr. 48, etc</i>. se prolonger jusqu’à un certain nombre d’années ; <i>avec un part. :</i> ποῖ παρατενεῖς δεδιὼς ταῦτα ; PHILSTR. <i>302,</i> jusques à quand veux-tu persister à craindre cela ? ;<br><b><i>Moy.</i></b> s’étendre le long de, <i>en parl. de lieux, de pays, etc. dat</i>. HDT. <i>2, 8 ;</i> AR. <i>Nub. 212</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρατεινω - παρατείνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3906":"<h1>paratereo</h1>\n<p>Strong n° 3906 <i>Prononciation [par-at-ay-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se trouver à côté et veiller, veiller assidûment, observer attentivement\n<ol type=\"a\">\n<li>veiller, faire attention avec les yeux</li>\n<li>des augures, voir ce qui va arriver</li>\n<li>dans un mauvais sens, veiller d'une manière insidieuse</li>\n<li>prendre garde à soi</li>\n<li>observer, tenir scrupuleusement\n<ol>\n<li>ne rien négliger de ce qui est requis par la religion</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·τηρέω-ῶ :<br>      1</b> observer en se tenant auprès, épier, surveiller, XÉN. <i>Mem. 3, 14, 4 ;</i> ARSTT. <i>H.A. 9, 34 ; p. suite,</i> se tenir en garde contre, <i>acc</i>. POL. <i>3, 77, 2 ;</i><br><b>      2</b> surveiller, suivre à la piste, DC. <i>53, 10 ;</i> π. ἵνα, DH. <i>Dem. 53,</i> veiller à ce que, <i>etc. ;</i> π. ὅπως μή, DÉM. <i>281, 16,</i> prendre garde que… ne pas ;<br><b>      3</b> observer, garder (la mesure) ARSTT. <i>Rhet. 3, 3 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> observer, épier, surveiller, <i>acc</i>. SPT. <i>Ps. 86, 12 ;</i> NT. <i>Luc. 14, 1 ;</i><br><b>      2</b> faire attention à, <i>acc</i>. NT. <i>Gal. 4, 10 ; d’où</i> observer (la loi, <i>etc.) acc</i>. DC. <i>33, 10</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρατηρεω - παρατηρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Actes (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G3907":"<h1>parateresis</h1>\n<p>Strong n° 3907 <i>Prononciation [par-at-ay'-ray-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>observation attentive, action de déceler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρατήρησις, εως (ἡ) :<br>      1</b> observation des astres, des augures, etc. DS. <i>1, 28, etc. ;</i> contemplation, NT. <i>Luc. 17, 20 ;</i><br><b>      2</b> action d’épier, surveillance, POL. <i>16, 22, 8 ;</i> PLUT. <i>M. 266</i> a ;<br><b>      3</b> <i>t. de gr</i>. observation, remarque, LGN <i>23</i>.<br><span><b>Étym</b>. παρατηρέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρατηρησις - παρατήρησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3908":"<h1>paratithemi</h1>\n<p>Strong n° 3908 <i>Prononciation [par-at-ith'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>placer à côté ou près ou poser devant\n<ol type=\"a\">\n<li>nourriture (la nourriture placée sur une table)</li>\n<li>mettre devant quelqu'un pour son enseignement</li>\n<li>présenter, expliquer</li>\n</ol>\n</li>\n<li>remettre, de soi-même ou pour soi-même\n<ol type=\"a\">\n<li>déposer</li>\n<li>confier, remettre une charge, une fonction à quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·τίθημι</b>, placer auprès, <i>d’où :</i><br><b>      1</b> offrir, présenter : δίφρον, OD. <i>21, 182,</i> un siège ; τράπεζαν, OD. <i>5, 92, etc</i>. placer la table devant celui qu’on veut traiter, <i>particul</i>. faire servir sur la table, <i>acc</i>. OD. <i>1, 192, etc. ;</i> AR. <i>Ach. 85, etc. ;</i> PLAT. <i>Rsp. 372</i> d ; <i>abs</i>. οἱ παρατιθέντες, XÉN. <i>Cyr. 8, 8, 20,</i> ceux qui servent à table, les servants ; τὰ παρατιθέμενα, XÉN. <i>Cyr. 2, 1, 3 ;</i> ARSTT. <i>Pol. 1, 6,</i> les mets servis sur la table ;<br><b>      2</b> présenter, offrir : τινί τι, IL. <i>11, 779 ; 8, 408 ;</i> OD. <i>9, 517,</i> qqe ch. à qqn ; στέφανον καρήατι, HÉS. <i>Th. 577,</i> déposer une couronne sur la tête de qqn (<i>propr</i>. l’approcher de la tête) ; <i>avec un inf</i>. τινὶ ἀναγιγνώσκειν τι, PLAT. <i>Prot. 325</i> e, donner à qqn qqe ch. à lire ; τινὸς ἀπογεύσασθαι, PLAT. <i>Theæt. 157</i> c, donner à goûter qqe ch. ; <i>fig</i>. exposer, raconter, <i>acc</i>. XÉN. <i>Cyr. 1, 6, 14 ;</i> NT. <i>Matth. 13, 24 ; particul</i>. citer un auteur, un passage, DH. <i>Dem. 37, Comp. 23, etc. ;</i><br><b>      3</b> procurer : δύναμίν τινι, OD. <i>3, 205,</i> procurer la puissance à qqn ;<br><b>      4</b> mettre sous la garde de, remettre, confier : τινί τι, NT. <i>Ap. 20, 32,</i> qqe ch. à qqn ;<br><b>      5</b> mettre à côté : ἀντωνυμίαις, DYSC. <i>Synt. p. 131, 27,</i> à côté de pronoms, <i>en parl. de prépositions, comme dans</i> παρ' ἐμοῦ ; <i>d’où</i> mettre en parallèle, comparer : τινά τινι, PLUT. <i>Demetr. 12, 45 ;</i> τι πρός τι, LUC. <i>Pr. 15,</i> une personne <i>ou</i> une chose à une autre ;<br><b><i>Moy.</i></b> placer devant soi <i>ou</i> faire placer devant soi, <i>d’où :</i><br><b>      1</b> se servir <i>ou</i> se faire servir des mets sur la table, EUR. <i>Cycl. 390 ;</i> XÉN. <i>Cyr. 8, 6, 12,</i> se faire présenter des flambeaux, OD. <i>2, 105 ; 19, 150 ; 24, 140, etc. ;</i><br><b>      2</b> attribuer : χωρίῳ ὄνομα, PAUS. <i>2, 14, 4,</i> un nom à un pays ;<br><b>      3</b> déposer qqe ch. de soi <i>ou</i> pour soi, déposer en garde <i>ou</i> en gage : τὰ χρήματα, HDT. <i>6, 86, etc</i>. sa fortune ; τὴν οὐσίαν τινί, XÉN. <i>Ath. 2, 16,</i> son avoir entre les mains de qqn, <i>d’où en gén</i>. remettre, confier, recommander : τί τινι, PLUT. <i>Num. 9, M. 325</i> a, confier qqe ch. à qqn ; <i>ou</i> εἰς χεῖράς τινος, NT. <i>Luc. 23, 46,</i> aux mains de qqn ; τινα θεῷ, NT. <i>Ap. 14, 23,</i> qqn à Dieu ;<br><b>      4</b> produire au jour, citer, alléguer : τι, PLAT. <i>Pol. 257</i> b, <i>279</i> a ; PLUT. <i>M. 833</i> d, qqe preuve <i>ou</i> témoignage ;<br><b>      5</b> mettre de côté pour soi, mettre en réserve : τι, PLUT. <i>Per. 26,</i> qqe ch. ; τι εἴς τι, POL. <i>3, 17, 10,</i> qqe ch. en vue d’un besoin ;<br><b>      6</b> exposer à un risque : κεφαλήν, OD. <i>2, 337 ; ou</i> ψυχήν, OD. <i>3, 74 ; 9, 255,</i> sa tête <i>ou</i> sa vie.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. 3 sg. épq</i>. παρτιθεῖ, OD. <i>1, 192 ; impf. 2 sg</i>. παρετίθεις, AR. <i>Ach. 85 ; 3 sg</i>. παρετίθει, AR. <i>Eq. 1223 ; ao.2 3 pl. épq</i>. πάρθεσαν, OD. <i>4, 66 ; moy. ao.2 part. poét</i>. παρθέμενοι, OD. <i>2, 337 ; 3, 74 ; 9, 255</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρατιθημι - παρατίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 18 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (4)</li>\n<li>Luc (5)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3909":"<h1>paratugchano</h1>\n<p>Strong n° 3909 <i>Prononciation [par-at-oong-khan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être là par hasard, se trouver présent, rencontrer par chance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·τυγχάνω</b> <span>(<i>f</i>. -τεύξομαι, <i>ao.2</i> παρέτυχον, <i>pf</i>. παρατετύχηκα <i>ou</i> παρατέτευχα)</span> se trouver auprès de, à portée de, <i>en parl. de pers. dat</i>. IL. <i>11, 74 ;</i> HDT. <i>7, 236 ; 9, 107 ;</i> PLAT. <i>Prot. 340</i> e ; POL. <i>3, 70, 7, etc. ; en parl. de choses,</i> THC. <i>4, 19 ; 8, 11 ;</i> λαϐόντες ὅ τι ἑκάστῳ παρέτυχεν ὅπλον, PLAT. <i>Rsp. 474</i> a, tous deux ayant pris l’arme qui se trouvait sous la main de chacun, <i>càd</i>. la première venue ; <i>au part. abs</i>. HDT. <i>1, 59 ; 6, 108 ;</i> ὁ παρατυχών, THC. <i>1, 22 ;</i> XÉN. <i>Cyr. 1, 4, 18,</i> celui qui se trouve à portée, le premier venu ; πρὸς τὸ παρατυγχάνον, THC. <i>1, 122,</i> selon les circonstances ; ἐκ τοῦ παρατυχόντος, PLUT. <i>M. 154</i> a ; ἐν τῷ παρατυχόντι, THC. <i>5, 38,</i> selon l’occasion, sur-le-champ, à l’instant même ; παρατυχόν, <i>avec l’inf</i>. THC. <i>1, 76 ; 5, 60,</i> lorsque l’occasion se présente de, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. παρατετύχηκα, PLAT. <i>Prot. 340</i> e ; <i>postér</i>. παρατέτευχα, POL. <i>12, 27, 8</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρατυγχανω - παρατυγχάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3910":"<h1>parautika</h1>\n<p>Strong n° 3910 <i>Prononciation [par-ow-tee'-kah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pour le moment, en cet instant, au moment présent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·αυτίκα</b> <span>[ῐᾰ]</span> <i>adv</i>., à l’instant même, sur-le-champ, aussitôt : π. εὐθέως, POL. <i>35, 4, 13, m. sign. ;</i> τὸ παραυτίκα, HDT. <i>1, 19, etc. ; m. sign. ;</i> ἐκ τοῦ π. PLUT. <i>Cor. 20 ;</i> ἐν τῷ π. (<i>s.-e</i>. χρόνῳ) THC. <i>2, 11 ;</i> PLAT. <i>Phædr. 240</i> b, <i>m. sign. ; enclavé entre l’art. et le nom :</i> ἡ π. ἐλπίς, THC. <i>8, 82,</i> l’espérance du moment ; τὸ π. ἡδύ, PLAT. <i>Phædr. 239</i> a, le plaisir du moment.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραυτικα - παραυτίκα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3911":"<h1>paraphero</h1>\n<p>Strong n° 3911 <i>Prononciation [par-af-er'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>porter à, emporter, emmener, apporter à, mettre devant</li>\n<li>mener hors du droit chemin, amener au loin</li>\n<li>éloigner\n<ol type=\"a\">\n<li>faire dévier, enlever</li>\n<li>se laisser entraîner, séduire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·φέρω</b> <span>(<i>f</i>. παροίσω, <i>ao.1</i> παρήνεγκα, <i>etc</i>.)</span><br><b>A <i>tr</i>.<br>   I</b> porter auprès : λαμπάδας τινί, EUR. <i>Hel. 724,</i> porter des flambeaux auprès de qqn escorter qqn avec des flambeaux ;<br><b>   II</b> porter devant, <i>d’où :</i><br><b>      1</b> <i>propr</i>. apporter : ξύνθημά τινι, EUR. <i>Ph. 1140,</i> apporter un mot d’ordre à qqn ; <i>au pass</i>. se porter en avant, s’approcher, <i>en parl. de poissons,</i> ARSTT. <i>H.A. 4, 8 ;</i><br><b>      2</b> mettre sur la table, servir : τί τινι, HDT. <i>1, 119 ;</i> XÉN. <i>Cyr. 1, 3, 6,</i> qqe ch. à qqn ; τὸ παραφερόμενον, PLAT. <i>Rsp. 354</i> b, <i>ou</i> τὰ παραφερόμενα, LUC. <i>M. cond. 26,</i> les mets qu’on sert ;<br><b>      3</b> produire, faire paraître : τινά, ESCHN. <i>18, 37,</i> qqn ; <i>particul</i>. produire sur la scène, SCH.-AR. <i>Ran. 994 ; fig</i>. λόγους, EUR. <i>I.A. 981,</i> prononcer des paroles ; νόμον, ANT. <i>124, 39,</i> citer une loi ; πίστεις, DH. <i>7, 27,</i> alléguer des témoignages ;<br><b>   III</b> porter en passant devant, au delà de, <i>d’où au pass</i>. être porté <i>ou</i> se porter en passant devant, dépasser, PLUT. <i>Mar. 35 ;</i><br><b>   IV</b> l’emporter sur, surpasser : τινά τινι, LUC. <i>Charid. 19 ;</i> ARSTD. <i>t. 1, 127,</i> qqn en qqe ch. ;<br><b>   V</b> porter de côté, mouvoir, mouvoir de côté, <i>acc</i>. DÉM. <i>305, 5 ; en parl. de membres paralysés,</i> PLUT. <i>Cam. 41 ;</i> ARSTT. <i>Nic. 1, 13, 16 ; d’un homme ivre,</i> DL. <i>7, 183 ; p. suite :</i><br><b>      1</b> emmener, emporter, entraîner, <i>acc</i>. PLUT. <i>Tim. 28, M. 432</i> a, <i>etc. ;</i><br><b>      2</b> détourner, <i>acc. :</i> τινὸς π. τὴν ὄψιν, XÉN. <i>Cyn. 5, 27,</i> diriger sa vue à côté de qqe ch., <i>càd</i>. passer à côté d’une chose sans la voir ;<br><b>      3</b> emporter hors du droit chemin, faire dévier, <i>d’où au pass</i>. se laisser entraîner hors du droit chemin, s’égarer, PLAT. <i>Phil. 60</i> d, <i>etc. ; fig</i>. avoir l’esprit égaré, HPC. <i>217</i> h ;<br><b>      4</b> interpréter faussement, détourner le sens d’une chose, <i>acc</i>. PLUT. <i>M. 15, 41</i> d ;<br><b>      5</b> changer, réformer, <i>acc</i>. APP. <i>Civ. 3, 61 ; en mauv. part,</i> dénaturer, altérer, <i>acc</i>. APP. <i>Civ. 2, 68 ;</i><br><b>      6</b> mettre de côté, écarter, négliger, dédaigner, <i>acc</i>. ORACL. (DÉM. <i>531, 16</i>) ; PLUT. <i>Arat. 43 ;</i><br><b>B <i>intr</i>.<br>      1</b> passer outre, s’écouler, <i>en parl. du temps,</i> THC. <i>5, 20, 26 ;</i><br><b>      2</b> s’écarter de, différer de : τινός, DH. <i>1, 28,</i> de qqe ch. ; παρά τι, DC. <i>59, 5,</i> par comparaison avec qqe ch. ; <i>abs</i>. être différent, altéré, changé, CON. <i>26</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. poét</i>. πάρφερε, SOPHR. <i>48 Ahrens ; ind. pass</i>. παρφέρομαι, ANTH. <i>11, 26</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραφερω - παραφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G3912":"<h1>paraphroneo</h1>\n<p>Strong n° 3912 <i>Prononciation [par-af-ron-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être à côté de soi-même, hors de sens, dénué de compréhension, insensé, aliéné, avoir l'esprit dérangé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παραφρονέω-ῶ</b>, être hors de son bon sens, déraisonner, être fou, HDT. <i>1, 109, etc. ;</i> HPC. <i>Progn. 39 ;</i> ESCHL. <i>Sept. 806 ;</i> SOPH. <i>Ph. 815, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. παραιφρονέω, THCR. <i>Idyl. 25, 262</i>.<br><span><b>Étym</b>. παράφρων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραφρονεω - παραφρονέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3913":"<h1>paraphronia</h1>\n<p>Strong n° 3913 <i>Prononciation [par-af-ron-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>folie, démence</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παραφρονία, ας (ἡ)</b> <i>c</i>. παραφρόνησις NT. <i>2Petr. 2, 16</i>.<br><br>\n<b>παραφρόνησις, εως (ἡ)</b> délire, folie, SPT. <i>Zach. 12, 4</i>.<br><span><b>Étym</b>. παραφρονέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραφρονια - παραφρονία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3914":"<h1>paracheimazo</h1>\n<p>Strong n° 3914 <i>Prononciation [par-akh-i-mad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>hiverner, passer l'hiver, avec quelqu'un ou dans un lieu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·χειμάζω</b>, passer l’hiver qqe part, hiverner, DÉM. <i>909, 14 ; 1293, 4 ;</i> HYPÉR. (PHOT.) ; PLUT. <i>Sert. 3, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραχειμαζω - παραχειμάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G3915":"<h1>paracheimasia</h1>\n<p>Strong n° 3915 <i>Prononciation [par-akh-i-mas-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>action de passer l'hiver, d'hiverner, un hivernage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παραχειμασία, ας (ἡ)</b> <span>[μᾰ]</span> quartiers d’hiver, POL. <i>3, 35, 1 ;</i> DS. <i>14, 38, etc</i>.<br><span><b>Étym</b>. παραχειμάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραχειμασια - παραχειμασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3916":"<h1>parachrema</h1>\n<p>Strong n° 3916 <i>Prononciation [par-akh-ray'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>immédiatement, sur-le-champ, tout-de-suite, à l'instant, instantanément</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρα·χρῆμα</b>, <i>adv</i>., sur le fait, sur-le-champ, à l’instant même, HDT. <i>3, 15 ; 7, 150 ;</i> THC. <i>7, 75 ;</i> LYS. <i>172, 44, etc. ;</i> ταχὺ παραχρῆμα, PLAT. <i>Theag. 129</i> e ; εὐθὺς παραχρῆμα (<i>v</i>. εὐθύς) <i>m. sign. ;</i> τὸ παραχρῆμα, HDT. <i>6, 11 ;</i> PLAT. <i>Crat. 395</i> d, ce qui arrive présentement ; εἰς τὸ π. THC. <i>1, 22 ;</i> PLAT. <i>Leg. 646</i> c, pour le moment ; ἐκ τοῦ π. XÉN. <i>Hell. 6, 4, 11 ;</i> PLAT. <i>Crat. 399</i> d ; DÉM. <i>9, 7 ; ou</i> ἀπὸ τοῦ π. XÉN. <i>Hell. 1, 1, 30,</i> sur-le-champ, à l’improviste, sans préparation ; ἐν τῷ π. PLAT. <i>Rsp. 455</i> a, en ce moment, pour le moment ; <i>enclavé entre l’article et le nom :</i> ἡ π. ἀνάγκη, THC. <i>2, 17,</i> la nécessité du moment présent ; αἱ π. ἡδοναί, PLAT. <i>Prot. 356</i> b, les plaisirs du moment ; <i>postér. avec le gén</i>. παραχρῆμα τοῦ λαϐεῖν, GEOP. <i>10, 75, 16,</i> au moment même <i>ou</i> juste au moment de prendre.<br><span><b>Étym</b>. π. χρῆμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παραχρημα - παραχρῆμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 19 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (10)</li>\n<li>Actes (7)</li>\n</ul>\n</td></tr>\n</table>","G3917":"<h1>pardalis</h1>\n<p>Strong n° 3917 <i>Prononciation [par'-dal-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un léopard, une panthère</li>\n<li>un animal Asiatique et Africain très féroce, à la peau fauve et basanée, marquée de grandes taches noires</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πάρδαλις, εως (ἡ)</b> <span>[δᾰ]</span><br><b>      1</b> panthère <i>ou</i> léopard, IL. <i>13, 103 ; 17, 20 ; 21, 573 ;</i> OD. <i>4, 457 ;</i> AR. <i>Nub. 346 ;</i> PLAT. <i>Lach. 196</i> e ;<br><b>      2</b> sorte de requin tacheté, EL. <i>N.A. 9, 4 ;</i> OPP. <i>H. 1, 368</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. ion</i>. -ιος, OPP. <i>l. c</i>. (<i>cf</i>. πόρδαλις).</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρδαλις - πάρδαλις</font>\n<br><br>vient de pardos (une panthère)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3918":"<h1>pareimi</h1>\n<p>Strong n° 3918 <i>Prononciation [par'-i-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être là, être auprès, être arrivé, être présent</li>\n<li>être prêt, en magasin</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πάρ·ειμι</b> <span>(<i>impf</i>. παρῆν, <i>att</i>. παρῆ <i>f</i>. παρέσομαι)</span><br><b>A</b> être présent : <i>avec un nom de pers. pour suj. :</i><br><b>   I</b> être présent, <i>abs</i>. IL. <i>2, 485, etc. ;</i> HDT. <i>7, 12 ;</i> SOPH. <i>El. 1197, etc. ; avec un dat :</i> π. μάχῃ, OD. <i>4, 497,</i> assister à la bataille ; τοῖς πράγμασι, DÉM. <i>10, 2,</i> être présent <i>ou</i> assister aux événements ; <i>avec une prép. :</i> π. ἐν ταῖς συνουσίαις, PLAT. <i>Prot. 335</i> b, assister aux réunions, π. ἐπὶ πᾶσι, XÉN. <i>Cyr. 4, 5, 44,</i> être présent à tout ; π. παρά τινι, SOPH. <i>Ph. 1057 ;</i> PLAT. <i>Phædr. 243</i> e, se trouver auprès de qqn ;<br><b>   II</b> <i>p. suite,</i> être aux côtés de, à l’aide de, assister, secourir (<i>cf. lat</i>. adesse, præsens sum) : τινι, IL. <i>18, 472 ;</i> OD. <i>13, 393 ;</i> ESCHL. <i>Pers. 235 ;</i> EUR. <i>Or. 1159 ;</i> DÉM. <i>911, 6, etc</i>. qqn ;<br><b>   III</b> <i>avec idée d’un mouv. antér. :</i><br><b>      1</b> être venu et se trouver présent, <i>avec</i> εἰς <i>et l’acc</i>. HDT. <i>1, 9, etc. ;</i> XÉN. <i>Cyr. 6, 2, 40, etc. ; avec</i> επί <i>et l’acc</i>. XÉN. <i>Cyr. 8, 3, 2, etc. ; avec</i> πρός <i>et l’acc</i>. XÉN. <i>Cyr. 2, 4, 21, etc. ; avec un acc. de lieu :</i> EUR. <i>Cycl. 85, 106, etc. ; avec double rég. :</i> π. τινι ἐπὶ δεῖπνον, HDT. <i>1, 118,</i> être venu et se trouver chez qqn pour un repas ;<br><b>      2</b> <i>joint à des mots exprimant l’idée d’un point de départ :</i> τοὐκ θεοῦ παρόν, SOPH. <i>O.C. 1540,</i> (signe) envoyé par un dieu ; Φίλιππος ἐκ Θρᾴκης π. ESCHN. <i>41, 21,</i> voici Philippe revenu de Thrace ; <i>avec double rég. de mouv. :</i> π. ἐκ πόλιος εἰς Ἀσίην, HDT. <i>6, 24,</i> être arrivé d’une ville en Asie ;<br><b>B</b> <i>avec un nom de chose pour suj. :</i> être présent, être à la disposition de, <i>dat</i>. IL. <i>1, 213, etc. ;</i> OD. <i>14, 80, etc. ;</i> HDT. <i>5, 106, etc. ;</i> εἴ μοι δύναμίς γε παρείη, IL. <i>22, 20, etc</i>. si j’en avais le pouvoir à ma disposition, si j’avais la puissance, si je pouvais ; ὅση δύναμίς γε πάρεστι, IL. <i>8, 294, etc. ;</i> OD. <i>23, 128,</i> autant qu’il est en mon pouvoir, autant que je le peux ; ὁ παρὼν νῦν χρόνος, SOPH. <i>El. 1293,</i> le temps présent ; <i>p. opp. à</i> ὁ παρεληλυθώς, ESCHN. <i>13, 19 ;</i> ἡ νῦν παροῦσα ἡμέρα, PLAT. <i>Leg. 683</i> c, le jour présent ; <i>subst</i>. τὸ παρόν, SOPH. <i>Ph. 149 ;</i> PLAT. <i>Gorg. 499</i> c ; τὸ παρεόν, HDT. <i>1, 20,</i> le présent, les circonstances présentes, la situation actuelle ; <i>plur</i>. τὰ παρόντα, <i>ion</i>. παρεόντα, ce qui est présent, <i>càd</i>. les choses à portée (provisions toutes prêtes, <i>etc</i>.) OD. <i>1, 140 ; 4, 56, etc. ; ou en gén</i>. les circonstances présentes, la situation actuelle, HDT. <i>1, 113 ; p. opp. à</i> τὰ γεγονότα <i>et à</i> τὰ μέλλοντα, PLAT. <i>Theæt. 186</i> a, <i>etc. ; adv</i>. τὰ παρόντα, à présent, dans le présent, maintenant, SOPH. <i>El. 215 ;</i> τῷ παρόντι, THC. <i>2, 88, etc. ;</i> XÉN. <i>An. 2, 5, 8 ;</i> ἐν τῷ τότε παρόντι, THC. <i>1, 95 ;</i> ἐν τῷ νῦν παρόντι, PLAT. <i>Phæd. 67</i> c, <i>m. sign. ;</i> ἐκ τῶν παρόντων, THC. <i>5, 40, etc. ;</i> XÉN. <i>An. 3, 2, 3, etc</i>. selon les circonstances présentes, par suite des circonstances actuelles ;<br><b>C</b> <i>impers</i>. πάρεστί μοι, il dépend de moi, il est en mon pouvoir, je puis ; <i>avec l’inf</i>. ESCHL. <i>Eum. 867 ;</i> SOPH. <i>Aj. 332 ;</i> HDT. <i>8, 20, etc. ; sans dat</i>. ESCHL. <i>Pers. 401 ;</i> SOPH. <i>El. 130 ; abs. part</i>. παρόν, <i>ion</i>. παρεόν, comme il est <i>ou</i> était permis, comme il est <i>ou</i> était possible, quoiqu’il soit <i>ou</i> fût possible, <i>etc., avec l’inf</i>. HDT. <i>1, 129 ; 6, 72, etc. ;</i> XÉN. <i>An. 5, 8, 3 ;</i> SOPH. <i>Ph. 1099 ;</i> PLUT. <i>Fab. 11, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 3 pl. épq</i>. παρέασι <span>[ᾱσ]</span> IL. <i>5, 192 ; 14, 299 ;</i> OD. <i>13, 247 ; sbj. ion</i>. παρέω, HDT. <i>4, 98 ; inf. épq</i>. παρέμμεναι, OD. <i>4, 640, etc. ; part. ion. et poét</i>. παρεών, IL. <i>8, 491, etc. ; duel</i> παρεόντε, IL. <i>24, 475. Impf. att. 1 sg</i>. παρῆ, ESCHL. <i>Ch. 523 ; 2 sg. épq</i>. παρῆσθα, OD. <i>4, 497 ; 3 sg. épq</i>. παρῆεν, OD. <i>8, 417 ; 3 pl. épq</i>. πάρεσαν, IL. <i>11, 75. Fut</i>. παρέσσομαι, OD. <i>13, 393</i>.<br><span><b>Étym</b>. π. εἰμί.</span></span><br><br>\n➁ <b>πάρ·ειμι</b> <span>(<i>inf</i>. παριέναι, <i>impf</i>. παρῄειν ; <i>chez les Att. le prés. a la signif. du fut. ; pour le prés. on emploie</i> παρέρχομαι)</span><br><b>   I</b> passer auprès de, le long de, OD. <i>4, 527 ; 17, 233 ;</i> PD. <i>P. 1, 50 ;</i> PLAT. <i>Rsp. 515</i> b, <i>etc. ; avec l’acc</i>. passer auprès <i>ou</i> devant, HDT. <i>7, 109 ;</i> XÉN. <i>An. 5, 4, 30 ;</i> π. ἐπὶ τὰ ὑποζύγια, XÉN. <i>An. 4, 5, 8,</i> s’avancer vers les bêtes de somme le long du cortège ; ὃ παριὼν τῷ λόγῳ ἔτυχον εἰπών, PLAT. <i>Leg. 776</i> c, ce que je disais en passant ;<br><b>   II</b> surpasser, XÉN. <i>Cyr. 1, 4, 5 ;</i><br><b>   III</b> aller vers, aller rejoindre, s’approcher, entrer, venir, PLAT. <i>Phæd. 59</i> e ; EUR. <i>Hel. 458,</i> AR. <i>Ach. 43, etc. ; avec</i> εἰς <i>et l’acc</i>. HDT. <i>3, 77, 84, etc. ;</i> EUR. <i>Ion 229 ;</i> βίᾳ εἰς οἰκίαν, XÉN. <i>Cyr. 1, 2, 2,</i> entrer de force dans une maison ; <i>particul. en parl. des orateurs qui s’avancent en public,</i> s’avancer, se produire, PLAT. <i>1 Alc. 106</i> c ; PLUT. <i>Pomp. 54 ;</i> π. ἐπὶ τὸ βῆμα, ISOCR. <i>161</i> c ; ESCHN. <i>76, 18,</i> s’avancer à la tribune ; <i>abs</i>. οἱ παριόντες, ATT. les orateurs qui se présentent ; παρῄει οὐδείς, DÉM. <i>285, 6,</i> personne ne s’est présenté pour parler ;<br><b>   IV</b> continuer son chemin, passer de l’un à l’autre : τὸ σύνθημα παρῄει, XÉN. <i>An. 6, 3, 25,</i> le mot d’ordre passa d’homme à homme.<br><span><b>Étym</b>. π. εἷμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρειμι - πάρειμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 22 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (5)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (5)</li>\n<li>Galates (2)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (2)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G3919":"<h1>pareisago</h1>\n<p>Strong n° 3919 <i>Prononciation [par-ice-ag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>introduire ou apporter secrètement ou astucieusement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·εισ·άγω</b> <span>[ᾰγ]</span><br><b>   I</b> <i>avec un rég. de pers. :</i><br><b>      1</b> τινά, ISOCR. <i>175</i> c ; POL. <i>3, 62, 3, etc</i>. produire qqn (devant une assemblée) ; <i>particul</i>. présenter, mettre en scène, représenter (dans un poème, dans un récit, <i>etc</i>.) POL. <i>2, 3, 7 ; 5, 2, 6, etc. ;</i><br><b>      2</b> <i>avec une idée de secret, de fraude,</i> introduire furtivement <i>ou</i> doucement, comme par surprise, <i>d’où</i> laisser entrer, <i>acc</i>. POL. <i>2, 7, 8 ;</i><br><b>   II</b> <i>avec un rég. de chose :</i><br><b>      1</b> proposer, introduire, <i>acc</i>. POL. <i>6, 56, 12, etc. ; en parl. d’institutions, de coutumes, etc</i>. POL. <i>4, 20, 5, etc. ;</i> DS. <i>1, 96, etc. ;</i><br><b>      2</b> <i>avec une idée négative,</i> introduire sans raison, faire intervenir à tort, mêler à, POL. <i>2, 3, 8</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεισαγω - παρεισάγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3920":"<h1>pareisaktos</h1>\n<p>Strong n° 3920 <i>Prononciation [par-ice'-ak-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporté secrètement ou subrepticement</li>\n<li>celui qui a volé furtivement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρείσακτος, ος, ον</b>, introduit furtivement, intrus, NT. <i>Gal. 2, 4 ; surn. d’un Ptolémée,</i> STR. <i>794</i>.<br><span><b>Étym</b>. παρεισάγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεισακτος - παρείσακτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G3921":"<h1>pareisduno</h1>\n<p>Strong n° 3921 <i>Prononciation [par-ice-doo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>entrer secrètement, se glisser furtivement, s'introduire furtivement</li>\n<li>voler (discrètement)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·εισδύνω</b> <i>(seul. prés.) c</i>. παρεισδύω, GEOP. <i>17, 23, 2</i>.<br><br>\n<b>παρ·εισδύω</b>, DYSC. <i>Synt. p. 119, 15 ; d’ord. moy</i>. <b>παρεισδύομαι</b> <span>(<i>f</i>. -δύσομαι, <i>ao.2</i> παρεισέδυν, <i>etc</i>.)</span> s’introduire par le côté, pénétrer furtivement, se glisser, <i>avec</i> εἰς <i>et l’acc</i>. HPC. <i>1160</i> c ; HDN <i>2, 12, 1 ; abs</i>. ARSTT. <i>Probl. 5, 6, etc. ;</i> PLUT. <i>M. 216</i> b ; DYSC. <i>Synt. p. 314, 16</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεισδυνω - παρεισδύ(ν)ω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G3922":"<h1>pareiserchomai</h1>\n<p>Strong n° 3922 <i>Prononciation [par-ice-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'introduire secrètement ou à la dérobée, se glisser, voler d'une manière furtive</li>\n<li>entrer en complément, venir aux côtés</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·εισέρχομαι</b>, s’introduire furtivement <i>ou</i> frauduleusement, εἰς <i>et l’acc</i>. PLUT. <i>Popl. 17 ; abs</i>. POL. <i>1, 7, 3, etc. ;</i> PLUT. <i>Cor. 23 ; avec un inf</i>. NT. <i>Gal. 2, 4,</i> pour faire qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεισερχομαι - παρεισέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G3923":"<h1>pareisphero</h1>\n<p>Strong n° 3923 <i>Prononciation [par-ice-fer'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporter en outre, en plus</li>\n<li>être aux côtés et contribuer quelque chose</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·εισφέρω :<br>      1</b> apporter en outre, <i>acc</i>. NT. <i>2Petr. 1, 5 ;</i><br><b>      2</b> introduire contre : νόμον, DÉM. <i>484, 1, 12, etc</i>. proposer une loi en abrogation d’une autre.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεισφερω - παρεισφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3924":"<h1>parektos</h1>\n<p>Strong n° 3924 <i>Prononciation [par-ek-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>excepté, sauf, à l'exception de (une chose)</li>\n<li>en outre, en dehors</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·εκτός :<br>      1</b> <i>adv</i>., hors, dehors, à l’extérieur, NT. <i>2Cor. 11, 28 ;</i><br><b>      2</b> <i>prép</i>. hors de, <i>gén</i>. NT. <i>Matth. 5, 32 ; Ap. 26, 29</i>.<br><span><b>Étym</b>. π. ἐκτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεκτος - παρεκτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3925":"<h1>parembole</h1>\n<p>Strong n° 3925 <i>Prononciation [par-em-bol-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un campement\n<ol type=\"a\">\n<li>le camp d'Israël dans le désert\n<ol>\n<li>utilisé pour la ville de Jérusalem, d'autant plus qu'elle rappelait aux Israélites qu'ils avaient eu autrefois leur campement dans le désert</li>\n<li>de la congrégation sacrée ou assemblée d'Israël, comme elle fut jadis rassemblée dans les camps du désert</li>\n</ol>\n</li>\n<li>la caserne des soldats Romains, qui se trouvait à Jérusalem dans la Tour Antonia, citadelle reliée au temple</li>\n</ol>\n</li>\n<li>une armée en ligne de bataille</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρεμϐολή, ῆς (ἡ)</b> action de jeter au milieu de, <i>d’où :</i><br><b>      1</b> insertion, intercalation, ESCHN. <i>23, 41 ; 83, 21 ; particul</i>. insertion d’une lettre au milieu d’un mot, DH. <i>6, 1069 Reiske ; t. de rhét. ou de gr</i>. parenthèse, RHÉT. <i>8, 483, 576 W. ;</i><br><b>      2</b> <i>t. mil</i>. action d’intercaler des soldats de renfort dans les rangs, POL. <i>11, 32, 6 ;</i> EN. TACT. <i>Pol. 31 ; p. ext</i>. ordre de bataille, COM. (POLL. <i>9, 15</i>) ;<br><b>      3</b> action de s’établir et de camper, POL. <i>4, 29, 1 ; 6, 31, 7 ; d’où</i> place où qqn a sa tente dans le camp, POL. <i>6, 28, 9 ; p. suite,</i> campement, camp, NT. <i>Ap. 21, 34 ;</i><br><b>      4</b> sorte de croc-en-jambe, <i>ou</i> attaque de l’adversaire par le flanc, PLUT. <i>M. 638</i> b ;<br><b>      5</b> <i>c</i>. παρεξειρεσία, le bord le plus bas du navire à l’avant et à l’arrière, POL. <i>21, 5, 4 (corr</i>. παραϐολάς).<br><span><b>Étym</b>. παρεμϐάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεμβολη - παρεμβολή</font>\n<br><br>Voir définition </td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (6)</li>\n<li>Hébreux (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3926":"<h1>parenochleo</h1>\n<p>Strong n° 3926 <i>Prononciation [par-en-okh-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>occasionner des difficultés dans une affaire, susciter des ennuis, déranger, contrarier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·ενοχλέω-ῶ</b> <span>(<i>impf</i>. -ηνώχλουν, <i>ao</i>. -ηνώχλησα, <i>pf. pass</i>. -ηνώχλημαι)</span> causer du trouble à, troubler, inquiéter, tourmenter, <i>abs</i>. HPC. <i>1276, 32 ; dat</i>. ARSTT. <i>Rhet. 2, 4, 21 ; acc</i>. POL. <i>16, 37, 3 ; au pass</i>. DÉM. <i>242, 16</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρενοχλεω - παρενοχλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3927":"<h1>parepidemos</h1>\n<p>Strong n° 3927 <i>Prononciation [par-ep-id'-ay-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui vient d'un pays étranger et qui est dans une ville ou sur une terre où il réside aux côtés des autochtones</li>\n<li>un étranger</li>\n<li>celui qui séjourne à l'étranger, un voyageur</li>\n<li>dans le N.T. métaph. en référence aux cieux comme lieu d'origine, pour celui qui séjourne sur terre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·επίδημος, ος, ον</b>, qui séjourne <i>ou</i> voyage peu de temps en pays étranger, POL. <i>32, 22, 4 ;</i> ATH. <i>196</i> a ; SPT. <i>Gen. 23, 4</i>.<br><span><b>Étym</b>. π. ἐπίδημος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεπιδημος - παρεπίδημος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G3928":"<h1>parerchomai</h1>\n<p>Strong n° 3928 <i>Prononciation [par-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>passer, avancer\n<ol type=\"a\">\n<li>de personnes allant de l'avant\n<ol>\n<li>s'éloigner</li>\n</ol>\n</li>\n<li>de temps\n<ol>\n<li>une action qui avance dans le temps</li>\n</ol>\n</li>\n<li>métaph.\n<ol>\n<li>disparaître, périr</li>\n<li>passer au-dessus, négliger, omettre, transgresser</li>\n<li>être conduit près de, être amené, être averti</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>venir près de, se mettre en avant, arriver</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·έρχομαι</b> <span>(<i>f</i>. παρελεύσομαι, <i>ao.2</i> παρῆλθον, <i>pf</i>. παρελήλυθα <span>[ῠ]</span>)</span><br><b>   I. 1</b> passer à côté <i>ou</i> devant ; <i>en parl. d’oiseaux,</i> passer en volant, OD. <i>12, 62 ; en parl. d’un vaisseau,</i> passer en naviguant, OD. <i>16, 357 ; en parl. de pers</i>. ESCHL. <i>Suppl. 1004 ;</i> SOPH. <i>O.C. 902 ;</i> HDT. <i>3, 72, etc. ; avec l’acc. du lieu auprès duquel on passe,</i> IL. <i>8, 239 ;</i> PLAT. <i>1 Alc. 123</i> b ;<br><b>      2</b> passer outre, s’écouler, <i>en parl. de flots,</i> OD. <i>5, 429 ; fig. en parl. du temps,</i> SOPH. <i>Tr. 69 ;</i> PLAT. <i>Lach. 188</i> a, <i>etc. ; en gén. en parl. de tout ce qui est passé, accompli,</i> SOPH. <i>Ph. 1358 ;</i> PLAT. <i>Phædr. 231</i> b, <i>etc. ; t. de gr</i>. ὁ παρεληλυθὼς χρόνος, ARSTT. <i>Poet. 20, 9, etc</i>. le temps passé ;<br><b>      3</b> dépasser, surpasser : τινα, IL. <i>23, 345,</i> qqn ; τινα ποσίν, OD. <i>8, 230,</i> dépasser qqn à la course ; <i>fig</i>. τινα ἐν δόλοισιν, OD. <i>13, 291,</i> surpasser qqn en ruses ; τῇ δόξῃ, PLUT. <i>Cam. 36,</i> en gloire ;<br><b>      4</b> transgresser, enfreindre : Διὸς νόον, HÉS. <i>Th. 613,</i> la volonté de Zeus ; νόμον, LYS. <i>107, 41 ;</i> DÉM. <i>977, 14,</i> la loi ;<br><b>      5</b> passer à côté de, omettre, ne pas tenir compte de, <i>acc</i>. AR. <i>Vesp. 636 ;</i> PLAT. <i>1 Alc. 130</i> c ; EUR. <i>Suppl. 231,</i> mépriser les dieux ;<br><b>      6</b> passer auprès de qqn de façon qu’il ne s’en aperçoive pas : ἐπεὶ οὐ παρελεύσεαι, IL. <i>1, 132,</i> puisque tu ne m’échapperas pas ; πολλά με παρέρχεται, THGN. <i>419,</i> beaucoup de choses m’échappent ; <i>avec l’inf</i>. il ne m’échappe pas de, <i>etc</i>. SOPH. <i>Tr. 226 ;</i> τοῦτο μικροῦ παρῆλθε με εἰπεῖν, DÉM. <i>550, 26,</i> j’ai failli oublier de dire cela ;<br><b>   II</b> arriver, s’approcher, entrer, ESCHL. <i>Ch. 845 ;</i> SOPH. <i>El. 1337 ;</i> PLAT. <i>2 Alc. 144</i> a, <i>etc. ; avec</i> εἰς <i>et l’acc</i>. HDT. <i>3, 77 ;</i> PLUT. <i>Ant. 74, etc. ; avec l’acc</i>. EUR. <i>Hipp. 108, etc. ; avec idée d’hostilité :</i> π. βίᾳ εἰς τὴν πόλιν, XÉN. <i>An. 5, 5, 11,</i> entrer de force dans la ville ; <i>cf</i>. DÉM. <i>237, 6, etc. ; particul</i>. s’avancer devant une assemblée pour parler, THC. <i>2, 59, etc. ;</i> PLAT. <i>1 Alc. 105</i> a ; s’avancer au milieu du peuple pour se faire entendre, <i>en parl. de joueurs de flûte,</i> ATH. <i>538 ; fig</i>. entrer en possession de, parvenir à (au pouvoir, <i>etc.) avec</i> εἰς <i>et l’acc</i>. DÉM. <i>117, 4, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 dor. inf</i>. παρενθεῖν, THCR. <i>Idyl. 15, 60</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρερχομαι - παρέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n31 fois dans 27 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (5)</li>\n<li>Luc (9)</li>\n<li>Actes (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3929":"<h1>paresis</h1>\n<p>Strong n° 3929 <i>Prononciation [par'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>passer au-dessus, laisser passer, négliger, ne tenir aucun compte de rémission</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πάρεσις, εως (ἡ)</b> action de laisser aller, de relâcher, <i>d’où :</i><br><b>   I</b> <i>pass</i>. relâchement, affaiblissement, HPC. <i>1136</i> g ; PLUT. <i>M. 652</i> d ; <i>etc. ;</i><br><b>   II</b> <i>act. :</i><br><b>      1</b> action de, congédier, PLUT. <i>Dio. c. Brut. 2 ;</i><br><b>      2</b> action de remettre, rémission (<i>de dettes,</i> PHALAR. <i>Ep. 114 ; de fautes,</i> NT. <i>Rom. 3, 25</i>) ;<br><b>      3</b> action de mépriser, mépris, APP. (SUID. <i>s. v</i>.).<br><span><b>Étym</b>. παρίημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεσις - πάρεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G3930":"<h1>parecho</h1>\n<p>Strong n° 3930 <i>Prononciation [par-ekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>procurer, offrir</li>\n<li>montrer, avoir les moyens de, fournir</li>\n<li>être les auteurs de, ou faire avoir à quelqu'un\n<ol type=\"a\">\n<li>donner, apporter, occasionner à quelqu'un une chose favorable ou défavorable, occasionner</li>\n</ol>\n</li>\n<li>s'offrir, se montrer, se présenter</li>\n<li>offrir de sa propre part\n<ol type=\"a\">\n<li>rendre ou donner sur ses propres ressources ou par son propre pouvoir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·έχω</b> <span>(<i>f</i>. παρέξω, <i>ao.2</i> παρέσχον, <i>pf</i>. παρέσχηκα)</span><br><b>   I <i>tr</i>.<br>      1</b> fournir, procurer : φάος πάντεσσι, OD. <i>18, 317,</i> la lumière à tous ; δύναμιν εἰς τὴν στρατιάν, fournir un contingent à l’armée, XÉN. <i>An. 6, 2, 10 ; abs</i>. ἐγὼ δ' εὖ πᾶσι παρέξω, OD. <i>8, 39,</i> je fournirai à tous abondamment ; <i>avec un n. de chose pour suj. :</i> θάλασσα παρέχῃ ἰχθῦς, OD. <i>19, 113,</i> la mer fournit des poissons ; <i>cf</i>. IL. <i>23, 834 ; en parl. de choses immatérielles :</i> π. ὕμνον πολύν, PD. <i>N. 6, 57,</i> fournir (à un poète) une riche matière à chanter ; γέλω τε καὶ εὐφροσύνην, OD. <i>20, 8,</i> un sujet de rire et de joie ; ὅπως τὰ ὅπλα μὴ αἴσθησιν παρέχοι, THC. <i>3, 22,</i> afin que les armes n’attirassent pas l’attention (en s’entrechoquant) ; παρέχειν τινὶ πράγματα, HDT. <i>1, 155, etc. ;</i> PLAT. <i>Phæd. 115</i> a, <i>etc. ; ou</i> πόνον, HDT. <i>1, 177 ; ou</i> ἔργον, AR. <i>Nub. 524,</i> PLAT. <i>Tim. 38</i> e, <i>etc</i>. donner à qqn de la peine, du mal, de l’embarras, du souci ; être importun, à charge à qqn ; <i>avec l’inf. ;</i> π. γάλα θῆσθαι, OD. <i>4, 89,</i> fournir du lait à traire, <i>en parl. de brebis ;</i> τὸ σῶμα τύπτειν, AR. <i>Nub. 441,</i> offrir son corps pour des coups ; <i>avec le pron. réfl</i>. π. ἑαυτοὺς χρῆσθαι Κύρῳ ὅ, τι ἂν δέῃ, XÉN. <i>Cyr. 8, 1, 5,</i> se mettre à la disposition de Cyrus pour ce dont il aurait besoin ; <i>cf</i>. PLAT. <i>Phædr. 228</i> e, <i>Ap. 33</i> b, <i>etc. ; avec le part. :</i> π. ἑαυτὸν δεθησόμενον, LUC. <i>Tox. 35,</i> se livrer pour être emprisonné ; <i>sans pron. réfl</i>. παρέχοντες (<i>s.-e</i>. ἑαυτούς) διαφθαρῆναι αἰσχίστῳ μόρῳ, HDT. <i>9, 17,</i> se livrer pour périr de la plus affreuse mort ; πατεῖν παρεῖχε τῷ θέλοντι, SOPH. <i>Aj. 1145,</i> il se laissait fouler aux pieds par le premier venu ; τοῖς ἰατροῖς π. ἀποτέμνειν καὶ ἀποκάειν, XÉN. <i>Mem. 1, 2, 54,</i> se livrer aux médecins pour qu’ils coupent et qu’ils brûlent ;<br><b>      2</b> accorder, permettre, concéder, <i>avec l’inf</i>. ἐπεὶ παρέσχες ἀντιφωνῆσαι, SOPH. <i>Tr. 1114,</i> puisque tu m’as permis de répondre ; <i>cf</i>. LUC. <i>D. mar. 14, 2 ;</i><br><b>      3</b> <i>avec le pron. réfl. accompagné d’un adj. ou d’un part</i>. se donner, s’offrir, se montrer (tel ou tel, dans telle disposition, <i>etc</i>.) : π. ἑαυτὸν εὐπειθῆ, XÉN. <i>Cyr. 2, 1, 22,</i> se montrer docile ; π. σπάνιον αὑτόν. PLAT. <i>Euthyphr. 3</i> d, se montrer rarement, se faire rare ; οὕτω ἑαυτόν, XÉN. <i>Cyr. 7, 5, 46,</i> se montrer ainsi ; <i>de même sans pron. réfl.,</i> παρέχειν ἐκποδών, AR. <i>Vesp. 949,</i> s’éclipser, prendre la clef des champs ; <i>abs. au sens obscène,</i> ἑαυτὸν π. LUC. <i>D. mar. 13, etc., ou</i> παρέχειν <i>seul</i>. AR. <i>Lys. 162, etc. ; avec un subst. accompagné d’un attrib</i>. faire qqe ch. d’une pers. <i>ou</i> d’une chose : τινὰ βέλτιστον, XÉN. <i>Cyr. 1, 2, 5,</i> rendre un homme excellent ; τινὰ σῶον, XÉN. <i>Œc. 9, 9,</i> sauver qqn ; καθαρόν τινα, PLAT. <i>Crat. 405</i> b, rendre qqn pur ;<br><b>   II</b> <i>impers</i>. παρέχει τινί, <i>avec ou sans inf</i>. il se présente une occasion de, l’occasion <i>ou</i> le moment est favorable pour, il est possible <i>ou</i> permis de, HDT. <i>1, 9 ; 3, 73, 142, etc. ;</i> PLUT. <i>Brut. 36, etc. ; part. abs</i>. παρέχον, comme il est possible, comme l’occasion s’offre, HDT. <i>5, 48 ;</i> παρασχόν, l’occasion s’étant présentée, THC. <i>1, 120 ; 5, 14, etc. ;</i> PLUT. <i>Cim. 14, etc. ;</i><br><b><i>Moy</i>. παρέχομαι</b> <span>(<i>pf</i>. παρέξομαι <i>et</i> παρασχήσομαι, <i>pf</i>. παρέσχημαι)</span> : offrir, présenter, fournir, donner qqe ch. de soi, par ses propres moyens, par sa propre volonté :<br><b>      1</b> <i>en gén</i>. π. νέας, HDT. <i>7, 89, etc.,</i> fournir des vaisseaux ; ποταμὸς παρέχεται κροκοδείλους, HDT. <i>4, 44,</i> le fleuve a des crocodiles ; π. προθυμίαν, HDT. <i>7, 6 ;</i> DÉM. <i>11, 13 ;</i> τὸ πρόθυμον, THC. <i>4, 85 ;</i> PLAT. <i>Leg. 859</i> b, montrer de la bonne volonté ;<br><b>      2</b> <i>particul</i>. π. τινα μάρτυρα, PLAT. <i>Ap. 19</i> d, <i>etc</i>. produire qqn comme témoin ; π. τεκμήρια, PLAT. <i>Ap. 20</i> d, <i>Phæd. 87</i> b, <i>etc</i>. produire des preuves ;<br><b>      3</b> offrir de soi <i>ou</i> en soi : Ἀθηναῖοι ἀρχαιότατον ἔθνος παρεχόμενοι, HDT. <i>7, 161,</i> les Athéniens qui se présentent, <i>càd</i>. qui sont reconnus comme le plus ancien peuple ; ὁ Πόντος π. ἔθνεα ἀμαθέστατα, HDT. <i>6, 61,</i> le Pont offre dans son sein les peuples les moins cultivés ;<br><b>      4</b> offrir en perspective, promettre ; ἀψευδέα μαντήϊα, HDT. <i>2, 174,</i> des oracles sûrs ; ἔστιν ἃ παρεχόμενον, THC. <i>3, 36,</i> bien qu’il fît certaines promesses ; <i>cf</i>. THC. <i>1, 39 ; 4, 108 ;</i><br><b>      5</b> <i>avec double acc</i>. se procurer pour soi-même : π. θεὸν εὐμενῆ, EUR. <i>Andr. 54,</i> se rendre un dieu propice ; τινα ἀϐλαϐῆ, XÉN. <i>Cyr. 4, 1, 3,</i> rendre qqn inoffensif pour soi.<br><span><b><span class=\"arrow\"></span></b> <span>[πᾱρ]</span> <i>dans</i> παρέχῃ <i>à l’arsis,</i> OD. <i>19, 113. Act. fut</i>. παρέξω, <i>rar</i>. παρασχήσω, THC. <i>6, 86 ;</i> ISOCR. <i>130</i> e, ANTID. <i>§ 248 ; ao.2 impér. 2 sg</i>. παράσχες (<i>non</i> παράσχε), EUR. <i>Hec. 842, etc. ; inf. épq</i>. παρασχέμεν, IL. <i>19, 147 ; autre ao.2 poét</i>. παρέσχεθον, HÉS. <i>Th. 639 ; inf</i>. παρασχεθεῖν, AR. <i>Eq. 325. Moy. f</i>. παρέξομαι, ATT. <i>ou</i> παρασχήσομαι, ANT. <i>132, 20 ;</i> LYS. <i>115, 5 ; pf. pass. au sens moy</i>. παρέσχημαι, XÉN. <i>An. 7, 6, 11 ;</i> DÉM. <i>829, 2, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρεχω - παρέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 16 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Actes (5)</li>\n<li>Galates (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (2)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G3931":"<h1>paregoria</h1>\n<p>Strong n° 3931 <i>Prononciation [par-ay-gor-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui s'adresse à, discours\n<ol type=\"a\">\n<li>exhortation</li>\n<li>consolation, réconfort, soulagement</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρηγορία, ας (ἡ) :<br>      1</b> exhortation, encouragement, A. RH. <i>2, 1281 : fig</i>. ESCHL. <i>Ag. 95 ;</i><br><b>      2</b> consolation, adoucissement, PLUT. <i>Cim. 4 ; d’où</i> remède, ARÉT. <i>Cur. m. diut. 1, 3, etc. ;</i><br><b>      3</b> nom, épithète, JOS. <i>B.J. 4, 8, 3</i>.<br><span><b>Étym</b>. παρήγορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρηγορια - παρηγορία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3932":"<h1>parthenia</h1>\n<p>Strong n° 3932 <i>Prononciation [par-then-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>virginité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>παρθενία, ας (ἡ)</b> virginité, PD. <i>I. 8, 94 ;</i> ESCHL. <i>Pr. 898 ;</i> PLUT. <i>Brut. 13, etc. ; en parl. d’hommes,</i> A. TAT. <i>5, 20</i>.<br><i>Ion</i>. παρθενίη, A. RH. <i>2, 502</i>.<br><span><b>Étym</b>. παρθένος.</span><br><br>\n➁ <b>παρθένια, ων (τὰ)</b> <i>v</i>. παρθένιος.<br><br>\n<b>παρθένιος, α, ον :<br>   I</b> <i>adj. :</i><br><b>      1</b> de jeune fille, de vierge, virginal, OD. <i>11, 245 ;</i> HÉS. <i>Th. 205 ;</i> PD. <i>P. 12, 15, etc. ;</i> ESCHL. <i>Ag. 215 ;</i> EUR. <i>Ph. 224, etc. ;</i> π. θύραι, ANTH. <i>6, 202,</i> les portes du temple de la déesse vierge (Artémis) ; παρθένιος ἀνήρ, PLUT. <i>Pomp. 74,</i> mari d’une jeune fille ; τὰ παρθένια, virginité, SPT. <i>Deut. 22, 15, etc. ;</i><br><b>      2</b> <i>fig</i>. vierge, pur, <i>en parl. de choses (source,</i> HH. <i>Cer. 99 ; baie de myrte,</i> AR. <i>Av. 1099, etc</i>.) ;<br><b>      3</b> π. αὐλός, sorte de flûte, ARSTT. <i>H.A. 7, 1 ;</i> ATH. <i>176</i> f, <i>etc. ;</i><br><b>   II</b> <i>subst</i>. ὁ π. fils d’une jeune fille, d’une femme non mariée, IL. <i>16, 180</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. παρθένιος, EUR. <i>Ph. 224</i>.<br><span><b>Étym</b>. παρθένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρθενια - παρθενία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3933":"<h1>parthenos</h1>\n<p>Strong n° 3933 <i>Prononciation [par-then'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une vierge\n<ol type=\"a\">\n<li>une jeune fille à marier</li>\n<li>une femme n'ayant jamais eu de relation sexuelle avec un homme</li>\n<li>la fille non encore mariée</li>\n</ol>\n</li>\n<li>un homme qui s'est abstenu de toute impureté et ne s'est pas prostitué à l'idolâtrie, et a ainsi gardé sa chasteté\n<ol type=\"a\">\n<li>celui qui n'a jamais eu de relation sexuelle avec une femme</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρθένος, ου (ἡ) :<br>A</b> ἡ π. :<br><b>   I</b> vierge, <i>particul. :</i><br><b>      1</b> jeune fille, HOM. ATT. ; <i>joint à</i> γυνή, HÉS. <i>Th. 514 ; à</i> θυγάτηρ, XÉN. <i>Cyr. 4, 6, 9 ; à</i> κόρα, <i>en parl. du Sphinx,</i> EUR. <i>Ph. 1730 ;</i><br><b>      2</b> <i>en gén</i>. fille non mariée, SOPH. <i>O.R. 1462 ;</i> DS. <i>16, 55, etc. ;</i><br><b>      3</b> jeune femme non mariée, IL. <i>2, 514 ;</i> SOPH. <i>Tr. 1221 ;</i><br><b>      4</b> qui est comme une jeune fille, vierge, pur, intact, <i>en parl. de choses (source,</i> ESCHL. <i>Pers. 615 ; navire dont on ne s’est pas encore servi,</i> AR. <i>Eq. 1302, etc</i>.) ;<br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> <i>la statue d’Athèna, à Athènes,</i> PAUS. <i>5, 11, 10 ; 10, 34, 8 ;</i><br><b>      2</b> la Vierge, <i>constellation,</i> ARAT. <i>97, etc. ;</i><br><b>      3</b> pupille de l’œil, ARÉT. <i>Caus. m. diut. 1, 7 (cf</i>. κόρη) ;<br><b>B</b> <i>p. anal</i>. ὁ π. :<br><b>      1</b> célibataire, NT. <i>Apoc. 14, 4 ;</i><br><b>      2</b> <i>ironiq</i>. homme timide, AR. <i>Eq. 1302</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Lac</i>. παρσένος, AR. <i>Lys. 1263, 1272</i>.<br><span><b>Étym</b>. <i>p.-ê. indo-europ</i>. *psteno-, sein.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρθενος - παρθένος</font>\n<br><br>origine inconnue</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 13 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3934":"<h1>Parthos</h1>\n<p>Strong n° 3934 <i>Prononciation [par'-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Parthes (Angl. Parthia) = « un gage »\n<ol><li>peuple qui occupait un territoire au sud-est de la Mer Caspienne, avec comme frontière occidentale l'Euphrate, allant jusqu'au golfe Persique, la capitale était Ctesiphon, sur le Tigre, en face de Séleucie.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πάρθοι, ων (οἱ)</b> les Parthes, <i>pple d’Asie,</i> HDT. <i>3, 93 ; au sg</i>. PLUT. <i>Syll. 5, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Παρθος - Πάρθοι</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3935":"<h1>pariemi</h1>\n<p>Strong n° 3935 <i>Prononciation [par-ee'-ay-mi]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>laisser passer\n<ol type=\"a\">\n<li>se détourner, négliger</li>\n<li>ne tenir aucun compte de, omettre</li>\n</ol>\n</li>\n<li>relâcher, détacher, laisser aller</li>\n<li>relâché, affaibli, languissant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·ίημι</b> <span>(<i>f</i>. παρήσω, <i>ao</i>. παρῆκα, <i>pf</i>. παρεῖκα ; <i>pass. ao</i>. παρείθην, <i>pf</i>. παρεῖμαι)</span> laisser aller, <i>d’où :</i><br><b>      1</b> lâcher, laisser tomber, <i>acc</i>. CLÉARQ. (ATH. <i>257</i> a) ; <i>p. suite, au pass</i>. tomber, IL. <i>23, 868 ;</i><br><b>      2</b> relâcher : τοῦ ποδός, AR. <i>Eq. 436,</i> abaisser les extrémités des voiles ; <i>au pass</i>. se précipiter, EUR. <i>Suppl. 1070 ;</i> s’abandonner, PLAT. <i>Euthyd. 303</i> b ; PLUT. <i>Eum. 7 ; fig</i>. relâcher, abattre, énerver, <i>acc</i>. SOPH. <i>O.R. 688 ;</i> au. <i>pass</i>. être abattu, être accablé (<i>par le sommeil, la maladie, la vieillesse, etc</i>.) EUR. <i>Or. 879, etc. ;</i> PLAT. <i>Leg. 931</i> d ; PLUT. <i>M. 102</i> a, <i>etc. ;</i><br><b>      3</b> laisser entrer, laisser pénétrer, <i>acc</i>. HDT. <i>3, 72, etc. ;</i> τινὰ εἰς τὴν ἀκρόπολιν, XÉN. <i>Hell. 5, 2, 29,</i> qqn dans la citadelle ; <i>fig</i>. admettre, <i>acc</i>. PLAT. <i>Rsp. 560</i> d ; τι εἰς τὴν ψυχήν, PLAT. <i>Phæd. 90</i> d, faire entrer dans l’âme (qqe sentiment, qqe désir, <i>etc</i>.) ;<br><b>      4</b> céder, abandonner : τί τινι, ESCHL. <i>Ag. 943 ;</i> ARSTT. <i>Pol. 7, 14</i> c, <i>etc</i>. qqe ch. à qqn ; ἑαυτόν τινι, EUR. <i>Tr. 688,</i> s’abandonner, se confier à qqe ch. (aux flots) ;<br><b>      5</b> remettre, confier : τινί τι, SOPH. <i>Ph. 132,</i> qqe ch. à qqn ; <i>avec l’inf</i>. HDT. <i>7, 161 ;</i> SOPH. <i>El. 1482 ;</i> PLAT. <i>Conv. 199</i> b, <i>etc. ; avec</i> ὥστε <i>et l’inf</i>. SOPH. <i>O.C. 570 ; avec le sbj</i>. AR. <i>Vesp. 154,</i> permettre de ; <i>abs</i>. SOPH. <i>O.C. 591 ;</i> PLAT. <i>Conv. 199</i> c, <i>etc. ;</i><br><b>      6</b> laisser passer, laisser s’écouler, <i>en parl. du temps,</i> HDT. <i>7, 183 ; 8, 9 ;</i> τὸν καιρόν, THC. <i>4, 27 ;</i> PLAT. <i>Rsp. 370</i> b ; DÉM. <i>98, 16, etc</i>. laisser passer l’occasion ;<br><b>      7</b> laisser de côté, <i>d’où :</i> ne pas tenir compte de, ne pas faire attention à, HDT. <i>1, 177 ;</i> SOPH. <i>El. 732 ; particul</i>. passer sous silence, PLAT. <i>Leg. 754</i> a ; omettre, négliger, ESCHL. <i>Ch. 925, etc. ;</i> SOPH. <i>Tr. 682, etc. ;</i> PLAT. <i>Rsp. 503</i> e, <i>etc. ;</i> π. περί τινος, POL. <i>2, 59, 3,</i> être oublieux <i>ou</i> négligent au sujet de qqe ch. ; <i>avec l’inf</i>. SOPH. <i>O.C. 1212 ;</i> PLAT. <i>Phædr. 235</i> e, <i>etc. ; avec le part</i>. PAUS. <i>3, 5, 8 ;</i><br><b><i>Moy</i>. παρίεμαι</b> <span>(<i>f</i>. παρήσομαι, <i>ao</i>. παρηκάμην, <i>etc</i>.)</span><br><b>   I</b> laisser aller, <i>càd. :</i><br><b>      1</b> laisser entrer auprès de soi, introduire <i>ou</i> admettre auprès de soi ; <i>acc</i>. POL. <i>2, 15, 6 ;</i> τινα εἰς τὰς ἀκροπόλεις, DÉM. <i>194, 27,</i> qqn dans les forteresses ;<br><b>      2</b> demander avec instance, solliciter, <i>acc</i>. PLAT. <i>Ap. 17</i> c, <i>etc. ;</i><br><b>      3</b> accorder, concéder, EUR. <i>Med. 891 ;</i><br><b>      4</b> <i>en mauv. part,</i> laisser aller, négliger, DC. <i>51, 5 ; 60, 2 ;</i><br><b>   II</b> envoyer hors de, <i>d’où fig</i>. chercher à détourner de soi : οὐδέν σου παρίεμαι, PLAT. <i>Rsp. 341</i> b, je n’écarte rien de ce que tu proposes, je consens à ce que tu proposes.<br><span><b><span class=\"arrow\"></span></b> <span>[ῑ]</span> <i>Att. ;</i> <span>[ῐ]</span> PD. <i>P. 1, 165. Pass. ao. 3 sg</i>. παρείθη, IL. <i>23, 868. Moy. ao.2</i> παρείμην, SOPH. <i>O.C. 1666</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παριημι - παρίημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3936":"<h1>paristemi</h1>\n<p>Strong n° 3936 <i>Prononciation [par-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être placé à côté ou près de\n<ol type=\"a\">\n<li>à portée de main\n<ol>\n<li>présenter</li>\n<li>offrir</li>\n<li>pourvoir</li>\n<li>mettre une personne ou une chose à sa disposition</li>\n<li>présenter une personne à une autre pour la voir et la questionner</li>\n<li>présenter ou montrer</li>\n<li>apporter, amener près de</li>\n<li>métaph. amener dans sa camaraderie ou son intimité</li>\n</ol>\n</li>\n<li>présenter (montrer) par des arguments, prouver</li>\n</ol>\n</li>\n<li>se tenir à côté, se tenir proche, être à portée de main, être présent\n<ol type=\"a\">\n<li>se tenir\n<ol>\n<li>se tenir aux côtés de, un spectateur</li>\n</ol>\n</li>\n<li>apparaître</li>\n<li>se tenir prêt</li>\n<li>être prêt à secourir</li>\n<li>être présent\n<ol>\n<li>être venu</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·ίστημι</b> <span>(<i>f</i>. παραστήσω, <i>ao.1</i> παρέστησα, <i>ao.2</i> παρέστην, <i>pf</i>. παρέστηκα, <i>au plur. avec sync</i>. παρέσταμεν, παρέστατε, <i>v. ci-dessous</i>)</span><br><b>   I</b> <i>tr. (à tous les temps de l’act. excepté l’ao.2</i>) :<br><b>      1</b> établir auprès, DÉM. <i>1194, 19 ;</i> ἱππέας τοῖς κέρασι, POL. <i>3, 72, 9,</i> poster des cavaliers auprès des ailes (d’une armée) ;<br><b>      2</b> mettre à la disposition de : τινί τινα, SOCR. RHOD. (ATH. <i>148</i> b) mettre qqn à la disposition de qqn ; ἀνθρώπους Ἀρτέμιδι, LUC. <i>Sacr. 13,</i> offrir des victimes humaines à Artémis, <i>propr</i>. les placer près de l’autel d’Artémis ; <i>particul</i>. placer auprès comme appui, comme soutien, <i>d’où</i> soutenir, étayer : τι τεκμηρίοις, LYS. <i>124 fin,</i> appuyer qqe ch. de preuves ; <i>cf</i>. NT. <i>Ap. 24, 13 ;</i><br><b>      3</b> mettre en regard, comparer, ISOCR. <i>240</i> e ;<br><b>      4</b> amener devant un tribunal, faire comparaître en justice, NT. <i>Ap. 23, 33 ;</i><br><b>      5</b> amener devant, mettre sous les yeux, faire voir, montrer : τι, ATH. <i>110</i> f, qqe ch. ; τί τινι, PLAT. <i>Ep. 335</i> d ; DÉM. <i>538, 3,</i> qqe ch. à qqn ;<br><b>      6</b> amener : ἐλέφαντας εἰς πόλεμον, SPT. <i>1Macc. 6, 34,</i> des éléphants pour la guerre ; <i>fig</i>. mettre dans l’esprit, <i>d’où</i> inspirer : ὀργήν, DÉM. <i>537, 22,</i> de la colère ; φόϐον, DÉM. <i>654, 25,</i> de la crainte ; <i>avec l’inf</i>. DÉM. <i>228, 4 ;</i> τινί τι ποιεῖν, PAUS. <i>14, 6,</i> inspirer à qqn la pensée de faire qqe ch. ; τινὶ π. ὡς, PLAT. <i>Rsp. 600</i> b, amener qqn à penser que, inspirer à qqn la pensée que, <i>etc. ;</i><br><b>      7</b> faire déposer un liquide, <i>d’où</i> le rendre agréable, PLUT. <i>M. 676</i> c ;<br><b>   II</b> <i>intr. (à l’ao.2</i> παρέστην, <i>au pf</i>. παρέστηκα <i>et au pl.q.pf</i>. παρειστήκειν) <i>les sens se confondent avec ceux du moy. intr. v. ci-dessous ;</i><br><b><i>Moy.</i></b> :<br><b>A</b> <i>tr. (aux temps suiv. : prés</i>. παρίσταμαι, <i>f</i>. παραστήσομαι, <i>ao.1</i> παρεστησάμην) :<br><b>   I</b> présenter en son nom, offrir pour son compte : ἱερεῖα, XÉN. <i>An. 6, 1, 22,</i> des sacrifices ; παρίστασθαι μάρτυρας, IS. <i>47, 39 ; 76, 3 ; ou simpl</i>. παρίστασθαι IS. <i>75, 27 ;</i> DÉM. <i>915, 12 et 30,</i> produire des témoins en sa faveur ;<br><b>   II</b> mettre de son côté, <i>càd. :</i><br><b>      1</b> se concilier, gagner, <i>acc</i>. AND. <i>3, 27 Baiter-Sauppe ;</i><br><b>      2</b> mettre de force de son côté, SOPH. <i>O.C. 916 ; d’où</i> soumettre, subjuguer, <i>acc</i>. HDT. <i>3, 45 ;</i> THC. <i>1, 124, etc. ;</i> DÉM. <i>14, 12 ;</i><br><b>   III</b> mettre dans l’esprit de qqn, <i>d’où :</i><br><b>      1</b> exciter : ἔννοιάν τινι, POL. <i>24, 8, 4,</i> faire naître une réflexion dans l’esprit de qqn ;<br><b>      2</b> amener à : τινα εἴς τι, PLAT. <i>Leg. 706</i> a ; πρός τι, POL. <i>29, 2, 5,</i> amener qqn à qqe ch. ; τινα φιλοσοφεῖν, CHION <i>Ep. 3,</i> qqn à philosopher ;<br><b>      3</b> mettre dans telle <i>ou</i> telle disposition, disposer : τινα ὥστε, HDT. <i>4, 136,</i> qqn à, <i>etc. ;</i><br><b>B</b> <i>intr. (à l’aor. 2, au pf. et au pl.q.pf. act. ; au prés. et à l’impf. moy</i>.) :<br><b>   I</b> se placer à côté, <i>d’où :</i><br><b>      1</b> s’avancer auprès, s’approcher de, <i>dat</i>. IL. <i>5, 170 ; 15, 442, 483, etc. ;</i> OD. <i>8, 218, etc. ;</i> ATT. <i>etc. ; abs</i>. IL. <i>3, 405, etc. ;</i> ESCHL. <i>Pers. 197, etc. ; particul. en parl. de serviteurs qui se tiennent respectueusement aux côtés de qqn,</i> OD. <i>1, 335 ; en parl. de compagnons,</i> OD. <i>8, 218, etc. ; d’un mendiant qui aborde qqn,</i> OD. <i>17, 450 ;</i><br><b>      2</b> se tenir à côté pour aider et protéger, <i>d’où</i> assister, aider : τινι, IL. <i>10, 279 ; 20, 121, etc. ;</i> HDT. <i>1, 87 ;</i> XÉN. <i>Hell. 6, 5, 33, etc</i>. qqn ; <i>abs</i>. IL. <i>10, 544 ;</i> OD. <i>4, 827, etc. ; joint à</i> ἀμύνειν, IL. <i>21, 231, etc. ; à</i> βοηθεῖν, DÉM. <i>1120, 26 ; avec idée d’hostilité,</i> marcher contre, marcher pour attaquer, IL. <i>15, 649, etc. ;</i><br><b>      3</b> (<i>à l’ao.2 act</i>.) passer du côté de : παραστῆναι εἰς γνώμην τινός, HDT. <i>6, 99,</i> se soumettre à l’avis de qqn ; π. τῷ πολέμῳ, DÉM. <i>597, 28,</i> se soumettre forcé par la guerre ; <i>d’où en gén</i>. se soumettre, se livrer, HDT. <i>3, 13 ; 5, 65, etc. ; avec un nom de chose pour suj</i>. approcher, avancer, <i>etc. ; en parl. de navires,</i> IL. <i>7, 467 ; en parl. d’événements,</i> être proche, imminent, IL. <i>16, 853 ;</i> OD. <i>9, 52 ; 24, 28, etc. ; p. suite, à l’ao. et au pf</i>. être présent : καί μοι καθ' ὕπνον δόξα τις παρεστάθη, EUR. <i>Rhes. 780,</i> mon âme eut en rêve une apparition ; ὅταν ὁρμὴ παραστῇ αὐτοῖς, <i>avec l’inf</i>. POL. <i>6, 44, 4,</i> quand il leur vient le désir de ; <i>au part</i>. παρεστηκώς, υῖα, ός, présent, PLAT. <i>Leg. 962</i> d, <i>etc. ; ion</i>. παρεσταώς, ANTH. <i>8, 201 ; att</i>. παρεστώς, ῶσα, ός (<i>non</i> παρεστώς) ; <i>fig</i>. παρ. τί τινι, qqe ch. vient à l’esprit de qqn, il vient à l’esprit de qqn de, <i>avec l’inf</i>. SOPH. <i>O.R. 911 ;</i> DÉM. <i>28, 1 ; impers</i>. παρίσταταί τινι, <i>avec l’inf. m. sign</i>. PAUS. <i>2, 19, 3 ;</i> τὸ παριστάμενον, LUC. <i>Char. 13 ; ou</i> τὸ παραστάν, LUC. <i>Am. 50,</i> ce qui vient à l’esprit de qqn, l’idée (subite), la pensée : ἐκ τοῦ παρισταμένου λέγειν, PLUT. <i>Dem. 9,</i> parler d’improvisation ;<br><b>   II</b> être mis dans une disposition d’esprit, s’attendre à, se résigner à, <i>avec</i> πρός <i>et l’acc</i>. DS. <i>17, 43 ; avec</i> εἰς <i>et l’acc</i>. POL. <i>11, 12, 2 ;</i><br><b>   III</b> tenir bon, être de sang-froid, DS. <i>17, 99 ;</i> PLUT. <i>Alc. 19 ;</i><br><b>   IV</b> se porter à côté, <i>d’où</i> s’emporter, être hors de soi, être irrité, POL. <i>23, 8, 13 ;</i> παρεστηκέναι τῶν φρενῶν, POL. <i>18, 366,</i> n’être pas dans son bon sens ; π. τῇ διανοίᾳ, POL. <i>15, 5, 7, etc. m. sign. ;</i><br><b>   V</b> <i>en parl. d’un liquide,</i> déposer, TH. <i>C.P. 6, 7, 5, etc. ;</i> DIOSC. <i>5, 16</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2, sbj. 3 duel poét</i>. παρστήετον (<i>p</i>. παραστῆτον) OD. <i>18, 183 ; impér. 2 sg. poét</i>. παράστα, MÉN. (<i>Bkk. p. 436, 18</i>) ; <i>part. poét</i>. παρστάς, IL. <i>10, 157 ; inf. poét</i>. παρεστάμεναι, OD. <i>20, 94, etc. ; pf. 3 sg. dor</i>. παρέστακε <span>[τᾱ]</span> PD. <i>P. 8, 100 ; sbj. 3 sg</i>. παραστήκῃ, HH. <i>Ven. 269 ; pf. réc. au sens tr</i>. παρέστακα <span>[τᾰ]</span> POL. <i>3, 94, 7 ; fut. antér. au sens intr</i>. παρεστήξω, THÉM. <i>115</i> a ; <i>ou</i> παρεστήξομαι, M. ANT. <i>10, 36</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παριστημι - παρίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 39 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (6)</li>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n<li>Actes (13)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (2)</li>\n<li>2 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G3937":"<h1>Parmenas</h1>\n<p>Strong n° 3937 <i>Prononciation [par-men-as']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Parménas (Angl. Parmenas) = « constant, durable »\n<ol><li>un des sept diacres de l'église à Jérusalem</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Παρμενας - Παρμενᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3938":"<h1>parodos</h1>\n<p>Strong n° 3938 <i>Prononciation [par'-od-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>en passant par, un passage</li>\n<li>pendant le passage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πάρ·οδος, ου (ἡ) :<br>   I</b> chemin à côté <i>ou</i> le long de :<br><b>      1</b> <i>particul</i>. chemin <i>ou</i> entrée à côté <i>ou</i> devant, THC. <i>3, 21 ;</i><br><b>      2</b> défilé, passe, passage, XÉN. <i>An. 4, 7, 4, etc. ;</i> DÉM. <i>119, 15, etc. ; fig</i>. PLUT. <i>M. 431</i> d ;<br><b>      3</b> couloir extérieur placé le long des rameurs thranites sur les deux bords d’un navire (<i>lat</i>. agea) ATH. <i>203</i> f ;<br><b>   II.1</b> action de passer le long de : ἐκ παρόδου, ARSTT. <i>G.A. 3, 6 ;</i> ἐν τῇ παρόδῳ, THC. <i>1, 126 ;</i> ἐν παρόδῳ POL. <i>5, 68, 8 ;</i> κατὰ τὴν πάροδον, POL. <i>22, 27, 12,</i> en passant ;<br><b>      2</b> action de s’avancer, ARSTT. <i>Nic. 4, 6 ;</i> PLUT. <i>M. 805</i> d ; ANTH. <i>11, 422 ; particul</i>. première entrée du chœur par le côté sur la scène dans la tragédie, POLL. <i>4, 108, etc. ; d’où</i> ἐκ παρόδου παρέρχεσθαι, ATH. <i>622</i> c, entrer par le côté ; <i>p. suite,</i> premier chant du chœur en entrant sur la scène, ARSTT. <i>Poet. 12 ;</i> PLUT. <i>M. 785</i> b.<br><span><b>Étym</b>. π. ὁδός.</span><br><br>\n➁ <b>πάρ·οδος, ου (ὁ)</b> <i>c</i>. παροδίτης, SPT. <i>Ezech. 16, 25</i>.<br><br>\n<b>παροδίτης, ου (ὁ)</b> <span>[ῑ]</span> voyageur qui passe, passant, HPC. <i>1280, 16 ;</i> ANTH. <i>9, 249</i>.<br><span><b>Étym</b>. πάροδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροδος - πάροδος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3939":"<h1>paroikeo</h1>\n<p>Strong n° 3939 <i>Prononciation [par-oy-keh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>demeurer à côté de quelqu'un ou dans son voisinage, vivre près de</li>\n<li>dans le N.T., être ou demeurer dans un lieu comme un étranger, séjourner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·οικέω-ῶ :<br>   I</b> habiter auprès, <i>d’où :</i><br><b>      1</b> habiter auprès de, être voisin de, <i>dat</i>. THC. <i>1, 71 ; avec mouv</i>. venir habiter près de, <i>acc</i>. ISOCR. <i>74</i> d ; <i>abs</i>. THC. <i>6, 82 ; en parl. de lieux,</i> être situé près de <i>ou</i> auprès, XÉN. <i>Vect. 1, 5 ;</i><br><b>      2</b> vivre au milieu de <i>ou</i> parmi, <i>dat</i>. THC. <i>3, 93 ;</i><br><b>   II</b> résider dans un pays comme étranger, SPT. <i>Gen. 12, 10 ;</i> NT. <i>Luc. 24, 18 ;</i> PHIL. <i>1, 416, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροικεω - παροικέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – demeurer, s'établir, temporairement\n<br><br> – demeurer, habiter, d'une façon permanente</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3940":"<h1>paroikia</h1>\n<p>Strong n° 3940 <i>Prononciation [par-oy-kee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui demeure proche, ou avec quelqu'un</li>\n<li>qui séjourne, qui demeure sur une terre étrangère</li>\n<li>métaph. la vie d'un homme ici sur la terre est semblable à un séjour, à un pèlerinage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παροικία, ας (ἡ)</b> séjour <i>ou</i> établissement en pays étranger, SPT. <i>Sap. 19, 10 ;</i> NT. <i>Ap. 13, 17</i>.<br><span><b>Étym</b>. πάροικος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροικια - παροικία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3941":"<h1>paroikos</h1>\n<p>Strong n° 3941 <i>Prononciation [par'-oy-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>demeurant près de, voisinage</li>\n<li>dans le N.T, un étranger, celui qui vit dans un lieu sans avoir le droit de cité, de citoyenneté</li>\n<li>métaph.\n<ol type=\"a\">\n<li>sans droit de cité dans le royaume de Dieu</li>\n<li>celui qui vit sur terre comme un étranger, un pèlerin sur la terre</li>\n<li>des Chrétiens dont la demeure est dans les cieux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πάρ·οικος, ος, ον</b> ; :<br><b>   I</b> qui demeure auprès, <i>d’où :</i><br><b>      1</b> voisin de, <i>gén</i>. ESCHL. <i>Pers. 869 ;</i> SOPH. <i>Ant. 1155 ; dat</i>. DIOG. (ATH. <i>636</i> a) ; THC. <i>3, 113 ; abs</i>. voisin, SAPPH. <i>80 ;</i> SOPH. <i>fr. 446 ;</i> ARSTT. <i>Rhet. 2, 21, 1 ;</i><br><b>      2</b> qui concerne un voisin : π. πόλεμος, HDT. <i>7, 235,</i> guerre avec des peuples voisins ;<br><b>      3</b> étranger, SPT. <i>Gen. 15, 3, etc. ; particul</i>. étranger domicilié dans une ville <i>ou</i> dans un pays sans droits politiques, DL. <i>1, 8, 2 ;</i> SPT. <i>Lev. 22, 10 ;</i> NT. <i>Ap. 7, 6, 29</i>.<br><span><b>Étym</b>. π. οἰκέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροικος - πάροικος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Ephésiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3942":"<h1>paroimia</h1>\n<p>Strong n° 3942 <i>Prononciation [par-oy-mee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un dire inhabituel ou différent de la manière usuelle de parler\n<ol type=\"a\">\n<li>une parole courante ou rebattue, un proverbe, un dicton</li>\n</ol>\n</li>\n<li>un dire sombre dont les ombres renforcent la vérité enseignée\n<ol type=\"a\">\n<li>spéc. un récit symbolique ou au figuré</li>\n<li>récit ou discours dans lequel une chose est illustrée par l'usage d'assimilations et de comparaisons</li>\n<li>une allégorie\n<ol>\n<li>métaphore étendue et élaborée</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παροιμία, ας (ἡ) :<br>      1</b> proverbe, ESCHL. <i>Ag. 264 ;</i> SOPH. <i>Aj. 664 ;</i> AR. <i>Th. 528 ;</i> κατὰ τὴν παροιμίαν, PLAT. <i>Conv. 222</i> b, selon le proverbe ;<br><b>      2</b> parabole, NT. <i>Joh. 10, 6</i>.<br><span><b>Étym</b>. π. οἴμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροιμια - παροιμία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (4)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3943":"<h1>paroinos</h1>\n<p>Strong n° 3943 <i>Prononciation [par'-oy-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>adonné au vin, ivrogne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πάροινος, ος, ον :<br>      1</b> d’ivrogne, ATH. <i>629</i> e ;<br><b>      2</b> ivre, PRATIN. <i>1, 10 ;</i> ANTIPH. (ATH. <i>445</i> c) ; LYS. <i>101, 20 ;</i> LUC. <i>Tim. 55 ;</i> DL. <i>1, 92</i>.<br><span><b>Étym</b>. π. οἶνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροινος - πάροινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G3944":"<h1>paroichomai</h1>\n<p>Strong n° 3944 <i>Prononciation [par-oy'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>s'en aller (en parlant du temps), être passé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·οίχομαι</b> <span>(<i>f</i>. -οιχήσομαι, <i>pf. act</i>. παρῴχηκα <i>ou</i> παρῴχημαι ; <i>pl.q.pf</i>. παρῳχήκειν, <i>v. ci-dessous</i>)</span><br><b>   I</b> aller au delà, <i>d’où :</i> être passé, IL. <i>4, 272 ; p. suite</i> passer, s’évanouir, disparaître : παροιχόμενοι ἄνδρες, PD. <i>N. 6, 50,</i> ceux qui sont morts ; π. δείματι, ESCHL. <i>Suppl. 738,</i> mourir de peur ; <i>en parl. du temps,</i> s’écouler, IL. <i>10, 252 ;</i> HDT. <i>8, 72, etc. ;</i> τὰ παροιχόμενα, HDT. <i>7, 120 ;</i> XÉN. <i>An. 2, 4, 1,</i> les choses passées ; ὁ παρῳχημένος χρόνος, PLUT. <i>M. 1081</i> c ; <i>subst</i>. ὁ παρῳχημένος (<i>s.-e</i>. χρόνος) SEXT. <i>M. 10, 119, 217, ou</i> τὸ παρῳχηκός, DYSC. <i>Synt. 269, etc</i>. le temps passé, <i>t. de gr. ;</i><br><b>   II</b> passer le long de <i>ou</i> au delà de, <i>d’où :</i><br><b>      1</b> éviter, se débarrasser de, <i>gén</i>. ESCHL. <i>Suppl. 452 ;</i><br><b>      2</b> s’écarter du droit chemin, s’égarer, s’éloigner de, être loin de se douter de, <i>gén</i>. EUR. <i>Med. 995</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. 3 sg</i>. παρῴχηκεν, IL. <i>10, 252, etc. ;</i> παρῴχημαι, NT. <i>Ap. 14, 16, etc. ; p. q. pf. 3 sg. ion</i>. παροιχώκεε, HDT. <i>8, 72</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροιχομαι - παροίχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3945":"<h1>paromoiazo</h1>\n<p>Strong n° 3945 <i>Prononciation [par-om-oy-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être comme</li>\n<li>ne pas être dissemblable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρομοιάζω</b>, avoir quelque ressemblance avec, <i>dat</i>. NT. <i>Matth. 23, 27</i>.<br><span><b>Étym</b>. παρόμοιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρομοιαζω - παρομοιάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G3946":"<h1>paromoios</h1>\n<p>Strong n° 3946 <i>Prononciation [par-om'-oy-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>semblable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·όμοιος, ος, ον</b>, qui a quelque ressemblance avec, presque semblable à, <i>dat</i>. HDT. <i>2, 73 ;</i> THC. <i>1, 132 ; abs</i>. HDT. <i>4, 99 ;</i> THC. <i>1, 80 ;</i> παρόμοιον ὅπερ, DÉM. <i>12, 9,</i> à peu près comme ; π. ὡσπερανεί, PLUT. <i>M. 4</i> d, à peu près comme si ; π. τοῖς Ἕλλησι τὸν ἀριθμόν, XÉN. <i>Hell. 3, 4, 13,</i> à peu près égaux en nombre avec les Grecs.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -α (<i>ion</i>. -η, HDT. <i>4, 183</i>) ; ISOCR. <i>Antid. § 192 ;</i> ARSTT. <i>H.A. 9, 14, 2, etc. ; épq</i>. παρομοίϊος, SIB. <i>2, 35</i>.<br><span><b>Étym</b>. π. ὅμοιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρομοιος - παρόμοιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G3947":"<h1>paroxuno</h1>\n<p>Strong n° 3947 <i>Prononciation [par-ox-oo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre tranchant, aiguiser\n<ol type=\"a\">\n<li>stimuler, éperonner, presser</li>\n<li>irriter, provoquer, pousser à la colère\n<ol>\n<li>mépriser</li>\n<li>rendre fâché</li>\n<li>être exaspéré, brûler de colère</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>paroxysme</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·οξύνω</b> <span>[ῡ]</span><br><b>   I</b> aiguiser contre, <i>fig. càd. :</i><br><b>      1</b> exciter, <i>acc</i>. XÉN. <i>Cyr. 6, 2, 5, etc. ;</i> τινὰ ἐπί τι, ISOCR. <i>82</i> c, <i>etc. ;</i> PLUT. <i>Them. 13 ;</i> πρός τι, POL. <i>2, 22, 2 ;</i> ἔς τι, HDN <i>5, 1, 6,</i> qqn à qqe ch. ; <i>avec un inf</i>. ISOCR. <i>240</i> b ; PLUT. <i>M. 1126</i> d, <i>etc. ; au pass</i>. POL. <i>1, 14, 1 ;</i> DS. <i>19, 18, etc.,</i> à faire qqe ch. ;<br><b>      2</b> <i>particul</i>. irriter, mettre en colère, DÉM. <i>403, 1, etc. ; au pass</i>. être irrité, THC. <i>6, 56 ;</i> DÉM. <i>70, 14, etc. ;</i> κατά τινος, PLUT. <i>Them. 31 ;</i> LUC. <i>Abd. 6, etc. ;</i> τινί, LYCURG. <i>158, 39 ;</i> DS. <i>Exc. 556, 76,</i> exciter contre qqn ;<br><b>      3</b> <i>t. de méd</i>. exacerber ; <i>au pass</i>. s’exacerber, HPC. <i>V. med. 10 ;</i><br><b>   II</b> marquer la pénultième d’un accent aigu, ATH. <i>323</i> c, <i>484</i> f.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροξυνω - παροξύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3948":"<h1>paroxusmos</h1>\n<p>Strong n° 3948 <i>Prononciation [par-ox-oos-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>inciter, être un instigateur, une incitation</li>\n<li>une irritation, une excitation, une exaspération</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παροξυσμός, οῦ (ὁ) :<br>   I</b> action d’exciter, de stimuler, NT. <i>Hebr. 10, 24 ;</i><br><b>   II</b> <i>en mauv. part :</i><br><b>      1</b> irritation, DÉM. <i>1105, 25 ;</i> NT. <i>Ap. 15, 39 ;</i><br><b>      2</b> paroxysme d’une maladie, HPC. <i>Aph. 1243</i>.<br><span><b>Étym</b>. παροξύνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροξυσμος - παροξυσμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3949":"<h1>parorgizo</h1>\n<p>Strong n° 3949 <i>Prononciation [par-org-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pousser à la colère, provoquer, exaspérer, irriter, courroucer, exciter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·οργίζω</b> <span>(<i>f. att</i>. ιῶ)</span> irriter, SPT. <i>3Reg. 16, 33, etc. ;</i> NT. <i>Rom. 10, 19, etc. ; au pass</i>. être irrité <i>ou</i> s’irriter, TH. <i>H.P. 9, 16, 6 ;</i> STR. <i>923 ;</i> πρός τινα, DÉM. <i>805, 19,</i> contre qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροργιζω - παροργίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3950":"<h1>parorgismos</h1>\n<p>Strong n° 3950 <i>Prononciation [par-org-is-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>indignation, courroux, colère, exaspération</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παροργισμός, οῦ (ὁ) :<br>      1</b> provocation, SPT. <i>3Reg. 15, 30, etc. ;</i><br><b>      2</b> irritation, NT. <i>Eph. 4, 26</i>.<br><span><b>Étym</b>. παροργίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροργισμος - παροργισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3951":"<h1>parotruno</h1>\n<p>Strong n° 3951 <i>Prononciation [par-ot-roo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>inciter, être l'instigateur, exciter, pousser, stimuler, d'où fanatiser, ameuter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·οτρύνω</b> <span>[ῡ]</span> exciter : τινὰ πρός τι, LUC. <i>Tox. 35,</i> qqn à qqe ch. ; <i>t. de méd</i>. stimuler, HPC. <i>654, 41</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροτρυνω - παροτρύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3952":"<h1>parousia</h1>\n<p>Strong n° 3952 <i>Prononciation [par-oo-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>présence</li>\n<li>la venue, l'arrivée, l'avènement\n<ol type=\"a\">\n<li>le retour futur et visible de Jésus depuis les cieux, pour ressusciter les morts, se tenir au jugement dernier, et établir formellement et glorieusement le royaume de Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρουσία, ας (ἡ) :<br>   I</b> présence, ESCHL. <i>Pers. 169 ;</i> SOPH. <i>El. 948 ;</i> EUR. <i>Alc. 606 ;</i> παρουσίαν ἔχειν, SOPH. <i>Aj. 540,</i> être présent ; <i>au plur</i>. EUR. <i>Thes. fr. 8, p. 899, Dindorf ; p. suite :</i><br><b>      1</b> état présent d’une chose, EUR. <i>Hec. 227 ;</i> PLAT. <i>Phæd. 100</i> d, <i>etc. ;</i><br><b>      2</b> occasion qui se présente, <i>particul</i>. occasion favorable, SOPH. <i>El. 1251 ;</i><br><b>      3</b> ressources présentes, biens, fortune, DÉM. (HARP.) ;<br><b>   II</b> action de se présenter, arrivée, SOPH. <i>El. 1104,</i> EUR. <i>Alc. 207 ;</i> THC. <i>1, 128 ;</i> DH. <i>1, 45</i>.<br><span><b>Étym</b>. παρών, <i>part. de</i> πάρειμι¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρουσια - παρουσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 24 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (3)</li>\n<li>Philippiens (2)</li>\n<li>1 Thessaloniciens (4)</li>\n<li>2 Thessaloniciens (3)</li>\n<li>Jacques (2)</li>\n<li>2 Pierre (3)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3953":"<h1>paropsis</h1>\n<p>Strong n° 3953 <i>Prononciation [par-op-sis']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un plat annexe, un plat de friandises ou de mets choisis destinés plus à ouvrir l'appétit qu'à le satisfaire\n<ol type=\"a\">\n<li>un accompagnement d'une nourriture plus consistante</li>\n</ol>\n</li>\n<li>le plat lui-même dans lequel les mets délicats sont servis</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·οψίς, ίδος (ἡ)</b> <span>[ῐδ]</span><br><b>      1</b> plat de friandises <i>ou</i> de hors-d’œuvre, XÉN. <i>Cyr. 1, 3, 4 ;</i> ARCHESTR. (ATH. <i>64</i> a), <i>etc. ;</i><br><b>      2</b> plat, assiette, PLUT. <i>M. 828</i> a ; NT. <i>Matth. 23, 65 ;</i> ARTÉM. <i>1, 74 ; fig</i>. MAGN. (<i>Com. fr. 2, 9</i>).<br><span><b>Étym</b>. π. ὄψον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παροψις - παροψίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G3954":"<h1>parrhesia</h1>\n<p>Strong n° 3954 <i>Prononciation [par-rhay-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>liberté dans les paroles, discours sans réserve\n<ol type=\"a\">\n<li>ouvertement, franchement, c.à.d sans dissimulation</li>\n<li>sans ambiguïté ou circonlocution</li>\n<li>sans l'usage de figures ou de comparaisons</li>\n</ol>\n</li>\n<li>confiance libre et intrépide, courage joyeux, hardiesse, assurance</li>\n<li>le maintien par lequel on se met en évidence et que l'on assure sa publicité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·ρησία, ας (ἡ)</b> liberté de langage, franchise, EUR. <i>Ion 672, Hipp. 422, etc. ;</i> DÉM. <i>73, 17 ;</i> παρρησίαν ἔχειν, EUR. <i>Ph. 391,</i> pouvoir parler librement ; παρρησίαν διδόναι, PLAT. <i>Leg. 694</i> b ; ISOCR. <i>20</i> c, donner la liberté de parler, <i>etc. ; en mauv. part,</i> liberté de langage excessive, ISOCR. <i>229</i>.<br><span><b>Étym</b>. <i>p</i>. *πανρησία, <i>de</i> πᾶν, ῥητός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρρησια - παρρησία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n31 fois dans 31 versets de 11 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (9)</li>\n<li>Actes (5)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (4)</li>\n<li>1 Jean (4)</li>\n</ul>\n</td></tr>\n</table>","G3955":"<h1>parrhesiazomai</h1>\n<p>Strong n° 3955 <i>Prononciation [par-hray-see-ad'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>user de liberté dans le discours, parler librement\n<ol type=\"a\">\n<li>parler franchement</li>\n</ol>\n</li>\n<li>grandir dans la confiance, avoir de la hardiesse, montrer de l'assurance, prendre un maintien hardi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρρησιάζομαι</b> <span>(<i>f</i>. άσομαι, <i>ao</i>. ἐπαρρησιασάμην, <i>pf. pass</i>. πεπαρρησίασμαι)</span><br><b>      1</b> parler en toute liberté, avec franchise : τινι, ESCHN. <i>11, 36 ;</i> πρός τινα, PLAT. <i>Lach. 178</i> a, à qqn ; περί τινος, DÉM. <i>287, 13,</i> parler franchement de qqe ch. ;<br><b>      2</b> <i>au pf. pass</i>. être dit franchement, <i>d’où part</i>. πεπαρρησιασμένος, η, ον, ISOCR. <i>312</i> b, dit franchement.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass. au sens moy</i>. DÉM. <i>55, 1</i>.<br><span><b>Étym</b>. παρρησία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παρρησιαζομαι - παρρησιάζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (7)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G3956":"<h1>pas</h1>\n<p>Strong n° 3956 <i>Prononciation [pas]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>individuellement\n<ol type=\"a\">\n<li>chacun, chaque, n'importe quel, l'entier, tout le monde, toutes choses, chaque chose</li>\n</ol>\n</li>\n<li>collectivement\n<ol type=\"a\">\n<li>de tous types</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πᾶς, πᾶσα, πᾶν</b>, <i>gén</i>. <b>παντός, πάσης, παντός</b> ; <i>plur</i>. <b>πάντες, πᾶσαι, πάντα</b> ; <i>gén</i>. <b>πάντων, πασῶν, πάντων</b> ; <i>dat</i>. <b>πᾶσι, πάσαις, πᾶσι</b>, <i>etc</i>. tout, toute :<br><b>A<br>   I</b> <i>au sg. :</i><br><b>      1</b> <i>au sens partitif,</i> chaque, chacun : οἱ δ' ἄλκιμον ἦτορ ἔχοντες πρόσσω πᾶς πέτεται, IL. <i>16, 265,</i> chacune de ces guêpes pleine d’ardeur vole en avant ; <i>cf</i>. OD. <i>13, 313 ;</i> SOPH. <i>O.R. 596, etc. ; avec un gén. :</i> πᾶς Ἑλλήνων, SOPH. <i>O.C. 597,</i> tout Grec, chaque Grec ; <i>avec un subst. sans article :</i> πᾶς ἀνήρ, THGN. <i>177 ;</i> SOPH. <i>Aj. 1366,</i> tout homme ; πᾶς ἄνθρωπος, ATT. tout être humain ; <i>avec un adj. ou un part. accompagné de l’art. :</i> πᾶς ὁ ἄδικος οὐχ ἑκὼν ἄδικος, PLAT. <i>Leg. 731</i> c, tout homme qui fait le mal mais sans le vouloir ; <i>cf</i>. SOPH. <i>Aj. 101 ;</i> XÉN. <i>Mem. 2, 4, 6, etc. ;</i> πᾶς τις, THGN. <i>621 ;</i> ESCHL. <i>Ag. 1205, 1652 ;</i> SOPH. <i>Aj. 28 ;</i> THC. <i>1, 20, etc</i>. tout homme (<i>cf. franç</i>. tout un chacun) ; <i>avec le gén. ;</i> πᾶς τις βροτῶν, SOPH. <i>El. 984,</i> tout mortel ; <i>cf</i>. HDT. <i>1, 50, etc. ;</i> πᾶς ὅστις, SOPH. <i>Aj. 1413,</i> tout homme qui ; πᾶν ὅσον, ESCHL. <i>Pr. 787, etc</i>. tout ce qui ; παντός ἐστι, <i>avec l’inf</i>. DÉM. <i>13, 17, etc</i>. c’est l’affaire de chacun de, <i>etc. ;</i><br><b>      2</b> tout entier, tout : πᾶς δ' ἄρα χαλκῷ λάμπε, IL. <i>11, 65,</i> il brillait tout entier d’airain ; <i>avec un subst. :</i> πᾶσαι πύλαι, IL. <i>2, 809,</i> les portes tout entières ; τὴν φάτνην ἐοῦσαν χαλκέην πᾶσαν, HDT. <i>9, 70,</i> la crèche toute d’airain, entièrement d’airain ; πᾶσαν ἀληθείην κατάλεξον, IL. <i>24, 407,</i> dis toute la vérité ; πᾶν κράτος, SOPH. <i>Ph. 142,</i> pleine puissance, <i>càd</i>. la plus haute puissance ; <i>avec l’art. :</i> κεῖνος ἡ πᾶσα βλάϐη, SOPH. <i>Ph. 622,</i> cet homme qui est le mal en personne ; πάντα εἶναί τινος, SOPH. <i>Ph. 386,</i> être tout à fait dépendant de qqn ; ὅλος καὶ πᾶς εἰμι πρός τι, POL. <i>3, 94, 10 ; ou</i> πρός τινι, POL. <i>5, 58, 1,</i> être tout entier à qqe ch., y employer toute son activité ;<br><b>   II</b> <i>au plur</i>. tous, <i>joint à un nom :</i> πάντες τε θεοὶ πᾶσαί τε θέαιναι, IL. <i>8, 5,</i> vous tous, dieux, et vous toutes, déesses ; <i>avec un gén. partit. :</i> Σαμίων πάντες, THC. <i>8, 75,</i> tous ceux des Samiens ; <i>cf</i>. XÉN. <i>Lac. 3, 3, etc. ;</i> πάντες ὅσοι, HOM. ATT. tous ceux qui ; <i>avec un adv. :</i> ἅμα πάντες, IL. <i>24, 253 ;</i> OD. <i>21, 230 ;</i> HDT. <i>9, 23,</i> tous ensemble, tous sans exception ; πάντες ὁμῶς, IL. <i>15, 98,</i> tous également ; <i>avec un superl. :</i> πάντες ἄριστοι, IL. <i>9, 3 ;</i> OD. <i>4, 272,</i> tous les meilleurs (<i>cf. lat</i>. optimus quisque) ; πᾶσι, IL. <i>2, 285 ;</i> SOPH. <i>O.C. 1448,</i> auprès de tous <i>ou</i> devant tous, <i>càd</i>. dans l’opinion de tous, d’après le jugement de tous ;<br><b>B</b> <i>construct. :</i><br><b>   I</b> <i>avec un subst. précédé ou non de l’article :</i><br><b>      1</b> <i>sans l’article, pour marquer que le subst. est employé au sens collect. :</i> tout entier : παντὶ σθένει, PLAT. <i>Leg. 646</i> a, avec toute sa force ; πᾶσα γῆ, THC. <i>2, 42,</i> toute la terre ; πάντες ἄνθρωποι, ATT. tous les hommes qu’on peut imaginer ; <i>au sens de plein, complet :</i> ἐν πάσῃ ἀναρχίᾳ καὶ ἀνομίᾳ, PLAT. <i>Rsp. 575</i> a, en dehors de toute autorité et de toute loi ; πᾶσα ἀνάγκη, PLAT. <i>Phædr. 240</i> a, il est tout à fait <i>ou</i> absolument nécessaire ; <i>de même au plur</i>. φρουρούμενος ὑπὸ πάντων πολεμίων, PLAT. <i>Rsp. 579</i> b, gardé par des hommes tous ennemis ;<br><b>      2</b> <i>avec l’article, soit avec l’article placé dev. le nom,</i> πᾶς <i>les précédant ou les suivant lorsqu’il est employé comme attribut :</i> τὸν ἀριθμὸν πάντα, PLAT. <i>Theæt. 147</i> e, le nombre tout entier ; πᾶσαν τὴν ἀλήθειαν λέγειν, THC. <i>6, 87,</i> dire toute la vérité ; πᾶν τοὐναντίον, ATT. tout le contraire ; τὰ ἀγαθὰ πάντα, XÉN. <i>An. 3, 1, 20,</i> tous les biens ; <i>soit précédé lui-même de l’article quand on veut marquer que la totalité est opposée aux parties isolées :</i> τὸ πᾶν, le tout, tout ensemble, ESCHL. <i>Pr. 273, etc. ;</i> SOPH. <i>Ph. 21 ;</i> THC. <i>1, 72 ;</i> τὰ πάντα, ESCHL. <i>Eum. 415, m. sign. ; d’où chez les philos</i>. τὸ πᾶν, l’univers, PLAT. <i>Pol. 272</i> e, <i>Tim. 28</i> c, <i>etc. ;</i> τὰ πάντα, XÉN. <i>Mem. 1, 1, 11 et 14, m. sign. ;</i> τὸ πᾶν πλῆθος τῶν ὁπλιτῶν, THC. <i>8, 93,</i> toute cette multitude d’hoplites ; ὁ πᾶς ἀριθμός, ESCHL. <i>Pers. 337 ;</i> THC. <i>2, 7,</i> le nombre total (des vaisseaux) ; τὰ πάντα μέρη, PLAT. <i>Theæt. 204</i> a, les parties prises toutes ensemble ; οἱ πάντες ἄνθρωποι, XÉN. <i>An. 5, 6, 7,</i> les hommes tous ensemble (sans exception) ; πόλις τοῖς πᾶσιν εὐπορωτάτη, THC. <i>2, 64,</i> ville la plus abondante en toutes choses ; τὸ πᾶν κράτος, HDT. <i>6, 35,</i> la puissance entière, la toute-puissance ; τῆς πάσης ἀλογίας, POL. <i>1, 15, 6, litt</i>. l’absurdité entière, <i>càd</i>. une complète absurdité ;<br><b>   II</b> <i>avec un n. de nombre précédé ou non de l’article :</i><br><b>      1</b> <i>sans l’article lorsqu’on veut appeler l’attention sur l’idée du détail :</i> ἐννέα πάντες, OD. <i>8, 258 ; 24, 60,</i> neuf complètement, neuf sans qu’il en manque un, pas moins que neuf ; <i>de même</i> δέκα π. IL. <i>19, 247 ; 24, 232 ;</i> ἕνδεκα π. OD. <i>14, 103 ;</i> δώδεκα π. OD. <i>9, 204, etc</i>. dix, onze, douze complètement ; <i>ou pour marquer une idée de variété :</i> κτήνεα πάντα τρισχίλια, HDT. <i>1, 50,</i> trois mille têtes de bétail de toute espèce ;<br><b>      2</b> <i>avec l’article, lorsqu’on veut appeler l’attention sur l’idée de l’ensemble :</i> τριάκοντα τὰς πάσας ἡμέρας, THC. <i>2, 101,</i> trente jours en tout ; οἱ πάντες ὡς ὀκτωκαίδεκα, XÉN. <i>Hell. 5, 4, 60,</i> dix-huit en tout ; <i>cf</i>. HDT. <i>1, 214 ;</i> THC. <i>1, 60, etc. ;</i><br><b>C</b> πᾶς <i>employé au neutre subst. ou adv. :</i><br><b>   I</b> τὸ πᾶν :<br><b>      1</b> le tout (<i>v. ci-dessus</i>, B, I, 2), la chose principale, l’important : τοῦ παντός, PLAT. <i>Phædr. 236</i> e, du tout au tout ; τοῦ παντὸς ἄξιος, PLAT. <i>Soph. 216</i> c, digne de tout ce qu’il y a de plus haut ;<br><b>      2</b> <i>adv. c</i>. πάντως, en tout, tout à fait, complètement, absolument, XÉN. <i>Cyr. 1, 6, 13 ;</i> SOPH. <i>El. 1009, etc. ; de même</i> ἐς τὸ πᾶν, ESCHL. <i>Eum. 52, 84 ;</i> τῷ παντί, XÉN. <i>Ages. 2, 24 ; Hell. 7, 5, 12, etc. ; avec idée de temps,</i> τὸ πᾶν, LUC. <i>Sacr. 5,</i> toujours ;<br><b>      3</b> tout, tout le possible : πᾶν μᾶλλον ἢ στρατιάν, HDT. <i>4, 162,</i> tout plutôt qu’une expédition ; περὶ παντὸς ποιεῖσθαι, ATT. estimer au-dessus de tout ; πᾶν ποιεῖν, PLAT. <i>Ap. 39</i> a, <i>ou</i> π. πράττειν, LYS. <i>115, 29,</i> faire tout son possible ; <i>d’ord. en ce sens :</i> πάντα π. XÉN. <i>Mem. 4, 2, 6 ;</i> LYS. <i>127, 42, etc. ;</i> πάντα ποιεῖν ὅπως, XÉN. <i>Hell. 7, 4, 21 ; ou</i> ὥστε, XÉN. <i>Hell. 6, 1, 4,</i> faire tout le possible pour que ; παντὸς μᾶλλον, plus que tout, au-dessus de tout, complètement, PLAT. <i>Prot. 344</i> b, <i>etc. ; avec le gén. :</i> ἐς πᾶν κακοῦ ἀφικνεῖσθαι, HDT. <i>7, 118,</i> en arriver à tout le malheur possible, à l’extrême malheur ; ἐν παντὶ ἀθυμίας εἶναι, THC. <i>7, 55,</i> être dans un découragement absolu ; <i>abs</i>. μάλ' ἂν φοϐοῖο καὶ ἐν παντὶ εἴης, PLAT. <i>Conv. 194</i> a, tu serais dans la plus grande inquiétude et dans le plus grand embarras ; εἰς πᾶν ἀφικνεῖσθαι, XÉN. <i>Hell. 6, 1, 12,</i> en venir à se trouver dans le plus grand danger ; διὰ παντός, pendant tout le temps, continuellement, toujours, HDT. <i>1, 122 ;</i> THC. <i>1, 38, etc. ;</i> XÉN. <i>An. 7, 8, 11 ;</i> SOPH. <i>Aj. 705, etc. ; ou</i> absolument, communément, généralement, THC. <i>2, 49 ;</i> PLAT. <i>1 Alc. 108</i> b, <i>etc. ;</i> διὰ πάντων, PLAT. <i>Soph. 254</i> b, <i>m. sign. ;</i> εἰς τὸ πᾶν <i>avec ou sans</i> χρόνου, ESCHL. <i>Eum. 670, Ch. 684, ou</i> μέχρι παντός, STR. <i>376, etc</i>. pour toujours ;<br><b>   II</b> πάντα : tout le possible : πάντα γίγνεσθαι, OD. <i>4, 417,</i> devenir toute sorte de choses, prendre toutes les formes, se changer en toute forme ; πάντα εἶναί τινι, être tout pour qqn, <i>càd</i>. l’homme <i>ou</i> la chose importante par excellence, THC. <i>8, 95 ;</i> DÉM. <i>240, 11 ; 660, 7 ;</i> LUC. <i>Tyr. 4 ; de même</i> τὰ πάντα, HDT. <i>1, 122, etc. ;</i> πάντα, en tout, à tous les points de vue, sous tous les rapports, OD. <i>13, 209 ; de même</i> τὰ πάντα, HDT. <i>5, 97 ; d’où</i> πάντα, tout à fait, entièrement, complètement, SOPH. <i>Aj. 91, 1415, El. 301, etc. ;</i> τὰ πολλὰ πάντα, HDT. <i>1, 203, etc</i>. la plupart du temps ; τὰ πάντα νικᾶν, XÉN. <i>An. 2, 1, 1,</i> vaincre sur tous les points ; <i>avec idée de temps,</i> continuellement, LUC. <i>As. 22 ; sur</i> διὰ πασῶν, <i>v</i>. διαπασῶν.<br><span><b><span class=\"arrow\"></span></b> <span>[ᾱ]</span> <i>au neutre</i> πᾶν, <i>au fém. à tous les cas, et au dat. plur. aux trois genres ; ttef</i>. <span>[ᾰ]</span> <i>dans</i> πάσης, ANTH. <i>8, 93, et dans</i> πάσιν, ANTH. <i>8, 109 ; de même</i> α <i>du neutre</i> πᾶν <i>est bref dans les composés</i> ἅπαν, πάμπαν, σύμπαν. — <i>Gén. pl. fém. épq</i>. πασάων <span>[σᾱ]</span> OD. <i>6, 107 ;</i> A. RH. <i>1, 113, etc. ; dat. pl. épq</i>. πάντεσσι, OD. <i>18, 317, etc</i>.<br><span><b>Étym</b>. <i>p</i>. *παντ-ς, <i>de indo-europ</i>. *ph₂-ent-, tout.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πας - πᾶς</font>\n<br><br>incluant toutes les formes de déclinaison</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1234 fois dans 1070 versets de 27 livres bibliques (NT)\n<ul>\n<li>Matthieu (129)</li>\n<li>Marc (68)</li>\n<li>Luc (151)</li>\n<li>Jean (65)</li>\n<li>Actes (168)</li>\n<li>Romains (70)</li>\n<li>1 Corinthiens (112)</li>\n<li>2 Corinthiens (53)</li>\n<li>Galates (16)</li>\n<li>Ephésiens (51)</li>\n<li>Philippiens (34)</li>\n<li>Colossiens (40)</li>\n<li>1 Thessaloniciens (18)</li>\n<li>2 Thessaloniciens (16)</li>\n<li>1 Timothée (24)</li>\n<li>2 Timothée (18)</li>\n<li>Tite (14)</li>\n<li>Philémon (2)</li>\n<li>Hébreux (51)</li>\n<li>Jacques (12)</li>\n<li>1 Pierre (18)</li>\n<li>2 Pierre (7)</li>\n<li>1 Jean (27)</li>\n<li>2 Jean (2)</li>\n<li>3 Jean (2)</li>\n<li>Jude (6)</li>\n<li>Apocalypse (60)</li>\n</ul>\n</td></tr>\n</table>","G3957":"<h1>pascha</h1>\n<p>Strong n° 3957 <i>Prononciation [pas'-khah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le sacrifice pascal (que le peuple avait coutume d'offrir en souvenir de sa délivrance d'Egypte)</li>\n<li>l'agneau pascal, agneau que les Israélites avaient coutume de tuer et manger le quatorzième jour du mois de Nisan (le premier mois de leur année) en mémoire du jour où leurs pères, se préparant à partir d'Egypte, furent appelés par Dieu à tuer et manger un agneau et à asperger les montants de leurs portes avec le sang, afin que l'ange destructeur, voyant le sang, passe au dessus de leurs demeures; Christ crucifié est semblable à l'agneau pascal sacrifié.</li>\n<li>le souper pascal</li>\n<li>la fête pascale, la fête de la Pâque, s'étendant du 14ème au 20ème jour du mois de Nisan</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πάσχα (τὸ)</b> <i>indécl. :</i><br><b>   I</b> <i>en gén</i>. la Pâque, <i>fête juive et chrétienne,</i> SPT. <i>Ex. 12, 11, etc. ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> le repas de la Pâque, NT. <i>Matth. 26, 17, etc. ;</i><br><b>      2</b> l’agneau pascal, SPT. <i>Ex. 12, 21, etc</i>.<br><span><b>Étym</b>. <i>hébr</i>. pâsach.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πασχα</font> &lt; פסח - <font face=\"Georgia\">πάσχα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n29 fois dans 27 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (5)</li>\n<li>Luc (7)</li>\n<li>Jean (10)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3958":"<h1>pascho</h1>\n<p>Strong n° 3958 <i>Prononciation [pas'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être affecté ou avoir été affecté, ressentir, avoir une expérience sensible, subir, éprouver, faire l'expérience\n<ol type=\"a\">\n<li>dans un bon sens, être bien, dans une bonne cause</li>\n<li>dans un mauvais sens, souffrir tristement, être dans un mauvais état, supporter\n<ol>\n<li>d'une personne malade</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πάσχω</b> <span>(<i>f</i>. πείσομαι, <i>ao.2</i> ἔπαθον, <i>pf</i>. πέπονθα)</span> <i>propr</i>. être affecté de telle <i>ou</i> telle façon, éprouver telle <i>ou</i> telle affection, sensation <i>ou</i> sentiment (<i>p. opp. à l’idée de</i> agir, δρᾶν, ESCHL. <i>Ch. 313,</i> SOPH. <i>O.R. 1272 ;</i> THC. <i>7, 71 ;</i> ποιεῖν, HDT. <i>5, 89 ;</i> XÉN. <i>Cyr. 7, 1, 40, etc.,</i> ἔρξαι, OD. <i>8, 490, etc.) ; p. suite :</i><br><b>A</b> <i>en parl. d’actions, de faits, d’événements :</i><br><b>   I</b> <i>en mauv. part :</i> ἄλγεα, IL. <i>20, 297, etc. ;</i> αἰνά, IL. <i>3, 99, etc.,</i> éprouver des douleurs, des maux, <i>etc. ; particul. au sens obscène,</i> DÉM. <i>270, 26, etc. ; dans la langue du droit att. pour parler d’une peine corporelle ou de la peine capitale, p. opp. à</i> ἀποτίνειν, payer une amende, PLAT. <i>Pol. 299</i> a ; <i>cf</i>. XÉN. <i>Mem. 2, 9, 5, etc. ;</i> πάσχειν, subir un châtiment, LYS. <i>160, 36 ;</i> π. τι πρός τινος, ESCHL. <i>Pr. 92 ;</i> HDT. <i>6, 88 ;</i> ὑπό τινος, ISOCR. <i>36</i> c, souffrir un châtiment <i>ou</i> éprouver un préjudice de la part de qqn ; <i>abs</i>. ἔγνω παθών, HÉS. <i>O. 220,</i> il a appris par des souffrances, par de fâcheuses expériences ; <i>cf</i>. SOPH. <i>O.R. 403 ;</i> PLAT. <i>Conv. 222</i> b ; ὁ παθών, le malheureux, PLAT. <i>Leg. 730</i> a ; <i>au sens phys</i>. le blessé, PLAT. <i>Leg. 878</i> c ; <i>abs</i>. être malade, ARR. <i>Epict. 2, 23, 12 ; en gén</i>. παθεῖν τι, souffrir qqe ch. de mal, de fâcheux, IL. <i>5, 567 ; 11, 470, etc. ;</i> OD. <i>4, 820 ;</i> XÉN. <i>Conv. 2, 11, etc. ; d’où par euphém. pour</i> mourir : εἴ τι πάθοιμι, ἤν τι πάθω, si je devais, dois souffrir qqe ch, <i>càd</i>. si je devais, dois mourir, CALLIN. <i>fr. 17 ;</i> HDT. <i>8, 102 ;</i> XÉN. <i>An. 7, 2, 14 ;</i> εἴ τι πείσονται οἱ Μῆδοι, XÉN. <i>Cyr. 2, 1, 2,</i> si un malheur devait arriver aux Mèdes, εἴ τι πείσεται ἅδε γᾶ, EUR. <i>Ph. 247,</i> si ce pays doit être vaincu ; ἤν τι ναῦς πάθῃ, EUR. <i>I.T. 755 ;</i> PLAT. <i>Ep. 312</i> d, <i>etc</i>. si le navire sombre ; τί (γὰρ) πάθω ; que va-t-il m’arriver ? que va-t-il arriver de moi ? <i>pour marquer l’attente de ce qu’il y a de pire,</i> IL. <i>11, 404 ;</i> OD. <i>5, 465 ;</i> HDT. <i>4, 118 ;</i> SOPH. <i>O.C. 216 ;</i> PLAT. <i>Euthyd. 302</i> d, <i>etc. ; de même</i> τί ἂν πάθοιμι ; LUC. <i>D. mort. 10, 6, etc. ; de même dans la locut</i>. τί παθών ; <i>litt</i>. ayant souffert quoi ? <i>càd</i>. qu’est-il arrivé de si fâcheux ? τί παθόντε λελάσμεθα θούριδος ἀλκῆς ; IL. <i>11, 313,</i> que nous est-il arrivé de si fâcheux, que nous ne nous souvenions pas de notre force ? τί παθόντες γαῖαν ἔδυτε ; OD. <i>24, 106,</i> quel malheur vous est survenu, pour que vous soyez descendus dans les enfers ? ;<br><b>   II</b> <i>en gén. avec un adv. :</i><br><b>      1</b> κακῶς πάσχειν, se trouver dans une fâcheuse position, dans un état fâcheux, être malheureux, OD. <i>16, 275 ;</i> ESCHL. <i>Pr. 751 ;</i> HDT. <i>3, 146, etc. ;</i> κακῶς πάσχειν ὑπό τινος, souffrir de la part de qqn du mal, un préjudice, un outrage, ESCHL. <i>Pr. 1043 ;</i> THC. <i>8, 48, etc. ;</i><br><b>      2</b> εὖ πάσχειν, être dans une bonne position, en une bonne situation, être heureux, PD. <i>P. 1, 191, etc. ;</i> SOPH. <i>Ph. 503, etc. ;</i> ἔκ τινος εὖ π. PLAT. <i>Phædr. 233</i> a, tirer du plaisir de qqe ch. ; <i>avec le gén</i>. τῶν αὑτοῦ κτεάνων εὖ πασχέμεν, THGN. <i>1009,</i> se réjouir de ce qu’on possède ; <i>abs</i>. recevoir un service, un bienfait, SOPH. <i>O.C. 1489 ;</i> THC. <i>2, 40 ;</i> XÉN. <i>Cyr. 1, 6, 45 ;</i> εὖ π. ὑπό τινος, PLAT. <i>Gorg. 519</i> c, recevoir un bienfait de qqn ; <i>de même avec un adj. :</i> π. τερπνόν τι, SOPH. <i>Aj. 521 ;</i> ἀγαθά, HDT. <i>2, 37,</i> éprouver qqe ch. d’agréable, du bien ; φιλικὰ ὑπό τινος, XÉN. <i>Cyr. 4, 6, 6,</i> recevoir de qqn des marques d’amitié ;<br><b>   III</b> <i>chez les Att. au sens mor. :</i><br><b>      1</b> se trouver dans telle <i>ou</i> telle disposition résultant des impressions et effets extérieurs : τοιοῦτον πάθος π. PLAT. <i>Ap. 22</i> c, <i>etc</i>. être dans telle disposition ; <i>d’où</i> être en proie à une émotion, à une passion, σώφρων ὁ μὴ πάσχων, ARSTT. <i>M. mor. 2, 6,</i> l’homme sage est celui qui n’a pas de passions violentes ; πάσχειν τι πρός τινα, XÉN. <i>Conv. 4, 11, etc</i>. venir à éprouver un sentiment pour qqn, une disposition envers qqn (et être sous l’empire de ce sentiment, de cette disposition) PLAT. <i>Gorg. 485</i> b, <i>etc. ;</i><br><b>      2</b> πάσχω τοῦτο, il en est ainsi de moi, voilà ce qui m’arrive, <i>en parl. de l’état mor. ou des impressions extérieures ;</i> ὅπερ ἂν οἱ πολλοὶ πάθοιεν, THC. <i>1, 80,</i> comme fait la multitude ; ὅπερ νῦν ἐς Λακεδαιμονίους πεπόνθατε, THC. <i>6, 11,</i> comme cela vous arrive maintenant à l’égard des Lacédémoniens ; τὰ αὐτά τινι πάσχειν, XÉN. <i>Mem. 2, 1, 5,</i> éprouver <i>ou</i> ressentir la même chose que qqn ; ἔδοξεν ὁμοιότατον πεπονθέναι ὥσπερ ἂν εἴ τις, PLAT. <i>Phæd. 98</i> c, il parut qu’il en était de même pour lui que…, si qqn ; κυϐερνήτου ἀγαθοῦ πάθος εἰ πάθοι, PLAT. <i>Ep. 351</i> d, s’il lui arrive ce qui arrive à un bon pilote ;<br><b>      3</b> <i>chez les Stoïciens,</i> recevoir une impression du dehors, <i>p. suite,</i> conserver dans l’esprit une impression, une idée, <i>d’où</i> πάσχειν ὅτι, ARR. <i>Epict. 1, 28 ; 3, 13,</i> se représenter, se figurer, penser qu’une chose est ;<br><b>   IV</b> <i>t. de gr</i>. être capable de modifications, éprouver des modifications (de forme, d’accent, de quantité), EM. <i>200, 10, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. inf. poét</i>. πασχέμεν, THGN. <i>1009 ;</i> PD. <i>P. 3, 104. Ao.2 sbj. 2 sg. épq</i>. πάθῃσθα, IL. <i>24, 551 ; inf. épq</i>. παθέειν, IL. <i>17, 32. Pf. épq. part. fém</i>. πεπαθυῖα <span>[πᾰ]</span> OD. <i>17, 555. Pf. dor</i>. πέποσχα, EPICH. <i>fr. 7 Ahrens. Pf. 2, 2 pl. poét</i>. πέποσθε (<i>p</i>. πεπόνθατε) IL. <i>3, 99 ;</i> OD. <i>23, 53. Pl.q.pf. att</i>. ἐπεπόνθη, PLAT. <i>Conv. 198 ; ion</i>. ἐπεπόνθεε, HDT. <i>3, 74</i>.<br><span><b>Étym</b>. <i>degré zéro :</i> πάσχω (<i>p</i>. *πάθ-σκ-ω), ἔπαθον ; <i>degré normal :</i> πείσομαι (<i>p</i>. *πένθ-σ-ομαι) ; <i>degré fléchi :</i> πέ-πονθ-α ; <i>p.-ê. d’une R. indo-europ</i>. b<sup>h</sup>end<sup>h</sup>-, lier, <i>avec un glissement sémantique</i> « être lié » → « souffrir », <i>cf</i>. πενθερός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πασχω - πάσχω</font>\n<br><br>apparemment un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 41 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (3)</li>\n<li>Luc (6)</li>\n<li>Actes (5)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (4)</li>\n<li>1 Pierre (12)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3959":"<h1>Patara</h1>\n<p>Strong n° 3959 <i>Prononciation [pat'-ar-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Patara = « éparpillement, malédiction »\n<ol><li>cité maritime de Lycie, réputée pour son oracle d'Apollon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πάταρα, ων (τὰ)</b> <span>[ᾰᾰρ]</span> Patares (<i>auj</i>. ruines près de Gelemiş) <i>v. de Lycie,</i> HDT. <i>1, 182 ;</i> POL. <i>22, 26 etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Παταρα - Πάταρα</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3960":"<h1>patasso</h1>\n<p>Strong n° 3960 <i>Prononciation [pat-as'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>frapper doucement : une partie ou un membre du corps</li>\n<li>donner un coup, frapper : avec l'épée, affliger, visiter par des maux, etc. comme avec une maladie mortelle</li>\n<li>percer, découper, tuer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πατάσσω</b> <span>[πᾰ]</span> <span>(<i>impf</i>. ἐπάτασσον, <i>f</i>. πατάξω, <i>ao</i>. ἐπάταξα, <i>pf. inus. ; pass. f</i>. παταχθήσομαι, ἐπατάχθην)</span><br><b>      1 <i>tr.</i></b> battre avec bruit, frapper, <i>acc</i>. AR. <i>Lys. 362 ;</i> PLAT. <i>Rsp. 333</i> e, <i>etc. ;</i> τινὰ δορί, EUR. <i>Ph. 1473,</i> qqn d’une javeline ; <i>avec l’acc. de moyen :</i> πληγήν, PLAT. <i>Gorg. 527</i> d, frapper un coup ; <i>avec un suj. de chose</i> (pierre, <i>etc</i>.) DÉM. <i>645, 16 ; en parl. d’un éclair,</i> ARSTT. <i>Meteor. 3, 1 ; d’une abeille,</i> A. TAT. <i>2, 7 ; fig. avec un suj. de chose</i> (désir, AR. <i>Ran. 54 ;</i> parole, A. TAT. <i>7, 3</i>) ;<br><b>      2 <i>intr.</i></b> battre avec bruit, palpiter, <i>en parl. du cœur :</i> στέρνοισι, IL. <i>13, 282 ;</i> ἐνὶ στήθεσσι, IL. <i>7, 216,</i> dans la poitrine.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. épq. 3 sg</i>. πάτασσε, IL. <i>23, 370 ;</i> πάτασσεν, IL. <i>7, 216</i>.<br><span><b>Étym</b>. πάταγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατασσω - πατάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G3961":"<h1>pateo</h1>\n<p>Strong n° 3961 <i>Prononciation [pat-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>marcher\n<ol type=\"a\">\n<li>piétiner, écraser avec les pieds</li>\n<li>avancer en posant le pied, marcher sur : vaincre heureusement les plus grands périls des machinations et persécutions que Satan mettrait volontiers pour contrarier la prédication de l'évangile</li>\n<li>fouler aux pieds, piétiner, traiter avec insulte et mépris: profaner la cité sainte par dévastation et outrage</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πατέω-ῶ</b> : <span>[ᾰ]</span><br><b>   I</b> fouler aux pieds, <i>acc. :</i><br><b>      1</b> <i>au pr</i>. SOPH. <i>Aj. 1146 ; cf</i>. PLAT. <i>Theæt. 135</i> a, <i>Phædr. 248</i> a, <i>etc. ; particul</i>. fouler le raisin, pressurer le raisin, HYBRIAS (ATH. <i>696</i> a) ;<br><b>      2</b> <i>fig</i>. fouler aux pieds : ὅρκια, IL. <i>4, 157 ;</i> τὴν δίκην, SOPH. <i>Aj. 1335,</i> des serments, la justice ; <i>joint à</i> λάξ, ESCHL. <i>Eum. 110, etc. ; p. suite,</i> traiter avec mépris, traiter outrageusement, <i>acc</i>. PLUT. <i>Tim. 14 ;</i> LUC. <i>Lex. 10, etc. ; p. anal</i>. piller, saccager (une ville) HLD. <i>4, 19 ;</i><br><b>   II</b> <i>particul. en parl. d’un chemin,</i> fouler le sol, <i>d’où :</i><br><b>      1 <i>intr.</i></b> s’avancer, marcher : ὁδοῖς σκολιαῖς, PD. <i>P. 2, 157,</i> par des routes obliques ; πρὸς βωμόν, ESCHL. <i>Ag. 1298,</i> vers l’autel ;<br><b>      2 <i>tr.</i></b> fouler en marchant, mettre le pied sur : δωμάτων πύλας, ESCHL. <i>Ch. 732 ;</i> χῶρον, SOPH. <i>O.C. 37 ;</i> γαῖαν, THCR. <i>Idyl. 18, 20,</i> sur le seuil d’une maison, sur le sol d’un pays, sur la terre ; <i>p. anal</i>. πόντον, OPP. <i>C. 2, 217 ;</i> ἅλα, ANTH. <i>7, 532,</i> parcourir la mer ; <i>fig</i>. SYN. <i>4, 163</i> d ; <i>p. ext</i>. parcourir sans cesse, user à force de parcourir (un ouvrage, <i>etc.) acc</i>. AR. <i>Av. 471 ;</i> PLAT. <i>Phædr. 273</i> a ; <i>p. suite,</i> user, perdre (le temps) <i>acc</i>. PD. <i>O. 1, 185</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. ματέω, SAPPH. <i>fr. 60 (46) Bgk</i>.<br><span><b>Étym</b>. <i>cf. p.-ê</i>. πόντος, <i>lat</i>. pōns.</span><br><br>\n➁ <b>πατέω</b> <span>[ᾰ]</span> ORION ; <i>d’ord. au moy</i>. <b>πατέομαι</b> <span>(<i>ao</i>. ἐπασάμην, <i>pf</i>. πέπασμαι)</span> manger, se nourrir, s’abreuver de, <i>abs</i>. IL. <i>24, 641 ; avec l’acc</i>. IL. <i>1, 464, etc. ;</i> HÉS. <i>Th. 642 ; ou le gén. partit</i>. ESCHL. <i>Sept. 1035 ; Ag. 1408 ;</i> NIC. <i>Al. 310 ;</i> OD. <i>1, 124 ; 9, 87, etc. ;</i> SOPH. <i>Ant. 202 ;</i> HDT. <i>1, 73 ; 2, 37, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. poét</i>. πασάμην, IL. <i>21, 76 ; épq. avec double</i> σ : ἐπασσάμεθ', OD. <i>9, 87 ; inf</i>. πάσσασθαι, OD. <i>10, 384 ; part</i>. πασσάμενος, OD. <i>1, 124, etc. ; pl.q.pf. poét</i>. πεπάσμην, IL. <i>24, 642 ; part. fém. dor</i>. πασαμένα, ESCHL. <i>Ag. 1408</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ph₂t-, faire paître ; <i>cf. angl</i>. feed ; <i>élargissement de la</i> R. *peh₂-, protéger, faire paître, <i>cf</i>. ποιμήν, πῶμα¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατεω - πατέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G3962":"<h1>pater</h1>\n<p>Strong n° 3962 <i>Prononciation [pat-ayr']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\t\n<li>géniteur ou ancêtre mâle\n<ol type=\"a\">\n<li>soit le plus proche parent : père de la nature corporelle, les pères naturels, les parents</li>\n<li>un ancêtre plus ancien, fondateur d'une race ou d'une tribu, créateur d'un peuple, ancêtre: tels Abraham, Jacob et David\n<ol>\n<li>pères : ancêtres, fondateurs d'une race</li>\n</ol>\n</li>\n<li>celui qui est avancé en âge, un aîné</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>celui qui est à l'origine et transmet toute chose\n<ol>\n<li>l'auteur d'une famille ou société de personnes qui sont animées du même esprit que lui-même</li>\n<li>celui qui a mis son propre esprit dans les autres, qui anime et gouverne leurs esprits</li>\n</ol>\n</li>\n<li>celui qui se tient à la place d'un père et veille sur un autre d'une manière paternelle</li>\n<li>un titre d'honneur\n<ol>\n<li>enseignants, ceux de qui les élèves reçoivent connaissance et savoir</li>\n<li>les membres du Sanhédrin, dont les prérogatives sont de prendre en charge les intérêts des autres par la vertu de la sagesse et l'expérience dans lesquelles ils excellent</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>Dieu est appelé le Père\n<ol type=\"a\">\n<li>des étoiles, luminaires célestes, car il est leur créateur, qu'il les soutient, qu'il est leur souverain</li>\n<li>de tous les êtres intelligents et rationnels, que ce soit les anges ou les hommes, car il les a créés, les préserve, les garde et qu'il est leur protecteur\n<ol>\n<li>de tous les êtres spirituels, de tous les hommes</li>\n</ol>\n</li>\n<li>des Chrétiens, ceux qui à travers Christ ont été élevés, spécialement mis à part, dans une intime relation avec Dieu, et qui ne le voient plus comme un juge sévère en tant que pécheurs, mais le révèrent comme un Père aimant avec qui ils se sont réconciliés</li>\n<li>le Père de Jésus Christ, comme étant celui qui l'a uni à lui dans un lien étroit d'amour et d'intimité, qui l'a associé à ses desseins, l'a désigné pour expliquer et porter parmi les hommes le plan du salut, et lui a fait également partager sa propre nature divine\n<ol>\n<li>par Jésus-Christ lui-même</li>\n<li>par les apôtres</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πατήρ</b>, <i>voc</i>. <b>πάτερ</b> ; <i>gén</i>. <b>πατέρος</b>, <i>att. et poét</i>. <b>πατρός</b> ; <i>dat</i>. <b>πατέρι</b>, <i>att. et poét</i>. <b>πατρί</b> ; <i>acc</i>. <b>πατέρα</b> ; <i>plur. nom</i>. <b>πατέρες</b>, <i>gén</i>. <b>πατέρων</b>, <i>dat</i>. <b>πατράσι</b>, <i>acc</i>. <b>πατέρας (ὁ)</b> <span>[πᾰ]</span><br><b>   I</b> père, IL. <i>5, 156, etc. ;</i> OD. <i>11, 500, etc. ;</i> ATT. <i>etc. ; en parl. de Zeus,</i> père de toutes choses, HOM. ESCHL. <i>Sept. 512 ;</i> SOPH. <i>Ph. 1142, etc. ;</i> πατρὸς πατήρ, IL. <i>14, 118 ;</i> OD. <i>19, 180, etc</i>. le père du père, le grand-père, aïeul ; <i>au pl</i>. οἱ πατέρες :<br><b>      1</b> les parents, <i>càd</i>. le père et la mère, PLAT. <i>Leg. 772</i> b ; DH. <i>2, 26 ;</i> DS. <i>Exc. 561, 23, etc. ;</i><br><b>      2</b> les ancêtres, IL. <i>6, 209 ;</i> OD. <i>8, 245 ;</i> PD. <i>O. 2, 13 ;</i> EUR. <i>Andr. 766 ;</i> THC. <i>2, 11, 71, etc. ;</i><br><b>      3</b> fondateurs d’une race, souche, métropole, HDT. <i>7, 51 ; 8, 22 ;</i> PLUT. <i>Them. 9, etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> père, <i>titre de respect et d’affection qu’on donnait aux vieillards,</i> AR. <i>Ach. 225 ;</i> OD. <i>7, 28, 48 ; 8, 145, etc. ;</i><br><b>      2</b> auteur <i>ou</i> inventeur d’une chose, PD. <i>P. 4, 314, etc. ;</i> PLAT. <i>Tim. 28</i> c, <i>41</i> a, <i>etc. ;</i><br><b>      3</b> <i>p. ext</i>. ce qui est la source de, <i>particul</i>. capital producteur d’intérêts, PLAT. <i>Rsp. 555</i> e.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. pl. hom</i>. πατρῶν, OD. <i>4, 687 ; 8, 245 ; dat. poét. réc</i>. πατέρεσσι, Q. SM. <i>10, 40</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ph₂tēr, père <i>comme chef de famille ; cf. lat</i>. pater, <i>sscr</i>. pitár-, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατηρ - πατήρ</font>\n<br><br>apparemment un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n415 fois dans 369 versets de 26 livres bibliques (NT)\n<ul>\n<li>Matthieu (63)</li>\n<li>Marc (19)</li>\n<li>Luc (57)</li>\n<li>Jean (136)</li>\n<li>Actes (34)</li>\n<li>Romains (15)</li>\n<li>1 Corinthiens (6)</li>\n<li>2 Corinthiens (5)</li>\n<li>Galates (5)</li>\n<li>Ephésiens (11)</li>\n<li>Philippiens (4)</li>\n<li>Colossiens (5)</li>\n<li>1 Thessaloniciens (5)</li>\n<li>2 Thessaloniciens (3)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (9)</li>\n<li>Jacques (4)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (14)</li>\n<li>2 Jean (4)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G3963":"<h1>Patmos</h1>\n<p>Strong n° 3963 <i>Prononciation [pat'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Patmos = « mortel, fascinant »\n<ol><li>une île rude et nue dans la Mer Egée, proche de Rhodes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πάτμος, ου (ἡ)</b> Patmos (<i>auj</i>. Pátmos) <i>une des Sporades,</i> THC. <i>3, 33, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πατμος - Πάτμος</font>\n<br><br>de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3964":"<h1>patraloas</h1>\n<p>Strong n° 3964 <i>Prononciation [pat-ral-o'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un parricide, celui qui a tué son père</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>πατρ·ολέτωρ, ορος (ὁ)</b> meurtrier de son père, parricide, ANTH. <i>11, 348</i>.<br><span><b>Étym</b>. π. <i>th</i>. ὀλε- <i>de</i> ὄλλυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατραλωας - πατρολῴας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3965":"<h1>patria</h1>\n<p>Strong n° 3965 <i>Prononciation [pat-ree-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>les Israélites, divisés en douze tribus, descendant des douze fils de Jacob, ces tribus étant divisées en familles elles-mêmes divisées en maisons</li>\n<li>famille, au sens le plus large, nation, peuple</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πατριά, ᾶς (ἡ) :<br>   I</b> descendance, lignée, <i>particul</i>. du côté paternel, HDT. <i>3, 75 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> race, famille, SPT. <i>Ex. 12, 3, etc. ;</i> NT. <i>Eph. 3, 15 ;</i><br><b>      2</b> tribu, caste, HDT. <i>1, 200</i>.<br><i>Ion</i>. -ίη, HDT. <i>l. c</i>.<br><span><b>Étym</b>. πατήρ.</span><br><br>\n➁ <b>πατρία</b>, <i>fém. de</i> πάτριος.<br><br>\n<b>πάτριος, ος</b> <i>ou</i> <b>α, ον :<br>      1</b> du père, PD. <i>O. 2, 26, etc. ;</i> SOPH. <i>O.R. 1394, Ant. 806, etc. ;</i><br><b>      2</b> des pères, des ancêtres, HDT. <i>1, 172 ;</i> THC. <i>2, 16, etc. ;</i> PLAT. <i>Leg. 793</i> b, <i>etc. ;</i> τὸ πάτριον, THC. <i>4, 86,</i> la règle <i>ou</i> la coutume des ancêtres ; τὰ πάτρια, AR. <i>Ach. 1000 ;</i> THC. <i>2, 2, etc</i>. les coutumes, les institutions, les lois des ancêtres ; πάτριόν ἐστι, <i>avec le dat</i>. ATT. ; <i>avec l’inf</i>. THC. <i>1, 123 ;</i> PLAT. <i>Hipp. ma. 284</i> b, c’est une coutume qui a passé des pères aux enfants de, <i>etc</i>.<br><span>•<i> Cp</i>. -ώτερος, ISOCR. <i>48</i> a, qui provient plutôt des ancêtres, plus ancien.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, EUR. <i>Hel. 222, etc. ; de même dans les inscr. att</i>. CIA. <i>2, 332, 15 (271/265 av. J.C.), etc. ; v. Meisterh. p. 116, § 58, 2</i>.<br><span><b>Étym</b>. πατήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατρια - πατριά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3966":"<h1>patriarches</h1>\n<p>Strong n° 3966 <i>Prononciation [pat-ree-arkh'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>patriarche, fondateur d'une tribu\n<ol type=\"a\">\n<li>des douze fils de Jacob, fondateurs des tribus d'Israël</li>\n<li>Abraham, Isaac et Jacob</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πατρι·άρχης, ου (ὁ)</b> auteur <i>ou</i> chef d’une famille, patriarche, SPT. <i>1Par. 27, 22 ;</i> NT. <i>Ap. 2, 29 ; 7, 8 ; Hebr. 7, 4</i>.<br><span><b>Étym</b>. πατριά¹, ἄρχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατριαρχης - πατριάρχης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3967":"<h1>patrikos</h1>\n<p>Strong n° 3967 <i>Prononciation [pat-ree-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>paternel, héréditaire, hérité ou reçu de ses pères</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πατρικός, ή, όν :<br>   I</b> du père, <i>càd. :</i><br><b>      1</b> qui vient du père, transmis <i>ou</i> légué par le père, PLAT. <i>Soph. 242</i> a ; ARSTT. <i>Nic. 10, 9, 12, etc. ; particul. en parl. d’amitié ou d’inimitié héréditaires dans une famille</i> (ami, XÉN. <i>Hell. 6, 5, 4 ;</i> PLAT. <i>Lach. 180</i> e, <i>etc. ;</i> hôte, THC. <i>8, 6, etc. ;</i> ennemis, ISOCR. <i>79</i> d ; amitié, ISOCR. <i>1</i> b ; inimitié, DÉM. <i>530, 8</i>) ; ἡ πατρική (<i>s.-e</i>. οὐσία) EUR. <i>Ion 1034,</i> patrimoine ; τὰ πατρικά, <i>m. sign</i>. ANTH. <i>11, 75 ; ou</i> la maison paternelle, SPT. <i>Sir. 42, 10 ;</i><br><b>      2</b> semblable à un père, à la façon d’un père, de père, paternel, ARSTT. <i>Nic. 8, 10 ;</i> POL. <i>32, 11, 1 ;</i> PLUT. <i>M. 802</i> f ;<br><b>      3</b> ἡ πατρικὴ πτῶσις, CHŒROB. <i>10, 30 Gaisf</i>. le cas qui marque la descendance, le génitif ;<br><b>   II</b> des pères, des ancêtres (institutions, THC. <i>1, 13 ;</i> vertus, THC. <i>7, 69 ;</i> lois, CRAT. <i>dans</i> ATH. <i>667</i> f, <i>etc</i>.).<br><span><b>Étym</b>. πατήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατρικος - πατρικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote une descendance de père à fils\n<br><br> – indique une descendance de personnes en amitié ou inimitié</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G3968":"<h1>patris</h1>\n<p>Strong n° 3968 <i>Prononciation [pat-rece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>son pays natal\n<ol type=\"a\">\n<li>la terre de ses pères, son propre pays, la demeure fixe, le logis</li>\n<li>son propre lieu de naissance, la cité</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πατρίς, ίδος</b> <span>[ῐδ]</span><br><b>      1</b> <i>adj. f</i>. des ancêtres, <i>p. suite,</i> de la patrie, ESCHL. <i>Sept. 585 ;</i> SOPH. <i>O.R. 641 ;</i> EUR. <i>Ph. 287 ;</i><br><b>      2</b> <i>subst</i>. ἡ π. (<i>s.-e</i>. γῆ <i>ou</i> χώρα) IL. <i>5, 213 ;</i> OD. <i>4, 586 ; 9, 34, etc. ;</i> ESCHL. <i>Pers. 403 ;</i> THC. <i>6, 69,</i> terre des ancêtres, patrie ; <i>au plur</i>. PLAT. <i>Pol. 308</i> a ; DÉM. <i>324, 20 ; 327, 10</i>.<br><span><b>Étym</b>. πατήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατρις - πατρίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3969":"<h1>Patrobas</h1>\n<p>Strong n° 3969 <i>Prononciation [pat-rob'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Patrobas = « paternel »\n<ol><li>un certain Chrétien dans Rome</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πατροβας - Πατροβᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G3970":"<h1>patroparadotos</h1>\n<p>Strong n° 3970 <i>Prononciation [pat-rop-ar-ad'-ot-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>reçu ou hérité de ses pères ou ancêtres</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πατρο·παράδοτος, ος, ον</b>, transmis de père en fils, DS. <i>17, 4 ;</i> DH. <i>5, 48 ;</i> NT. <i>1Petr. 1, 18</i>.<br><span><b>Étym</b>. π. παράδοτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατροπαραδοτος - πατροπαράδοτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3971":"<h1>patroos</h1>\n<p>Strong n° 3971 <i>Prononciation [pat-ro'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>descendance du père au fils ou venant des ancêtres à leur postérité comme par un droit d'héritage</li>\n<li>reçu des pères</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πατρωός, οῦ (ὁ)</b> beau-père, PLUT. <i>Cleom. 11, etc</i>.<br><span><b>Étym</b>. πατήρ.</span><br><br>\n➁ <b>πατρῷος, ῴα, ῷον :<br>   I</b> du père, paternel, <i>càd. :</i><br><b>      1</b> provenant du père, appartenant au père, hérité du père (bâton, IL. <i>2, 46 ;</i> javeline, IL. <i>19, 387 ;</i> demeure, IL. <i>21, 44 ;</i> HÉS. <i>O. 374 ;</i> champ, PD. <i>I. 1, 51 ;</i> siège, ESCHL. <i>Pr. 228, etc</i>.) ; π. οὐσία, ALEX. (ATH. <i>165</i> d) biens paternels ; κλῆρος, PLAT. <i>Leg. 923</i> d, héritage paternel : <i>abs</i>. τὰ πατρῷα (πατρώϊα), le bien paternel, hérité du père, OD. <i>17, 80 ; 20, 336 ; 21, 61 ;</i> PLAT. <i>Rsp. 568</i> e, <i>etc. ;</i> π. ἤθη, PLAT. <i>Leg. 855</i> a, mœurs paternelles ; πατρῴα δόξα, DÉM. <i>150, 26,</i> gloire paternelle ; πατρῴαν πρὸς στάθμαν, PD. <i>P. 6, 45,</i> selon la façon du père ;<br><b>      2</b> qui concerne le père : π. ἆθλος, SOPH. <i>Ant. 856,</i> la lutte du père ; π. πήματα, SOPH. <i>El. 258,</i> les douleurs de la maison paternelle ; π. φόνοι, SOPH. <i>El. 779, etc</i>. meurtre consommé sur le père ; π. ξεῖνος, OD. <i>1, 187,</i> hôte du père, avec qui le père était lié ;<br><b>   II</b> des pères, des ancêtres : γαῖα π. OD. <i>13, 188, 251 ;</i> γῆ π. SOPH. <i>El. 67, Tr. 163,</i> la terre des ancêtres, la patrie ; θεοὶ π. ESCHL. <i>Pers. 404 ;</i> SOPH. <i>El. 411, etc. ;</i> XÉN. <i>Hell. 2, 4, 21, etc. ;</i> PLAT. <i>Leg. 717</i> b, <i>etc</i>. les dieux des ancêtres, <i>càd</i>. de la famille, de la race, du pays ; π. δόξα, XÉN. <i>Hell. 7, 5, 16,</i> la gloire des ancêtres ; π. θυσίαι, DÉM. <i>1481, 26,</i> sacrifices transmis par les ancêtres.<br><span><b><span class=\"arrow\"></span></b> <i>Fém. poét</i>. πατρῷος, ESCHL. <i>Ag. 210 ;</i> DÉM. <i>1481, 26 ;</i> <span>[ω <i>bref</i>]</span> EUR. <i>Hec. 78, Tr. 166, Bacch. 1367, El. 1315, Alc. 259 ; poét</i>. πατρώϊος, OD. <i>17, 80 ; 20, 336 ; 22, 61</i>.<br><span><b>Étym</b>. πατήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πατροως - πατρῷος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote une descendance de père à fils\n<br><br> – indique une descendance de personnes en amitié ou inimitié</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G3972":"<h1>Paulos</h1>\n<p>Strong n° 3972 <i>Prononciation [pow'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Paul ou Paulus = « petit » « faible »\n<ol>\n<li>Paul fut le plus fameux des apôtres, qui écrivit une grande partie du Nouveau Testament, les 14 épîtres Pauliniennes</li>\n<li>Paulus était député ou pro-consul de Chypre, connu comme homme prudent en affaires et gouvernement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Παῦλος, ου (ὁ)</b> = <i>lat</i>. Paulus, Paul :<br><b>      1</b> <i>n. d’h. rom</i>. PLUT. <i>Syll. 12, Æmil. 12, etc. ;</i><br><b>      2</b> <i>particul., n. d’un apôtre</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Παυλος - Παῦλος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n162 fois dans 158 versets de 15 livres bibliques (NT)\n<ul>\n<li>Actes (132)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Philémon (3)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3973":"<h1>pauo</h1>\n<p>Strong n° 3973 <i>Prononciation [pow'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire cesser ou désister</li>\n<li>préserver une chose ou une personne de quelque chose</li>\n<li>cesser, laisser, abandonner</li>\n<li>avoir obtenu d'être libéré du péché\n<ol type=\"a\">\n<li>ne plus être attiré par ses incitations et séductions</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παύω</b> <span>(<i>impf</i>. ἔπαυον, <i>f</i>. παύσω, <i>ao</i>. ἔπαυσα, <i>pf</i>. πέπαυκα ; <i>pass. f</i>. παυθήσομαι, <i>ao</i>. ἐπαύθην, <i>pf</i>. πέπαυμαι)</span><br><b>A <i>tr. :</i><br>   I</b> <i>avec un seul rég. :</i><br><b>      1</b> <i>avec un acc. de pers.,</i> calmer, apaiser, IL. <i>21, 314 ;</i> troubler, SOPH. <i>Ant. 963 ;</i> supprimer, détruire, OD. <i>20, 274 ;</i> DC. <i>56, 4 ;</i><br><b>      2</b> <i>avec un acc. de chose :</i> faire cesser (des maux, une guerre, une querelle, la colère, <i>etc</i>.) IL. <i>4, 191, etc. ;</i> SOPH. <i>El. 795, etc. ; ou un gén</i>. OD. <i>4, 35, etc.,</i> — terminer : λόγον, XÉN. <i>Cyr. 8, 6, 7,</i> un discours ; — laisser reposer ; τόξον, OD. <i>21, 279,</i> un arc ; — détruire (des murs, DC. <i>69, 9 ; fig</i>. la tyrannie, DÉM. <i>478, 6</i>) ;<br><b>   II</b> <i>avec double rég. :</i><br><b>      1</b> <i>avec un acc. de pers. et un gén. de chose,</i> retenir, détourner : τινά τινος, qqn de qqe ch. (d’un combat, IL. <i>15, 15,</i> d’une fatigue, IL. <i>21, 137 ;</i> τῆς ἔξω ξυμμαχίας, THC. <i>3, 65,</i> détacher de l’alliance étrangère) ; <i>p. suite,</i> faire que qqn se repose (d’une fatigue, d’une joie, d’une douleur) ; faire que qqn s’abstienne (de désirs, XÉN. <i>Mem. 1, 2, 5 ;</i> de faute, PLAT. <i>Leg. 784</i> c, <i>etc</i>.) ; déposséder de (d’une charge, XÉN. <i>Cyr. 8, 6, 3 ;</i> d’un commandement, XÉN. <i>Hell. 6, 2, 13, etc</i>.) ;<br><b>      2</b> <i>avec un acc. de chose et un gén. de chose :</i> πόδας ὀρχηθμοῖο, OD. <i>23, 298,</i> détourner les pieds de la danse, faire cesser la danse, <i>etc. ;</i><br><b>      3</b> <i>avec un acc. de pers. et un gén. de chose précédé d’une prép. :</i> παῦσον ἐκ κακῶν ἐμέ, SOPH. <i>El. 987,</i> délivre-moi du mal ; παύουσι (τοὺς παῖδας) ἀπὸ παιδαγωγῶν, XÉN. <i>Lac. 3, 1,</i> ils reprennent les enfants aux pédagogues, ils ne les leur confient plus ;<br><b>      4</b> <i>avec un acc. de pers. ou de chose accompagné d’un part. prés. :</i> γελῶντας ἐχθροὺς παύσομεν, SOPH. <i>El. 1295,</i> nous ferons cesser le rire des ennemis, nous ferons en sorte qu’ils cessent de rire ; πόλιν δυστυχοῦσαν παῦσαι, ISOCR. <i>16</i> c, faire que la ville cesse d’être malheureuse ; τὴν φιλοσοφίαν π. τοῦτο λέγουσαν, PLAT. <i>Gorg. 482</i> c, faire que la philosophie cesse de dire cela ; στρατηγοῦντα δ' αὐτὸν ἐπαύσατε, DÉM. <i>1187, 17,</i> vous l’avez dépossédé de sa charge de général ;<br><b>      5</b> <i>avec un acc. de pers. suivi d’un inf</i>. ἔμ' ἔπαυσας μάχεσθαι, IL. <i>11, 442,</i> tu m’as arrêté (forcé de m’arrêter) lorsque je combattais ; ῥαψῳδοὺς ἔπαυσε ἀγωνίζεσθαι, HDT. <i>5, 67,</i> il interdit aux rhapsodes de chanter ; <i>avec</i> μή <i>dev. l’inf</i>. θνητούς γ' ἔπαυσα μὴ προδέρκεσθαι μόρον, ESCHL. <i>Pr. 248,</i> j’ai fait que les mortels ont cessé de craindre l’approche de la mort ; <i>cf</i>. AR. <i>Ach. 634, etc. ;</i><br><b>B <i>intr.</i></b> cesser, <i>avec le gén</i>. OD. <i>4, 659 ; particul. à l’impér. :</i> παῦε μάχης, HÉS. <i>Sc. 449,</i> cesse le combat ; παῦε ὀρχούμενος, AR. <i>Pax 326,</i> cesse de danser ; <i>abs. :</i> παῦε, μὴ λέξῃς πέρα, SOPH. <i>Ph. 1275,</i> cesse, ne parle pas davantage ; <i>cf</i>. PLAT. <i>Phædr. 228</i> e ; <i>redoublé :</i> παῦε, παῦε, μὴ βόα, AR. <i>Av. 1504,</i> cesse, cesse, ne crie pas ;<br><b><i>Moy</i>. παύομαι</b> <span>(<i>f</i>. παύσομαι, <i>ao</i>. ἐπαυσάμην, <i>pf</i>. πέπαυμαι)</span> cesser :<br><b>   I</b> <i>abs. en parl. de pers. :</i><br><b>      1</b> cesser (de parler, de chanter, de combattre, <i>etc</i>.) IL. <i>8, 295 ; 21, 373 ;</i> OD. <i>4, 103 ; 16, 405 ;</i> HDT. <i>7, 9, etc. ;</i> SOPH. <i>O.C. 1040, etc. ;</i> XÉN. <i>An. 1, 3, 13, etc. ;</i> PLAT. <i>Conv. 185</i> c, <i>etc. ; p. suite,</i> se modérer, se calmer, IL. <i>14, 260,</i> — se reposer (sur une couche) IL. <i>24, 17 ;</i> se tenir inactif, HDT. <i>1, 83 ;</i><br><b>      2</b> <i>en parl. de choses :</i> αἷμα ἐπαύσατο, IL. <i>11, 267,</i> le sang cessa de couler ; ἵδρως παύετο, IL. <i>15, 242,</i> la sueur avait cessé ; ἄνεμος ἐπαύσατο, OD. <i>12, 168, etc</i>. le vent cessa de souffler, s’apaisa ; <i>cf</i>. OD. <i>5, 384, 391 ;</i> HDT. <i>7, 193 ;</i> πέπαυται, THC. <i>1, 6,</i> la chose a cessé ;<br><b>   II</b> <i>avec un rég. : avec le gén. de la chose,</i> se désister de, s’abstenir de : πολέμοιο, IL. <i>7, 376, etc. ;</i> μάχης, HDT. <i>1, 74, etc.,</i> suspendre le combat ; πόνου, IL. <i>1, 467,</i> terminer le travail ; γόοιο, OD. <i>8, 540,</i> cesser de gémir ; κλαγγῆς, IL. <i>2, 100,</i> cesser de crier, <i>etc. ;</i> ὀργῆς, LYCURG. <i>152, 25,</i> cesser d’être irrité ;<br><b>   III</b> <i>rar. avec le gén. précédé de</i> ἐκ, AR. <i>Ran. 1531 ;</i><br><b>   IV</b> <i>avec un part. prés</i>. ὅθ' ὕπνος ἕλοι, παύσαιτό τε νηπιαχεύων, IL. <i>22, 502,</i> lorsque le sommeil le prenait et qu’il avait cessé de jouer ; πέπαυμαι θρηνῶν, ESCHL. <i>Pr. 615,</i> j’ai cessé de gémir ; παύεται διψῶν, XÉN. <i>Cyr. 1, 3, 11,</i> il cesse d’avoir soif ; πέπαυμαι λέγων, PLAT. <i>Phæd. 100</i> b, j’ai fini de parler.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. épq</i>. παυέμεναι, OD. <i>10, 22. Impf. itér</i>. παύεσκον, OD. <i>22, 315 ;</i> SOPH. <i>Ant. 963. Ao. sbj. 3 sg</i>. παύσῃσι, IL. <i>4, 191 ; 1 pl. épq</i>. παύσομεν, IL. <i>21, 314. Moy. impf. itér. 3 sg</i>. παυέσκετο, IL. <i>24, 17 ; ao. opt</i>. παυσαίμαν, EUR. <i>Ion 152</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παυω - παύω</font>\n<br><br>un verbe racine (« pause »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 7 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Actes (6)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G3974":"<h1>Paphos</h1>\n<p>Strong n° 3974 <i>Prononciation [paf'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Paphos = « bouillant ou chaud »\n<ol><li>cité maritime à l'extrémité ouest de Chypre, avec un port. c'était la résidence d'un pro-consul Romain. « le Vieux Paphos » était connu pour son culte et son sanctuaire de Vénus (Aphrodite) et se trouvait à une dizaine de kilomètres vers le sud-est.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πάφος, ου (ἡ)</b> <span>[ᾰ]</span> Paphos (<i>auj</i>. Páfos, Paphos) <i>v. de Chypre, avec un temple à Aphrodite,</i> OD. <i>8, 363 ;</i> HH. <i>Ven. 59</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Παφος - Πάφος</font>\n<br><br>de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G3975":"<h1>pachuno</h1>\n<p>Strong n° 3975 <i>Prononciation [pakh-oo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être épais, rendre gras, engraisser, épaissir</li>\n<li>métaph. devenir stupide (avec une âme ennuyeuse ou insensible)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παχύνω</b> <span>[ᾰῡ]</span> (<i>pass. ao</i>. ἐπαχύνθην, <i>pf</i>. πεπάχυμμαι <i>ou</i> πεπάχυσμαι) :<br><b>   I</b> rendre épais, <i>càd. :</i><br><b>      1</b> rendre gros, lourd, épaissir, <i>acc</i>. PLAT. <i>Gorg. 518</i> c, <i>etc. ; d’où au pass</i>. devenir épais, gros, lourd, XÉN. <i>Conv. 2, 17 ;</i> PLUT. <i>Sol. 20 ; fig</i>. grossir, enfler, <i>en parl. de la prospérité,</i> ESCHL. <i>Sept. 771 ;</i><br><b>      2</b> <i>en b. part :</i> rendre fort, XÉN. <i>Œc. 12, 20 ;</i><br><b>      3</b> épaissir, rendre consistant, <i>en parl. de liquides</i> (sang, <i>etc</i>.) HPC. <i>1175</i> g ; <i>au pass</i>. s’épaissir, se coaguler, ARSTT. <i>G.A. 2, 2, 7, etc. ;</i><br><b>      4</b> envelopper d’un voile épais, <i>au pass</i>. DP. <i>35 ;</i><br><b>   II</b> <i>fig</i>. rendre lourd, hébéter, PLUT. <i>M. 995</i> d ; <i>au pass</i>. SPT. <i>Esaï. 6, 10 ;</i> NT. <i>Matth. 13, 15</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass</i>. πεπάχυμμαι, GAL. <i>6, 379 ;</i> πεπάχυσμαι, PHILSTR. <i>514</i>.<br><span><b>Étym</b>. παχύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">παχυνω - παχύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3976":"<h1>pede</h1>\n<p>Strong n° 3976 <i>Prononciation [ped'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un fer, un lien pour les pieds</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέδη, ης (ἡ) :<br>   I</b> entrave, lien pour les pieds, <i>d’ord. au pl. pour les chevaux,</i> IL. <i>13, 36 ; pour les hommes,</i> THGN. <i>539 ;</i> HDT. <i>5, 77, etc. ;</i> PLAT. <i>Leg. 882</i> b ; PLUT. <i>Nic. 19, etc. ; fig</i>. ESCHL. <i>Pr. 6, etc. ;</i> SOPH. <i>Tr. 1057 ;</i> POL. <i>17, 11, 51, etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> anneau de femme, <i>pour les jambes,</i> SOL. <i>fr. 3, 33 Bgk ;</i> AR. <i>fr. 309, 11 Dind. ;</i> LUC. <i>Lex. 9 ;</i><br><b>      2</b> <i>sorte d’exercice équestre,</i> XÉN. <i>Eq. 7, 13, 14</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ped-, pied ; <i>cf</i>. πούς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεδη - πέδη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3977":"<h1>pedinos</h1>\n<p>Strong n° 3977 <i>Prononciation [ped-ee-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>de niveau, plaine, plat, uni</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεδινός, ή, όν</b> <span>[ῑ]</span><br><b>      1</b> qui forme une plaine, qui est en plaine, HDT. <i>7, 198 ;</i> PLAT. <i>Leg. 704</i> d ;<br><b>      2</b> qui a lieu en plaine, POL. <i>1, 34, 8 ;</i><br><b>      3</b> qui vit dans les plaines, XÉN. <i>Cyn. 5, 17 ;</i> TH. <i>H.P. 1, 8, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Var</i>. πεδιεινός, <i>d’où</i> πεδεινός, πεδινός. <i>• Cp</i>. -ώτερος <span>[ῐ]</span> XÉN. <i>An. 5, 5, 2 p.-ê. mauv. leç. ;</i> πεδιεινότερος, PLAT. <i>l. c</i>.<br><span><b>Étym</b>. πεδίον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεδινος - πεδινός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3978":"<h1>pezeuo</h1>\n<p>Strong n° 3978 <i>Prononciation [ped-zyoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>voyager à pieds (non à cheval ou en voiture), ou, en opposition au voyage par mer, voyager sur terre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεζεύω<br>   I <i>intr.</i></b> aller par terre, <i>abs</i>. XÉN. <i>An. 5, 5, 4, etc. ;</i> π. περὶ τὴν τροφήν, ARSTT. <i>H.A. 8, 3,</i> chercher sa subsistance sur terre ; πόδα π. ἐπὶ γαίας, EUR. <i>Alc. 872,</i> fouler du pied la terre ; π. διὰ τῆς θαλάσσης, ISOCR. <i>58</i> e, aller sur mer comme sur la terre ferme ; π. ὁδόν, STR. <i>282,</i> faire route par terre ;<br><b>   II <i>tr</i>.<br>      1</b> traverser à pied, <i>acc</i>. PHILSTR. <i>252 ; d’où au pass</i>. être traversé <i>ou</i> parcouru à pied, LUC. <i>Rh. præc. 18 ;</i><br><b>      2</b> transporter par voie de terre, <i>au pass</i>. STR. <i>189</i>.<br><span><b>Étym</b>. πεζός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεζευω - πεζεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3979":"<h1>peze</h1>\n<p>Strong n° 3979 <i>Prononciation [ped-zay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>à pied (et non à cheval)</li>\n<li>par terre (et non par mer)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεζῇ</b>, <i>adv. v</i>. πεζός.<br><br>\n<b>πεζός, ή, όν :<br>A</b> <i>adj. :</i><br><b>   I</b> pédestre, <i>càd. :</i><br><b>      1</b> qui va à pied : στρατός, HDT. <i>4, 128 ; 7, 84,</i> infanterie ; ὁ πεζός, <i>dans</i> HOM. guerrier combattant à pied, <i>p. opp. à</i> ἱππεῖς, IL. <i>8, 59 ; 11, 150 ; ou à</i> ἵπποι, IL. <i>5, 13 ;</i> OD. <i>9, 50 ; 17, 436 ; postér</i>. soldat de pied, ESCHL. <i>Pers. 19 ; ou (s.-e</i>. στρατός) infanterie, HDT. <i>1, 80, etc. ;</i><br><b>      2</b> qui est à pied, pédestre, <i>en parl. de statues, p. opp. aux statues équestres,</i> PLUT. <i>Rom. 16 ;</i><br><b>   II</b> de terre, <i>càd. :</i><br><b>      1</b> qui va par terre, sur terre, OD. <i>1, 173 ; 4, 190 ; 16, 59, etc. ;</i> PD. <i>P. 10, 47 ;</i> ESCHL. <i>Pers. 558, 719 ;</i> π. στρατός, ESCHL. <i>Pers. 728,</i> armée de terre ; ὁ πεζός (<i>s.-e</i>. στρατός) HDT. <i>3, 25 ; 6, 45 ;</i> στρατιὰ πεζή, THC. <i>1, 47 ; 6, 33 ;</i> τὸ πεζόν, HDT. <i>4, 97 ; 6, 95 ; 7, 121,</i> armée de terre ;<br><b>      2</b> qui se fait <i>ou</i> se produit sur terre (combat, PLAT. <i>Leg. 707</i> c ; danger, ISOCR. <i>59</i> c, <i>etc</i>.) ;<br><b>      3</b> qui vit sur terre : πεζὰ θηρία, PLAT. <i>Conv. 207</i> a, animaux qui vivent sur la terre ; πεζὴ θήρα, PLAT. <i>Soph. 222</i> b, chasse (<i>p. opp. à pêche</i>) ;<br><b>   III</b> qui ne s’élève pas de terre, <i>d’où :</i><br><b>      1</b> de prose, prosaïque (<i>cf. lat</i>. sermo <i>ou</i> oratio pedestris) PAUS. <i>4, 6, 1 ;</i> DC. <i>69, 3 ;</i><br><b>      2</b> <i>en gén</i>. uni, simple, commun, terre à terre, PLUT. <i>M. 853</i> c, <i>etc. ;</i> μέλη πεζά, SOPH. <i>fr. 15,</i> paroles sans musique <i>ou</i> musique sans paroles ; πεζαὶ ἑταῖραι, THPP. COM. (ATH. <i>532</i> c) hétaïres de bas étage, <i>càd</i>. qui n’ont ni culture ni goût pour les arts ;<br><b>B</b> <i>adv</i>., πεζῇ :<br><b>      1</b> à pied, XÉN. <i>Œc. 5, 5 ;</i><br><b>      2</b> par terre, sur terre, HDT. <i>7, 110, 115 ;</i> THC. <i>4, 132 ;</i> XÉN. <i>An. 5, 6, 1 ;</i> PLAT. <i>Pol. 289</i> e ;<br><b>      3</b> en prose, PLAT. <i>Soph. 237</i> a, <i>etc</i>.<br><span>•<i> Cp</i>. πεζότερος, PLUT. <i>M. 804</i> c ; <i>sup</i>. πεζότατος, SUID. <i>v°</i> ψυχή.<br><span><b>Étym</b>. <i>p</i>. *πεδϳός, <i>cf. sscr</i>. pád-ya-, concernant le pied ; <i>v</i>. πούς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεζη - πεζῇ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G3980":"<h1>peitharcheo</h1>\n<p>Strong n° 3980 <i>Prononciation [pi-tharkh-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>obéir (à un souverain ou un supérieur)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πειθαρχέω-ῶ</b>, obéir aux magistrats <i>ou</i> aux lois, <i>d’où en gén</i>. obéir à, <i>dat</i>. SOPH. <i>Tr. 1178 ;</i> AR. <i>Eccl. 762 ;</i> XÉN. <i>Mem. 3, 5, 19 ;</i> PLAT. <i>Rsp. 538</i> d ; ISOCR. <i>29</i> c ; ARSTT. <i>Pol. 4, 11, 4 ; abs</i>. ARSTT. <i>Pol. 3, 15, 14 ;</i><br><b><i>Moy.</i></b> <i>m. sign. abs</i>. HDT. <i>6, 91</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Moy. inf. prés</i>. πειθαρχέεσθαι, HDT. <i>l. c</i>.<br><span><b>Étym</b>. πείθαρχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πειθαρχεω - πειθαρχέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G3981":"<h1>peithos</h1>\n<p>Strong n° 3981 <i>Prononciation [pi-thos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>persuasif, attirant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πειθός, ή, όν</b>, <i>c</i>. πιθανός, NT. <i>1Cor. 2, 4</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πειθος - πειθός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3982":"<h1>peitho</h1>\n<p>Strong n° 3982 <i>Prononciation [pi'-tho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>persuader\n<ol type=\"a\">\n<li>persuader, faire croire par des mots</li>\n<li>se faire un ami de, gagner la faveur, chercher à gagner quelqu'un, lutter pour plaire à quelqu'un</li>\n<li>rendre tranquille</li>\n<li>donner avec persuasion l'envie à quelqu'un de faire quelque chose</li>\n</ol>\n</li>\n<li>être persuadé\n<ol type=\"a\">\n<li>être persuadé, accepter de se laisser persuader ; être poussé à croire, avoir la foi dans une chose\n<ol>\n<li>croire</li>\n<li>être persuadé d'une chose concernant une personne</li>\n</ol>\n</li>\n<li>écouter, obéir à, céder à, se soumettre à</li>\n</ol>\n</li>\n<li>se confier à, avoir confiance, être confiant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πειθώ, όος-οῦς (ἡ) :<br>   I</b> <i>act. :</i><br><b>      1</b> faculté <i>ou</i> talent de persuader, éloquence persuasive, persuasion, ESCHL. <i>Pr. 172, etc. ;</i> XÉN. <i>Mem. 1, 7, 5 ;</i> PLAT. <i>Leg. 722</i> b, <i>etc. ;</i><br><b>      2</b> discours propre à persuader, éloquence, EUR. <i>I.A. 104 ; ou en gén</i>. moyen de persuader, AR. <i>Nub. 1398 ;</i><br><b>   II</b> <i>pass. :</i><br><b>      1</b> persuasion qu’on a dans l’esprit, ESCHL. <i>Ag. 385 ;</i><br><b>      2</b> docilité, obéissance, XÉN. <i>Cyr. 2, 3, 19 ; 3, 3, 8</i>.<br><span><b>Étym</b>. πείθω.</span><br><br>\n➁ πείθω<br>   I</b> <i>tr. aux temps suiv. (f</i>. πείσω, <i>ao.1</i> ἔπεισα, <i>ao.2 poét</i>. ἔπιθον <span>[ῐ]</span>, <i>pf</i>. πέπεικα ; <i>pass. f</i>. πεισθήσομαι, <i>ao</i>. ἐπείσθην, <i>pf</i>. πέπεισμαι) :<br><b>      1</b> persuader, convaincre : τινά, HOM. ATT. qqn ; φρένας τινός, IL. <i>9, 184, etc. ;</i> OD. <i>1, 43 ;</i> φρένας τινί, IL. <i>22, 78 ;</i> θυμόν τινος, IL. <i>9, 587 ;</i> OD. <i>23, 230 ;</i> θυμόν τινι, IL. <i>4, 104, etc</i>. l’esprit <i>ou</i> le cœur de qqn ; <i>avec un acc. de pers. et l’inf</i>. IL. <i>22, 223, etc. ;</i> ESCHL. <i>Eum. 724 ;</i> EUR. <i>Med. 982 ;</i> PLAT. <i>Euthyd. 272</i> c ; πείθειν ἑκόντα τινὰ ποιεῖν τι, XÉN. <i>An. 5, 1, 14,</i> persuader qqn de faire qqe ch. de bon gré ; <i>de même avec</i> ὡς, XÉN. <i>Mem. 1, 1, 1 ;</i> PLAT. <i>Rsp. 327</i> c ; <i>avec</i> ὥστε <i>et l’inf</i>. THC. <i>3, 31, 70, 75, etc. ; avec</i> ὥστε μή <i>et l’inf</i>. SOPH. <i>Ph. 901 ; postér. avec</i> ὅπως, PLUT. CLÉOM. <i>6 ;</i> πείθω ἐμαυτόν, je me persuade, <i>càd</i>. je suis convaincu, je crois, <i>comme</i> πείθομαι, THC. <i>6, 33 ;</i> XÉN. <i>Œc. 20, 15 ;</i> PLAT. <i>Gorg. 453</i> a, <i>etc. ;</i> DÉM. <i>5, 3, etc. ; au part</i>. ἡμᾶς δεῦρο πείσας ἀπήγαγεν, XÉN. <i>An. 7, 6, 9,</i> après nous avoir persuadés, il nous a amenés ici de notre consentement ; <i>de même</i> πείθων, <i>p. opp. à</i> βίᾳ, XÉN. <i>An. 5, 5, 11 ;</i> πείσας <i>p. opp. à</i> βίᾳ πράξας, POÈT. (PLUT. <i>M. 751</i> d) ; <i>à</i> ἐν δόλῳ, SOPH. <i>Ph. 102 ; avec la nég</i>. μὴ πείσας, PLAT. <i>Leg. 844</i> f, sans avoir persuadé, <i>càd</i>. sans avoir obtenu l’autorisation ; <i>cf</i>. PLAT. <i>Leg. 913</i> a, <i>etc. ;</i><br><b>      2</b> enjôler, circonvenir, engager par ruse, <i>d’où</i> séduire, surprendre, tromper, IL. <i>1, 132 ; 6, 360 ;</i> OD. <i>2, 106 ; 14, 123 ;</i><br><b>      3</b> fléchir par des prières, amollir, adoucir, apaiser, IL. <i>9, 112,</i> etc., HÉS. <i>Sc. 450 ;</i> XÉN. <i>An. 3, 1, 26 ; en mauv. part,</i> amollir <i>ou</i> gagner par de l’argent, corrompre, HDT. <i>8, 134, etc. ;</i> XÉN. <i>An. 1, 3, 19 ;</i><br><b>      4</b> <i>en gén</i>. gagner les bonnes grâces de, <i>acc</i>. XÉN. <i>Cyr. 6, 1, 34 ;</i><br><b>      5</b> stimuler, exciter, mettre en mouvement : θυέλλας, les tempêtes, IL. <i>15, 26, propr</i>. les persuader de souffler ;<br><b>      6</b> <i>en gén</i>. s’efforcer d’amener qqn à adopter une opinion, à participer à une entreprise, à suivre un conseil, XÉN. <i>Hell. 6, 5, 16 ; An. 5, 9, 19 ; 7, 2, 2 ;</i> POL. <i>4, 64, 2 ;</i><br><b>      7</b> <i>avec double accus</i>. πείθειν τινά τι, persuader qqe ch. à qqn, persuader <i>ou</i> convaincre qqn de qqe ch. HDT. <i>1, 163 ;</i> ESCHL. <i>Pr. 1063, etc. ;</i> XÉN. <i>Hier. 1, 16 ; avec l’accus. de la chose seul. :</i> π. ἃ μὴ δεῖ, SOPH. <i>O.C. 1442,</i> persuader ce qu’il ne faut pas ; <i>d’où au pass</i>. χρήμασι πεισθῆναι τὴν ἀναχώρησιν, THC. <i>2, 21,</i> avoir été persuadé à prix d’argent de se retirer ;<br><b>   II</b> <i>intr. (au pf</i>. πέποιθα <i>et au pl.q.pf</i>. ἐπεποίθειν, <i>au sens d’un prés. et d’un impf</i>.) se fier, se confier, s’en remettre à, <i>dat</i>. PD. <i>P. 10, 99, etc. ;</i> ESCHL. <i>Ch. 237, 297 ;</i> PLAT. <i>Menex. 248</i> a, <i>etc. ; avec un dat. et un inf</i>. IL. <i>13, 96 ; 16, 171 ;</i> OD. <i>16, 71 ; 21, 132 ; avec un dat. et un part</i>. OD. <i>16, 98 ; abs</i>. ὄφρα πεποίθῃς, IL. <i>1, 524 ;</i> OD. <i>13, 344,</i> afin que tu prennes confiance ; <i>de même avec l’inf</i>. avoir la confiance de <i>ou</i> que, compter que, <i>etc</i>. ESCHL. <i>Sept. 444 ;</i> SOPH. <i>Aj. 769, etc. ;</i><br><b><i>Moy</i>. πείθομαι</b> <span>(<i>f</i>. πείσομαι, <i>ao.2</i> ἐπιθόμην)</span> <i>et pass. (f</i>. πεισθήσομαι, <i>ao</i>. ἐπείσθην, <i>pf</i>. πέπεισμαι) :<br><b>      1</b> se laisser persuader : λόγῳ, ESCHL. <i>Pr. 1014 ;</i> EUR. <i>Andr. 870, etc</i>. par des paroles ; <i>avec l’inf</i>. THC. <i>6, 34, etc. ; abs. à l’impér. :</i> πείθου, laisse-toi persuader, SOPH. <i>O.C. 511, etc. p. opp. à</i> πιθοῦ, obéis (<i>v. ci-dessous</i>) ;<br><b>      2</b> πείθεσθαί τινι, HOM. ATT. obéir à qqn ; τοῖς ἐν τέλει βεϐῶσι, SOPH. <i>Ant. 67 ;</i> τοῖς ἄρχουσι, XÉN. <i>Cyr. 1, 2, 8,</i> aux magistrats ; τῷ νόμῳ, XÉN. <i>An. 7, 3, 39,</i> à la loi ; τῷ θεῷ, PLAT. <i>Ap. 29</i> d, à la divinité ; <i>avec double dat. :</i> τινι ἔπεσι, IL. <i>1, 150 ;</i> τινι μύθοις, IL. <i>23, 157,</i> obéir aux paroles de qqn ; πείθεσθαι μύθῳ, OD. <i>17, 177,</i> obéir à la parole ; γήραϊ πείθεσθαι, IL. <i>23, 645,</i> obéir à la vieillesse, se soumettre avec patience aux inconvénients de la vieillesse ; πείθεσθαι νυκτί, IL. <i>8, 502 ; 9, 65,</i> céder à l’invitation de la nuit pour cesser la lutte ; <i>avec l’acc. de la chose :</i> τινὶ πάντα πιθέσθαι, OD. <i>17, 21,</i> obéir à qqn en toute chose ; σοῖς ταῦτα πείσομαι λόγοις, ESCHL. <i>Ch. 781,</i> j’obéirai en cela à tes ordres ; <i>cf</i>. IL. <i>1, 289, etc. ;</i> OD. <i>3, 146, etc. ;</i> HDT. <i>6, 100, etc. ;</i> SOPH. <i>Ph. 1252, etc. ; en ce sens avec le gén</i>. HDT. <i>1, 126 ; 5, 29, 33 ; 6, 12 ;</i> THC. <i>7, 73 ;</i> EUR. <i>I.A. 733, etc. ; avec</i> ὥστε <i>et l’inf</i>. THC. <i>2, 2 ; avec l’inf. seul</i>. PLAT. <i>Prot. 338</i> a ; <i>abs</i>. πιθοῦ, ATT. obéis, <i>p. opp. à</i> πείθου (<i>v. ci-dessus</i> 1) ;<br><b>      3</b> <i>p. suite,</i> se fier à, croire à (à une parole) PLAT. <i>Leg. 714</i> b, <i>etc. ; avec la prop. inf</i>. OD. <i>16, 192 ; avec le dat. suivi de l’inf</i>. PLAT. <i>Phædr. 271</i> c ; <i>avec l’acc. suivi de</i> ὅπως : οὐ δυνήσομαί ποτε τὸν σὸν πιθέσθαι παῖδ' ὅπως ἐστὶν κακός, EUR. <i>Hipp. 1251,</i> je ne pourrai jamais croire que ton fils fasse le mal ; <i>avec l’acc. de la chose en quoi l’on a foi :</i> ταῦτ' ἐγῶ σοι οὐ πείθομαι, PLAT. <i>Ap. 25</i> e, je ne te crois pas sur ce point ; <i>en ce sens pf. pass</i>. πέπεισμαι, avoir été persuadé, <i>d’où</i> croire, <i>avec la prop. inf</i>. PLAT. <i>Prot. 328</i> e, <i>etc. ;</i> DÉM. <i>55, 5, etc. ; part</i>. πεπεισμένος, <i>avec le dat</i>. engagé, déterminé par, ESCHL. <i>Pers. 697 ;</i> EUR. <i>Hel. 1190, etc. ; avec</i> ἐκ <i>et le gén</i>. PLUT. <i>Rom. 14 ;</i> πεπείσμεθα περὶ ὑμῶν τὰ κρείττονα, NT. <i>Hebr. 6, 9,</i> nous nous attendons à mieux de votre part ; οἱ πεπεισμένοι, ECCL. les croyants.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. poét</i>. πειθέμεν, PD. <i>N. 7, 95. Impf. itér. 3 sg</i>. πείθεσκε, SIB. <i>1, 43. Fut. inf. épq</i>. πεισέμεν, IL. <i>5, 252. Ao.1 opt. 3 sg</i>. πείσειε, IL. <i>9, 386 ;</i> OD. <i>14, 123 ; part. dor</i>. πείσαις, PD. <i>O. 3, 16 ; part. poét</i>. πιθήσας, IL. <i>4, 398, etc. Ao.2 épq. impér</i>. πέπιθε, HH. <i>Ap. 275 ; sbj. 1 pl</i>. πεπίθωμεν, IL. <i>9, 112 ; opt</i>. πεπίθοιμι, <i>inf</i>. -εῖν, <i>part</i>. -ών, HOM. <i>etc. ; fut. ant</i>. πεπιθήσω, IL. <i>22, 223. Pf. impér</i>. πέπεισθι, ESCHL. <i>Eum. 599 ; sbj</i>. πεποίθω, ῃς, IL. <i>1, 524 ;</i> OD. <i>13, 344 ; 24, 329 ; 1 pl. épq</i>. πεποίθομεν (<i>p</i>. -ωμεν) OD. <i>10, 335 ; opt. 3 sg</i>. πεποιθοίη (<i>p</i>. -οίθοι) AR. <i>Ach. 940. Pl.q.pf. épq</i>. πεποίθεα, OD. <i>4, 434 ; 8, 181 ; 1 pl. épq. sync</i>. ἐπέπιθμεν (<i>p</i>. ἐπεποίθειμεν), IL. <i>2, 341. Moy. prés. impér. 2 sg. poét</i>. πείθεο <i>et</i> πείθεω, IL. <i>14, 235 ; opt. 3 pl</i>. πειθοίατο, IL. <i>14, 93. Fut. 2 sg</i>. πείσει, IL. <i>9, 345 ; épq</i>. πείσεαι, IL. <i>9, 74. Ao.2 ind. 3 pl</i>. ἐπίθοντο, CIA. <i>2, 38, 14 (av. 380 av. J.C.) ; v. Meisterh. p. 156, 4 ; impér</i>. πίθεο, PD. <i>P. 1, 59 ;</i> πιθοῦ, ESCHL. <i>Eum. 794 ;</i> SOPH. <i>Ant. 992 ; opt. 3 pl</i>. πιθοίατο, SIM. AM. <i>fr. 1, 22 ; opt. 3 sg. épq. avec redoubl</i>. πεπίθοιτο, IL. <i>10, 204</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. b<sup>h</sup>id<sup>h</sup>-, convaincre, avoir confiance ; <i>cf</i>. πίστις ; <i>lat</i>. fĭdēs, fīdō, fœdus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πειθω - πείθω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n56 fois dans 53 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Actes (18)</li>\n<li>Romains (5)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (4)</li>\n<li>Philippiens (7)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (4)</li>\n<li>Jacques (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3983":"<h1>peinao</h1>\n<p>Strong n° 3983 <i>Prononciation [pi-nah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faim, être affamé, avoir faim\n<ol type=\"a\">\n<li>souffrir du besoin</li>\n<li>être nécessiteux</li>\n</ol>\n</li>\n<li>métaph. implorer ardemment, chercher avec un désir ardent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεινάω-ῶ, -ῇς, ῇ</b>, <i>inf</i>. <b>-ῆν</b> <span>(<i>impf</i>. ἐπείνων, <i>f</i>. πεινήσω, <i>réc</i>. πεινάσω ; <i>ao</i>. ἐπείνησα, <i>réc</i>. ἐπείνασα ; <i>pf</i>. πεπείνηκα)</span><br><b>   I</b> avoir faim, être affamé, IL. <i>16, 758 ; 18, 162 ;</i> SOPH. <i>fr. 199 ; en parl. de pers</i>. AR. <i>Eq. 1270, etc. ;</i> XÉN. <i>Cyr. 1, 2, 11 ;</i> PLAT. <i>Gorg. 517</i> d, <i>etc. ; d’animaux,</i> IL. <i>3, 25, etc. ; de choses</i> (la terre, <i>etc</i>.) TH. <i>H.P. 8, 6, 2, avec un gén</i>. avoir faim de, OD. <i>20, 137 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> avoir faim de, <i>càd</i>. être avide de, avoir le désir de, <i>gén</i>. XÉN. <i>Conv. 4, 36 ; Cyr. 8, 3, 39 ;</i> PLAT. <i>Leg. 837</i> c ; PLUT. <i>M. 1100</i> b ; <i>avec l’acc</i>. NT. <i>Matth. 5, 6, etc. ;</i><br><b>      2</b> manquer de, avoir besoin de, <i>gén</i>. PLAT. <i>Rsp. 521</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Part. prés</i>. πεινάων <span>[ᾱ]</span> IL. <i>3, 25 ; 16, 758 ; 18, 162. Les contract. de</i> -αε- <i>sont en</i> -η- ; (πεινῇς, -ῇ, <i>inf</i>. -ῆν, <i>etc.). Prés. ind. 3 pl. dor</i>. πεινῶντι, XÉN. <i>Hell. 1, 1, 23 ; inf. épq</i>. πεινήμεναι, OD. <i>20, 137 ; inf. réc</i>. πεινᾶν, PLUT. <i>Arist. 25 ; part. dat. sg. dor</i>. πεινᾶντι, THCR. <i>Idyl. 15, 148 ; acc. épq</i>. πεινώοντα, OPP. <i>H. 5, 50. Fut. réc</i>. πεινάσω <span>[ᾱ]</span> SPT. <i>Esaï. 5, 27 ; ao. réc</i>. ἐπείνασα <span>[νᾱ]</span> Ps.-CALLISTH. <i>3, 6 ;</i> ANTH. <i>11, 402 ;</i> ES. <i>62 Halm</i>.<br><span><b>Étym</b>. πεῖνα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πειναω - πεινάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 23 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (2)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>Philippiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3984":"<h1>peira</h1>\n<p>Strong n° 3984 <i>Prononciation [pi'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une épreuve, une expérience, une tentative</li>\n<li>vérifier une chose, mettre à l'épreuve une chose ou une personne</li>\n<li>être à l'épreuve</li>\n<li>expérimenter, apprendre à connaître par l'expérience</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πειρά, ᾶς (ἡ)</b> pointe d’épée, ESCHL. <i>Ch. 860</i>.<br><span><b>Étym</b>. πείρω, περόνη.</span><br><br>\n➁ <b>πεῖρα, ας (ἡ) :<br>   I</b> épreuve, <i>càd. :</i><br><b>      1</b> expérience, tentative, essai, PD. <i>N. 9, 66, etc. ;</i> SOPH. <i>El. 471 ;</i> ἀπὸ πείρης, HDT. <i>7, 9,</i> par des épreuves faites, <i>càd</i>. avec effort, avec peine ; σφάλλεσθαι πείρᾳ τινός, THC. <i>1, 70,</i> manquer qqe ch. à l’essai, <i>càd</i>. être déçu dans une espérance ; ἐπὶ πείρᾳ, à titre d’essai, AR. <i>Av. 583 ;</i> DL. <i>6, 93 ;</i> πεῖράν τινος λαμϐάνειν, <i>souv. en prose,</i> ISOCR. <i>282</i> a ; POL. <i>2, 32, 5 ;</i> PLUT. <i>Sert. 18,</i> acquérir l’expérience de, faire un essai avec ; π. λαμϐάνειν ἐν ἑαυτῷ, XÉN. <i>An. 5, 8, 15,</i> faire une expérience sur soi-même ; <i>avec</i> εἰ, XÉN. <i>Mem. 1, 4, 18 ;</i> PLAT. <i>Theag. 129</i> d ; <i>avec</i> ὅπως, PLAT. <i>Prot. 342</i> a ; πεῖραν διδόναι, soutenir l’épreuve de, être mis à l’épreuve, <i>gén</i>. THC. <i>6, 11 ;</i> PLAT. <i>Lach. 189</i> b, <i>etc. ; abs</i>. πεῖραν ποιεῖσθαι, THC. <i>1, 53,</i> faire l’épreuve, l’essai ; <i>avec</i> εἰ, THC. <i>2, 20 ;</i> δέχεσθαι πεῖραν, PLUT. <i>Pyrrh. 5,</i> accepter une épreuve, une tentation ;<br><b>      2</b> <i>p. suite,</i> expérience acquise : πεῖραν ἔχειν, avoir l’expérience de, THC. <i>1, 140 ;</i> XÉN. <i>Cyr. 4, 1, 5, etc. ;</i> εἰς πεῖράν τινος ἔρχεσθαι, THC. <i>2, 41 ; 7, 21, etc</i>. arriver par l’expérience à la connaissance d’une personne <i>ou</i> d’une chose, apprendre à connaître qqn <i>ou</i> qqe ch. ; διὰ πείρας ἰέναι, PLAT. <i>Ax. 369</i> a, <i>m. sign. ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> essai de nuire à qqn par la ruse, ruse, tromperie, EL. <i>N.A. 1, 58 ;</i><br><b>      2</b> essai de séduire une femme, PLUT. <i>Thes. 26, Cim. 1, etc. ;</i><br><b>      3</b> <i>en gén</i>. proposition, projet, entreprise, ESCHL. <i>Pers. 719 ;</i> SOPH. <i>Aj. 2 ;</i> πεῖραν ἀφορμᾶν, SOPH. <i>Aj. 290,</i> partir pour une entreprise.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πείρη, HDT. <i>l. c. etc. ;</i> THGN. <i>563 ;</i> THCR. <i>Idyl. 15, 61</i>.<br><span><b>Étym</b>. <i>p</i>. *πέρ-ϳα, <i>de la R. indo-europ</i>. *per-, traverser, passer ; <i>cf</i>. πείρω, περάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πειρα - πεῖρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G3985":"<h1>peirazo</h1>\n<p>Strong n° 3985 <i>Prononciation [pi-rad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>essayer si une chose peut être faite\n<ol type=\"a\">\n<li>tenter, s'efforcer</li>\n</ol>\n</li>\n<li>essayer, éprouver, dans le but de certifier une quantité, ou ce que pense l'autre, ou comment il se conduit\n<ol type=\"a\">\n<li>dans un bon sens</li>\n<li>dans un mauvais sens, éprouver malicieusement, astucieusement pour prouver ses sentiments ou jugements</li>\n<li>essayer ou éprouver la foi, la vertu, le caractère, par la séduction du péché\n<ol>\n<li>solliciter à pécher, tenter\n<ol type=\"a\">\n<li>des tentations du diable</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>après l'A.T.\n<ol>\n<li>de Dieu : infliger des maux dans le but d'éprouver un caractère et la constance de la foi</li>\n<li>il est dit que les hommes veulent tenter Dieu en montrant leur méfiance, par une conduite impie ou méchante, pour éprouver la justice et la patience de Dieu, et le défier, comme s'il avait à donner une preuve de ses perfections.</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πειράζω</b> (<i>seul. prés., impf. et ao</i>. ἐπείρασα <span>[ρᾰ]</span>) essayer, tenter, <i>càd. :</i><br><b>      1</b> faire l’épreuve <i>ou</i> l’expérience de, <i>avec un gén. de pers</i>. OD. <i>16, 319 ; 23, 114, ou de chose,</i> A. RH. <i>1, 495 ; abs</i>. OD. <i>9, 281 ; avec un acc. de chose,</i> LUC. <i>Am. 26, etc. ; avec l’inf</i>. NT. <i>Ap. 16, 7, etc. ;</i><br><b>      2</b> <i>en mauv. part :</i> tenter, chercher à séduire <i>ou</i> à corrompre, <i>acc</i>. A. RH. <i>3, 10 ;</i> NT. <i>Ap. 15, 10, etc. ;</i> ὁ πειράζων, NT. <i>1Thess. 3, 5,</i> le tentateur, le mauvais esprit ; <i>au pass</i>. être tenté, NT. <i>Matth. 4, 1 ;</i><br><b>      3</b> éprouver, <i>en parl. d’une maladie, d’où au pass</i>. πειράζεσθαι, A. APHR. <i>Probl. 2, 54, etc</i>. être éprouvé par une maladie.<br><span><b>Étym</b>. πεῖρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πειραζω - πειράζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n38 fois dans 34 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (4)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (4)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G3986":"<h1>peirasmos</h1>\n<p>Strong n° 3986 <i>Prononciation [pi-ras-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une expérience, une épreuve, une tentation\n<ol type=\"a\">\n<li>épreuve : celle qui est faite de vous par ma condition corporelle comme cette condition a servi à éprouver l'amour des Galates envers Paul (<a class=\"ref\" data-r=\"GAL4.14\">Galates 4.14</a>).</li>\n<li>l'épreuve de la fidélité de l'homme, son intégrité, sa vertu, sa constance\n<ol>\n<li>une séduction du péché, tentation, survenant de désirs ou de circonstances extérieures</li>\n<li>une tentation interne au péché\n<ol type=\"a\">\n<li>la tentation par laquelle le diable voulait faire dévier Jésus de sa course divine</li>\n</ol>\n</li>\n<li>de conditions de choses, ou un état mental, par quoi nous sommes poussés à pécher, ou vers un manquement à la foi et à la sainteté</li>\n<li>adversité, affliction, malheur : envoyés par Dieu pour éprouver un caractère, la foi, la sainteté</li>\n</ol>\n</li>\n<li>tentation (épreuve) de Dieu par les hommes\n<ol>\n<li>rébellion contre Dieu, moyens par lesquels son pouvoir et sa justice sont mis à l'épreuve, comme si cela était possible.</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πειρασμός, οῦ (ὁ) :<br>      1</b> épreuve, essai, expérience, SPT. <i>Sir. 6, 7 ;</i> NT. <i>1Petr. 4, 12 ;</i><br><b>      2</b> tentation, ORIG. <i>1, 456 Migne, etc</i>.<br><span><b>Étym</b>. πειράζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πειρασμος - πειρασμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 20 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (6)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3987":"<h1>peirao</h1>\n<p>Strong n° 3987 <i>Prononciation [pi-rah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre à l'épreuve, tenter de, éprouver\n<ol type=\"a\">\n<li>expérimenté</li>\n</ol>\n</li>\n<li>mettre quelqu'un à l'épreuve, le forcer à prouver\n<ol type=\"a\">\n<li>son esprit, ses sentiments, son humeur</li>\n<li>dans certains cas, tenter de pousser au crime</li>\n<li>tenté au péché</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πειράω-ῶ</b> <span>(<i>impf</i>. ἐπείρων, <i>f</i>. πειράσω, <i>ao</i>. ἐπείρασα, <i>pf</i>. πεπείρακα ; <i>pass. f</i>. πειραθήσομαι, <i>ao</i>. ἐπειράθην, <i>pf</i>. πεπείραμαι)</span> tenter, <i>càd. :</i><br><b>A <i>tr. :</i><br>   I</b> essayer, tenter, s’efforcer, <i>avec l’inf</i>. IL. <i>8, 8 ; 19, 30 ;</i> HDT. <i>5, 85 ; 6, 84 ;</i> SOPH. <i>O.R. 399, etc. ;</i> THC. <i>1, 50, etc. ; avec</i> ὡς, IL. <i>4, 66, 71 ; 9, 181 ; 21, 459 ;</i> OD. <i>2, 316 ; avec</i> ὅπως, OD. <i>4, 545 ;</i><br><b>   II</b> <i>avec un gén. de pers. ou de chose :</i> faire un essai <i>ou</i> une expérience sur qqn, <i>càd</i>. mettre à l’épreuve, IL. <i>24, 390 ;</i> chercher à engager à, IL. <i>9, 345 ; avec idée d’hostilité,</i> s’essayer contre qqn, se mesurer avec qqn, IL. <i>12, 301 ;</i> OD. <i>6, 134 ;</i> THC. <i>7, 38 ;</i> πόλιος πειρᾶν, HDT. <i>6, 82,</i> tâter une ville pour s’en emparer <i>ou</i> la surprendre ; χωρίου, THC. <i>1, 61 ; 4, 70 ; 7, 12,</i> faire une tentative sur une place forte ;<br><b>   III</b> <i>après Hom. avec l’acc. :</i><br><b>      1</b> <i>avec un acc. de pers</i>. tenter, induire en tentation : τοὺς φίλους ἐπὶ Καίσαρα, PLUT. <i>Brut. 10,</i> éprouver les sentiments des amis à l’égard de César, les exciter contre lui ; <i>particul</i>. essayer de corrompre, de séduire (une femme, une jeune fille, un jeune garçon) LYS. <i>92, 40 ;</i> AR. <i>Pl. 1067 ;</i> PLAT. <i>Phædr. 227</i> c ; PLUT. <i>Galb. 19, etc. ; au pass</i>. THC. <i>6, 54 ; en parl. des animaux,</i> PLUT. <i>M. 990</i> c, <i>etc. ;</i><br><b>      2</b> <i>avec un acc. de chose :</i> πάντα π. PLUT. <i>M. 1122</i> a, tenter tout, employer tous les moyens ;<br><b>B <i>intr.</i></b> tenter la fortune dans les aventures, <i>particul</i>. s’adonner au brigandage, se faire brigand, HH. <i>Merc. 175 ;</i><br><b><i>Moy</i>. πειράομαι-ῶμαι</b> <span>(<i>f</i>. άσομαι, <i>ao</i>. ἐπειρασάμην)</span><br><b>   I</b> <i>abs</i>. tenter pour soi, faire un essai, faire une épreuve, OD. <i>21, 394 ;</i> s’essayer, s’exercer, IL. <i>16, 590 ;</i> περί τινος, IL. <i>23, 553,</i> tenter l’épreuve pour le prix du combat, s’efforcer d’obtenir le prix ;<br><b>   II</b> <i>en gén</i>. éprouver, tenter, entreprendre, <i>avec l’inf</i>. IL. <i>4, 5 ; 12, 341 ;</i> HDT. <i>6, 138 ; 8, 100, etc. ;</i> ESCHL. <i>Pers. 850, etc. ;</i> SOPH. <i>Ph. 149, etc. ;</i> XÉN. <i>Cyr. 1, 6, 16, etc. ;</i> PLAT. <i>Conv. 212</i> b ; <i>avec le part</i>. OD. <i>21, 184 ;</i> HDT. <i>1, 77 ; 7, 148, cf. 1, 84 ; 6, 5, 50, etc. ;</i> PLAT. <i>Phil. 21</i> a, <i>etc. ; avec des particules :</i> π. εἰ, IL. <i>13, 806 ;</i> PLAT. <i>Phæd. 95</i> b ; <i>avec</i> αἴκε <i>et le sbj</i>. IL. <i>18, 601 ; avec</i> ἐάν, ESCHL. <i>Pr. 325 ;</i> PLAT. <i>Leg. 638</i> e ; <i>avec</i> ὅπως, XÉN. <i>An. 3, 2, 3 ; avec</i> μή, dans la crainte que, OD. <i>21, 395 ; avec un gén. de pers. :</i><br><b>      1</b> tenter qqn, mettre qqn à l’épreuve ; <i>particul. pour éprouver sa fidélité ou sa véracité, p. suite,</i> pressentir, interroger, IL. <i>10, 444, etc. ;</i> OD. <i>13, 336 ; 23, 181, etc. ; suivi de</i> εἰ, OD. <i>19, 215 ; au sens phys</i>. s’essayer <i>ou</i> se mesurer avec, IL. <i>21, 225, 580 ;</i> OD. <i>8, 23 ;</i> HDT. <i>1, 76 ; 2, 163 ; et dans les écriv. postér.,</i> A. RH. <i>3, 147, etc. ;</i><br><b>      2</b> <i>p. suite,</i> faire l’expérience que, reconnaître par expérience que : πειρώμενος ἀνδρὸς ἀγαθοῦ καὶ νοῦν ἔχοντος, PLUT. <i>Arat. 43,</i> reconnaissant après expérience que l’homme était honnête et sensé ; <i>cf</i>. PLUT. <i>Æmil. 8, etc. ;</i><br><b>   III</b> <i>avec un gén. de chose,</i> essayer sur soi-même, éprouver pour soi : σθένεος, IL. <i>15, 359 ;</i> OD. <i>21, 282,</i> sa propre force ; ἔργου, OD. <i>18, 369 ;</i> ἀέθλου, IL. <i>23, 707, etc. ;</i> OD. <i>8, 100, etc. ;</i> μάχας, PD. <i>N. 1, 65,</i> s’essayer dans un travail, à la lutte, dans un combat, <i>etc. ;</i> τείχους, THC. <i>2, 81,</i> donner l’assaut aux murs ; τόξου, OD. <i>21, 159, etc</i>. essayer un arc ; ὀϊστοὶ τῶν τάχ' ἔμελλον πειρήσεσθαι, OD. <i>21, 418,</i> traits dont ils devaient bientôt faire l’épreuve, <i>càd</i>. dont ils devaient bientôt apprendre à connaître par leur propre expérience la force meurtrière ; <i>cf</i>. HÉS. <i>Sc. 359 ;</i> XÉN. <i>An. 3, 2, 38, etc. ; de même avec une nuance d’ironie,</i> tâter (du pouvoir, de la servitude, <i>etc</i>.) THC. <i>2, 44 ; 5, 69 ;</i> PLUT. <i>Ant. 25, etc. ; p. suite, au pf</i>. avoir appris par expérience, <i>d’où</i> connaître <i>ou</i> savoir par expérience, HDT. <i>9, 46, etc. ;</i> PLAT. <i>Ep. 323</i> a, <i>etc. ;</i> πεπειραμένος οἶδα, XÉN. <i>Hier. 2, 6,</i> je sais cela par expérience ;<br><b>   IV</b> <i>avec le dat</i>. ἔπεσι, IL. <i>2, 73,</i> essayer par des paroles <i>ou</i> avec des paroles ; ποσί, OD. <i>8, 120, etc</i>. s’essayer avec les pieds, <i>càd</i>. lutter de vitesse à la course ; πειρηθῆναι ἐν ἔντεσι, IL. <i>19, 384,</i> essayer des armes pour voir si elles vont bien au corps ; <i>ou</i> σὺν ἔντεσι, IL. <i>5, 220, etc</i>. s’essayer dans les armes, <i>càd</i>. montrer ce qu’on est capable de faire ; <i>p. suite, au pf</i>. s’être essayé, <i>d’où</i> être exercé, expérimenté : μύθοις, OD. <i>3, 23,</i> en paroles ;<br><b>   V</b> <i>avec l’acc</i>. ἕκαστα π. OD. <i>4, 119 ; 24, 238,</i> scruter chaque chose.<br><span><b><span class=\"arrow\"></span></b> <i>Pass.-moy. prés. opt. 3 pl</i>. πειρῴατο, HDT. <i>1, 68. Fut. dor</i>. πειρασοῦμαι <span>[ᾱ]</span> AR. <i>Ach. 743 ;</i> HIPPODAM. (STOB. <i>43, 93) ; ao</i>. ἐπειράθην, <i>d’ord. au sens moy. ; rar. au sens pass</i>. THC. <i>6, 54. Formes épq. et ion. en</i> η : <i>f</i>. πειρήσω, IL. <i>19, 30 ; ao</i>. πείρησα, A. RH. <i>3, 1249 ; au pass</i>. ἐπειρήθην, HDT. <i>3, 152, etc. ; pl.q.pf. 3 pl</i>. ἐπεπειρέατο (<i>p</i>. ἐπεπείρηντο) HDT. <i>7, 125 ; ao. moy. sbj. 3 sg. épq</i>. πειρήσεται (<i>p</i>. πειρήσηται) OD. <i>21, 159</i>.<br><span><b>Étym</b>. πεῖρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πειραω - πειράω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3988":"<h1>peismone</h1>\n<p>Strong n° 3988 <i>Prononciation [pice-mon-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>persuasion</li>\n<li>persuasion traître ou trompeuse, mauvaise influence</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεισμονή, ῆς (ἡ)</b> persuasion, <i>d’où</i> confiance, NT. <i>Gal. 5, 7</i>.<br><span><b>Étym</b>. πείθω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεισμονη - πεισμονή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G3989":"<h1>pelagos</h1>\n<p>Strong n° 3989 <i>Prononciation [pel'-ag-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la mer</li>\n<li>la haute mer, les profondeurs (où voguent les navires)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέλαγος, εος-ους (τὸ)</b> <span>[ᾰ]</span><br><b>      1</b> la pleine mer, IL. <i>14, 16 ;</i> OD. <i>3, 179, 321 ;</i> PD. <i>O. 7, 103 ;</i> THC. <i>8, 80, etc. ;</i> πέλαγος θαλάσσης, A. RH. <i>2, 608 ;</i> ἁλὸς πελάγεα, OD. <i>5, 335 ;</i> HH. <i>Ap. 73, etc</i>. le plein de la mer, la haute mer ; <i>p. anal. en parl. d’une plaine inondée,</i> HDT. <i>2, 97 ; fig</i>. πέλαγος κακῶν, ESCHL. <i>Pers. 433 ;</i> ἄτης, ESCHL. <i>Suppl. 470, etc</i>. un océan de maux, un abîme de malheur, <i>etc. ; en parl. d’une entreprise,</i> SOPH. <i>O.C. 663 ; de difficultés,</i> SOPH. <i>O.C. 1746 ;</i><br><b>      2</b> <i>particul</i>. une mer, <i>p. opp. à</i> θάλασσα, la mer <i>en gén. :</i> π. Αἰγαῖον, ESCHL. <i>Ag. 659 ;</i> SOPH. <i>Aj. 461,</i> la mer Égée : τὸ Τυρσηνικὸν π., τὸ Σικελικὸν π. THC. <i>4, 24,</i> la mer de Tyrrhénie, la mer de Sicile.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. sg. ion</i>. πελάγεϊ, HDT. <i>8, 60 ; gén. plur. ion. et poét</i>. πελαγέων, HDT. <i>4, 85 ;</i> SOPH. <i>Aj. 702 ; par contract</i>. πελαγῶν, THC. <i>4, 21 ; dat. pl. épq</i>. πελάγεσσι, PD. <i>P. 4, 447 ;</i> πελάγεσσιν, OD. <i>5, 335, etc</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πελαγος - πέλαγος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3990":"<h1>pelekizo</h1>\n<p>Strong n° 3990 <i>Prononciation [pel-ek-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>trancher avec une hache, décapiter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πελεκίζω</b>, frapper de la hache, <i>particul</i>. décapiter, <i>acc</i>. POL. <i>1, 7, 12, etc. ;</i> STR. <i>735, etc</i>.<br><span><b>Étym</b>. πέλεκυς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πελεκιζω - πελεκίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3991":"<h1>pemptos</h1>\n<p>Strong n° 3991 <i>Prononciation [pemp'-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cinquième</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πεμπτός, ή, όν</b>, envoyé, THC. <i>8, 86</i>.<br><span><b>Étym</b>. <i>vb. de</i> πέμπω.</span><br><br>\n➁ <b>πέμπτος, η, ον</b>, cinquième : π. μετὰ τοῖσι, OD. <i>9, 335,</i> moi cinquième avec ceux-là, <i>càd</i>. avec quatre autres ; π. αὐτός, THC. <i>1, 61, etc. m. sign. ;</i> π. σπιθαμή, HDT. <i>2, 106,</i> deux aunes et demie ; ἡ πέμπτη (<i>s.-e</i>. ἡμέρα) HÉS. <i>O. 800, 801 ;</i> AR. <i>Nub. 1131,</i> le cinquième jour ; (<i>s.-e</i>. ὁδός) POL. <i>6, 30, 6,</i> la via quintana (<i>rue où l’on vendait les vivres) dans le camp romain</i>.<br><span><b>Étym</b>. πέντε, <i>cf. lat</i>. quīntus <i>p</i>. quīnctus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεμπτος - πέμπτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G3992":"<h1>pempo</h1>\n<p>Strong n° 3992 <i>Prononciation [pem'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envoyer\n<ol type=\"a\">\n<li>faire qu'une chose soit transportée vers quelqu'un</li>\n<li>envoyer (pousser ou insérer) une chose dans une autre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέμπω</b> <span>(<i>impf</i>. ἔπεμπον, <i>f</i>. πέμψω, <i>ao</i>. ἔπεμψα, <i>pf</i>. πέπομφα, <i>pl.q.pf</i>. ἐπεπόμφειν ; <i>pass. f</i>. πεμφθήσομαι, <i>ao</i>. ἐπέμφθην, <i>pf</i>. πέπεμμαι, πέπεμψαι, πέπεμπται, <i>etc., pl.q.pf</i>. ἐπεπέμμην)</span><br><b>      1</b> envoyer, <i>acc</i>. IL. <i>3, 116 ;</i> HDT. <i>7, 15 ;</i> XÉN. <i>An. 2, 3, 1, etc. ;</i> SOPH. <i>O.R. 288 ; en parl. d’une armée, de troupes, etc</i>. ESCHL. <i>Pers. 54, etc. ;</i> XÉN. <i>Cyr. 1, 5, 4 ; 2, 4, 14 ; An. 4, 6, 19, etc. ; en parl. de choses</i> (vents qui emportent dans l’espace, ESCHL. <i>Pr. 131 ;</i> vaisseaux qui transportent qqn, OD. <i>8, 556 ;</i> ESCHL. <i>Suppl. 135, etc.) ; avec double accus. :</i> π. τινὰ ὁδόν, SOPH. <i>Aj. 739, etc</i>. envoyer qqn faire un voyage ; <i>de même en parl. de choses que l’on envoie, que l’on donne à emporter</i> (vêtements, vivres, OD. <i>16, 83 ;</i> présents, HDT. <i>7, 106 ;</i> XÉN. <i>Cyr. 3, 1, 42, etc.) ; fig</i>. κακόν τινι, IL. <i>15, 108, etc</i>. causer du mal à qqn ; φόϐον, PLAT. <i>Tim. 40</i> d, causer de la crainte ; ὀνείρατα, SOPH. <i>El. 460,</i> envoyer des songes ; ὕπνον, SOPH. <i>Ph. 19,</i> le sommeil ; οἰωνόν, IL. <i>24, 310,</i> un présage ; ἀγγέλους, φήμας καὶ ἐνύπνια καὶ οἰωνούς, XÉN. <i>Conv. 4, 48,</i> des nouvelles, des bruits, des songes et des présages ; ὄλϐον, PD. <i>O. 2, 37 ;</i> ἀλκάν, SOPH. <i>O.R. 189,</i> du bonheur, de la force ; <i>le n. du lieu vers lequel on envoie se construit à l’accus. :</i> πέμπειν Θήϐας, SOPH. <i>O.C. 1770,</i> ἀγρούς, SOPH. <i>O.R. 761,</i> envoyer à Thèbes, à la campagne ; <i>avec une prép. :</i> π. ἐς Τροίην, IL. <i>6, 207,</i> envoyer à Troie ; ἐς πόλεμον, IL. <i>18, 237,</i> à la guerre ; ἐς πατρίδα, OD. <i>17, 149,</i> dans sa patrie ; εἰς Ἀΐδαο, IL. <i>21, 48,</i> dans le séjour d’Hadès, <i>càd</i>. tuer ; εἰς διδασκάλων, PLAT. <i>Prot. 325</i> d, à l’école ; π. πρός τινα, XÉN. <i>An. 5, 2, 6, etc. ;</i> παρά τινα, THC. <i>2, 80 ;</i> ὥς τινα, THC. <i>8, 50,</i> envoyer vers qqn, auprès de qqn ; π. ἐπί τινα, THC. <i>6, 61,</i> envoyer chercher qqn ; ἐπὶ βοήθειαν, XÉN. <i>Hell. 5, 4, 10,</i> envoyer chercher du secours ; τι ἐπί τινι, IL. <i>2, 6,</i> envoyer qqe ch. à qqn ; ἐπὶ πολέμῳ, XÉN. <i>Hell. 4, 8, 17,</i> envoyer pour exciter à la guerre (<i>litt</i>. en vue de la guerre) ; π. περὶ συμμαχίας, XÉN. <i>Cyr. 6, 2, 11 ;</i> περὶ σπονδῶν, XÉN. <i>An. 2, 3, 1,</i> envoyer pour discuter sur une alliance, sur un traité ; <i>de même avec un adv. :</i> π. πόλεμόνδε, IL. <i>18, 452,</i> envoyer au combat ; ὅνδε δόμονδε, IL. <i>16, 445 ;</i> οἶκόνδε, OD. <i>24, 418 ;</i> οἴκαδε, OD. <i>19, 281,</i> envoyer dans sa demeure, dans ses foyers ; <i>avec un inf. :</i> π. τινὰ νέεσθαι, OD. <i>13, 206,</i> envoyer qqn retourner dans son pays ; ἰέναι, OD. <i>14, 396 ;</i> ἱκάνειν, OD. <i>4, 29 ;</i> ἄγειν, OD. <i>24, 419 ;</i> φέρειν, IL. <i>16, 454, etc</i>. envoyer qqn pour aller, pour venir, pour conduire, pour porter, <i>etc. ; abs. (s.-e</i>. πρέσϐεις, ἄγγελον, <i>etc.) d’ord. au part. ou accompagné d’un part. :</i> πέμπει κελεύων, THC. <i>4, 93 ;</i> πέμπων ἐκέλευε, XÉN. <i>An. 2, 3, 1,</i> il envoie, il envoyait l’ordre <i>ou</i> l’invitation ; ἔπεμπε πρὸς Κῦρον δεόμενος, XÉN. <i>Cyr. 1, 5, 4,</i> il envoyait vers Cyrus demandant, pour demander ; πέμψας ἐδεῖτο, XÉN. <i>An. 7, 1, 2,</i> il envoyait pour demander, <i>etc. ;</i> ἔπεμψε παραδιδούς, PLUT. <i>Tim. 13,</i> il envoya déclarer qu’il voulait remettre ; <i>d’où abs</i>. envoyer dire : πέμπεις σῇ δάμαρτι παῖδα σὴν δεῦρ' ἀποστέλλειν, EUR. <i>I.A. 360,</i> tu mandes à ton épouse d’envoyer ta fille ici ; <i>cf</i>. XÉN. <i>Hell. 3, 1, 7 ;</i><br><b>      2</b> renvoyer, congédier, faire partir <i>ou</i> laisser partir ; <i>particul</i>. renvoyer à la maison, renvoyer dans sa patrie, IL. <i>24, 780 ;</i> OD. <i>4, 29 ; 5, 140, etc. ;</i> HDT. <i>1, 116 ; en parl. d’un hôte qu’on laisse partir,</i> OD. <i>15, 74 ; du père qui laisse partir sa fille pour aller dans la maison de son époux,</i> OD. <i>4, 5, 8, etc. ;</i><br><b>      3</b> escorter, accompagner, IL. <i>1, 390 ;</i> OD. <i>16, 228, etc. ;</i> SOPH. <i>Ph. 1368, etc. ; en parl. des dieux qui accompagnent un mortel,</i> OD. <i>11, 626 ;</i> XÉN. <i>Cyr. 1, 6, 2 ; particul</i>. suivre dans un cortège solennel, ESCHL. <i>Eum. 12, Suppl. 219 ;</i> πομπὴν πέμπειν, faire une procession, HDT. <i>5, 56 ;</i> THC. <i>6, 56 ;</i> XÉN. <i>Hipp. 2, 1 ;</i> PLAT. <i>Rsp. 327</i> a, <i>etc. ;</i> π. θρίαμϐον, PLUT. <i>Æmil. 32, etc</i>. mener un cortège triomphal, célébrer un triomphe ; τὰ ἐπινίκια, DC. <i>36, 18, m. sign. ; au pass</i>. être conduit <i>ou</i> porté processionnellement, HDT. <i>2, 49 ;</i> PLUT. <i>Demetr. 12 ;</i><br><b><i>Moy</i>. πέμπομαι</b> <span>(<i>ao</i>. ἐπεμψάμην)</span><br><b>      1</b> envoyer après qqn, mander, faire venir, <i>acc</i>. SOPH. <i>O.C. 602 ;</i> EUR. <i>Hec. 977 ;</i><br><b>      2</b> πέμπεσθαί τινα ἐπί τινα, envoyer qqn vers qqn pour une affaire qui vous est propre, SOPH. <i>O.R. 556 ;</i><br><b>      3</b> πέμπεσθαί τινα <i>ou</i> τι, envoyer à qqn ce qui vous appartient en propre ; πέμψομαί γε θυγατέρα, EUR. <i>Or. 111,</i> j’enverrai ma fille ; πεμπομένη τὴν ἅϐραν, LUC. <i>Tox. 14,</i> envoyant sa suivante.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. part. fém. dor</i>. πέμποισα, PD. <i>O. 6, 32 ; inf. épq</i>. πεμπέμεναι, OD. <i>13, 48, ou</i> -έμεν, OD. <i>10, 18. Impf. itér. 3 sg</i>. πέμπεσκε, HDT. <i>7, 106. Fut. dor</i>. πεμψῶ, THCR. <i>Idyl. 5, 141 ; inf. épq</i>. πεμψέμεναι, OD. <i>10, 484. Moy. ao. opt. 3 pl</i>. πεμψαίατο, SOPH. <i>O.C. 602</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεμπω - πέμπω</font>\n<br><br>apparemment un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – est le terme général et peut même impliquer un accompagnement (comme par exemple envoyé de Dieu)\n<br><br> – comprend la référence à un équipement et suggère un envoi officiel ou autoritaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n80 fois dans 79 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (10)</li>\n<li>Jean (33)</li>\n<li>Actes (12)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (5)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G3993":"<h1>penes</h1>\n<p>Strong n° 3993 <i>Prononciation [pen'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pauvre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πένης, ητος</b>, <i>adj. m</i>. pauvre, indigent (<i>propr</i>. qui travaille pour vivre) HDT. <i>8, 51 ;</i> SOPH. <i>Ph. 584 ; p. opp. à</i> πλούσιος, XÉN. <i>An. 7, 7, 28 ; Mem. 4, 2, 37 ;</i> PLAT. <i>Prot. 319</i> d, <i>etc. ; différ. de</i> πτωχός, AR. <i>Pl. 552 ; joint à</i> φειδωλός, PLAT. <i>Leg. 719</i> e ; <i>à</i> ἄπορος, PLAT. <i>Rsp. 552</i> a ; <i>en parl. de choses (maison,</i> EUR. <i>El. 1139 ; corps,</i> EUR. <i>El. 372, etc.) ; avec un gén</i>. pauvre de, qui manque de, EUR. <i>El. 38 ;</i> PLAT. <i>Ep. 332</i> c ; LUC. <i>Apol. 11</i>.<br><span>•<i> Cp</i>. πενέστερος, XÉN. <i>Ath. 1, 13 ;</i> <i>• Sup</i>. πενέστατος, DÉM. <i>555, 11</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Avec un n. neutre</i> ἐν πένητι σώματι, EUR. <i>El. 372</i>.<br><span><b>Étym</b>. πένομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πενης - πένης</font>\n<br><br>vient du mot primaire peno (peiner pour une subsistance quotidienne)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – celui qui est si pauvre qu'il gagne son pain par un labeur quotidien\n<br><br> – celui qui obtient sa subsistance par mendicité</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3994":"<h1>penthera</h1>\n<p>Strong n° 3994 <i>Prononciation [pen-ther-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>belle-mère, la mère de l'épouse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πενθερά, ᾶς (ἡ)</b> belle-mère, DÉM. <i>1123, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πενθερή, CALL. <i>Dian. 149</i>.<br><span><b>Étym</b>. <i>fém. de</i> πενθερός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πενθερα - πενθερά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G3995":"<h1>pentheros</h1>\n<p>Strong n° 3995 <i>Prononciation [pen-ther-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>beau-père, le père de l'épouse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πενθερός, οῦ (ὁ)</b> <i>propr</i>. qui contracte un lien de famille par mariage :<br><b>      1</b> beau-père, père de la femme, IL. <i>6, 170 ;</i> OD. <i>8, 582 ;</i> HDT. <i>3, 52, etc. ;</i> père du mari, SPT. <i>Gen. 38, 13 ; plur</i>. οἱ π. EUR. <i>Hipp. 636,</i> les beaux-parents ;<br><b>      2</b> beau-frère, mari de la sœur, EUR. <i>El. 1286 ;</i><br><b>      3</b> gendre, SOPH. <i>fr. 293 Dind</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. b<sup>h</sup>end<sup>h</sup>-, lier, <i>sscr</i>. bándh-u-, parent, <i>litt</i>. celui qui contracte par alliance un lien de parenté.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πενθερος - πενθερός</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3996":"<h1>pentheo</h1>\n<p>Strong n° 3996 <i>Prononciation [pen-theh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pleurer</li>\n<li>affliger, se lamenter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πενθέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἐπένθησα, <i>pf</i>. πεπένθηκα ; <i>pass. seul. prés</i>.)</span><br><b>      1 <i>tr.</i></b> pleurer, déplorer, <i>acc</i>. IL. <i>19, 225 ;</i> ORACL. (HDT. <i>7, 220</i>) ; ESCHL. <i>Pers. 579 ;</i> SOPH. <i>O.R. 1320, etc. ;</i> EUR. <i>Med. 268 ;</i> XÉN. <i>Hell. 2, 2, 3 ;</i><br><b>      2 <i>intr.</i></b> être dans le deuil, pleurer, OD. <i>18, 174 ; 19, 120 ;</i> ESCHL. <i>Pers. 545, etc. ;</i> PLAT. <i>Phædr. 258</i> b, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 3 duel épq</i>. πενθείετον (<i>p</i>. -έετον) IL. <i>23, 283 ; inf. épq</i>. πενθήμεναι, OD. <i>18, 174 ; 19, 120</i>.<br><span><b>Étym</b>. πένθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πενθεω - πενθέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G3997":"<h1>penthos</h1>\n<p>Strong n° 3997 <i>Prononciation [pen'-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>deuil, affliction</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πένθος, εος-ους (τὸ) :<br>   I</b> deuil, <i>càd. :</i><br><b>      1</b> douleur, affliction : π. τινός, OD. <i>18, 324, etc</i>. deuil au sujet de qqn ; π. ἔχειν, IL. <i>24, 105,</i> être dans le deuil ; π. ἔχει τινά, PLUT. <i>Cæs. 23, etc. ; ou</i> λαμϐάνει, IL. <i>16, 548,</i> la douleur possède qqn <i>ou</i> s’empare de qqn ; ἐν πένθει εἶναι, SOPH. <i>El. 290, etc. ;</i> PLAT. <i>Rsp. 605</i> d, être dans le deuil ; πολὺ πένθος ἦν κατὰ τὸ στράτευμα, XÉN. <i>Hell. 4, 5, 10,</i> il y avait un grand deuil dans l’armée ; πένθος λύεσθαι, ἀποθέσθαι, PLUT. <i>Fab. 18, Alex. 75,</i> s’affranchir d’un deuil, déposer le deuil ; ἐπὶ πένθει, PLUT. <i>Ages. 29, Cic. 31,</i> dans le deuil ; τινὶ πένθος τιθέναι, IL. <i>17, 37 ; ou</i> παρέχειν, ESCHL. <i>Pers. 322,</i> être cause d’un deuil pour qqn ; <i>au plur</i>. PD. <i>fr. 119 (126) 4 Bgk ;</i> ESCHL. <i>Ch. 83, etc. ; joint à</i> θρῆνοι, ARSTT. <i>Rhet. 1, 11 ; à</i> ξυμφοραί, PLAT. <i>Rsp. 395</i> d ;<br><b>      2</b> cérémonie de deuil, deuil public : πένθος ποιήσασθαι, HDT. <i>2, 1,</i> organiser un deuil de cour ; <i>cf</i>. HDT. <i>6, 21 ;</i><br><b>   II</b> malheur, événement douloureux, PD. <i>I. 7 (6) 51 ;</i> HDT. <i>3, 14</i>.<br><span><b>Étym</b>. πάσχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πενθος - πένθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jacques (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G3998":"<h1>penichros</h1>\n<p>Strong n° 3998 <i>Prononciation [pen-ikh-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>nécessiteux, pauvre, indigent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πενιχρός, ά, όν</b> <span>[ῑ]</span> pauvre, indigent, OD. <i>3, 348 ;</i> THGN. <i>165, 181 ;</i> PD. <i>N. 7, 27 ;</i> AR. <i>Pl. 976 ;</i> PLAT. <i>Rsp. 578</i> a.<br><span>•<i> Sup</i>. -ότατος, POL. <i>6, 2, 17</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῐ]</span> PD. AR. <i>ll. cc. ;</i> MAN. <i>2, 416</i>.<br><span><b>Étym</b>. πένης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πενιχρος - πενιχρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3999":"<h1>pentakis</h1>\n<p>Strong n° 3999 <i>Prononciation [pen-tak-ece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cinq fois</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεντάκις</b> <span>[ᾰῐ]</span> <i>adv</i>., cinq fois, PD. <i>N. 6, 33 ;</i> ESCHL. <i>Pers. 323 ;</i> AR. <i>Pax 242 ;</i> ISOCR. <i>83</i> b.<br><span><b>Étym</b>. π. -άκις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεντακις - πεντάκις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>"};
